// ==========================================
// ★ K 의 방 — A등급 직업 갈림길 · 감각
// 탐험가 · 사수 · 추적자 · 탐지술사 · 보물사냥꾼
// ==========================================

// ------------------------------------------
// 탐험가 (explorer) · 자원 없음
// ------------------------------------------
kJob('explorer', 'A', [
{ at:'A', t:'돌아가는 길 — 늘어난 걸음',
  x:`들어올 때 이 복도는 마흔 걸음이었다. 탐험가는 어디서든 걸음을 센다.<br><br>
    돌아가는 길이다. 마흔 걸음을 걸었다. 끝이 안 나온다.<br>
    마흔하나. 마흔둘. 복도는 곧다. 꺾인 데가 없다.<br><br>
    등 뒤에서 누가 같이 센다. 아주 작게. 하나 늦게.`,
  o:[
    { l:'① 멈춰 서서 늘어난 자리를 찾는다.', k:'sense', dc:22,
      ok:`멈췄다. 뒤에서 세던 소리도 멈췄다.<br><br>벽을 짚으며 한 걸음씩 되짚었다. 바닥 이음매 간격이 고르다. 서른일곱째에서만 한 뼘 넓다. 들어올 때 없던 한 뼘이다.<br>그 한 뼘을 밟지 않고 건넜다. 일행에게도 건너뛰게 했다. 마흔 걸음 끝에 문이 있었다.<br><br>걸음은 이제 숫자가 아니다. 발바닥이 길이를 기억한다. 틀린 한 뼘은 발이 먼저 안다.`,
      ng:`되짚는 사이 세는 소리가 다시 시작됐다. 이번엔 이쪽보다 하나 빠르다.<br><br>그 소리에 맞춰 발이 나간다. 멈추려 해도 박자가 끌어당긴다. 쉰. 쉰하나.<br>일행이 허리띠를 잡아당겨서야 섰다. 발목이 접질렸다. 뒤에서 세는 소리가 실망한 듯 끊겼다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16 }, wake:1 },
    { l:'② 벽에 손을 대고 눈을 감은 채 걷는다.', k:'steady', dc:21,
      ok:`왼손을 벽에 붙이고 눈을 감았다. 숫자를 버렸다.<br><br>벽이 차다. 손바닥 밑으로 이음매가 지나간다. 하나, 또 하나. 세지 않았다.<br>손끝에 문틀이 걸렸다. 눈을 떴다. 들어온 문이다.<br><br>뒤에서 세는 소리가 한참 이어졌다. 이쪽이 그만둔 숫자를 혼자서.`,
      ng:`눈을 감자 벽이 손바닥 밑에서 멀어진다. 아주 조금씩.<br><br>따라가려고 몸이 기울었다. 눈을 떴을 때 복도 한가운데 서 있었다. 벽은 양쪽 다 멀다.<br>세는 소리가 바로 귀 뒤에서 났다. 예순.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-14, spirit:-20 } }
  ] },

{ at:'A1', t:'로비 — 비상 대피도',
  x:`로비 벽에 대피도가 붙어 있다. 일곱 층짜리 건물 단면이다. 비상계단이 오른쪽 끝에 그려져 있다.<br><br>
    그림 위에 스티커가 붙었다. 웃는 해. 여기 있어요. 스티커 자리가 이쪽이 선 자리와 꼭 맞다.<br>
    탐험가는 그림보다 건물을 믿는다.<br><br>
    천장 환기구에서 바람이 내려온다. 바람은 그림을 모른다.`,
  o:[
    { l:'① 환기구 바람을 따라 진짜 계단을 찾는다.', k:'sense', dc:22,
      ok:`환기구마다 손등을 댔다. 바람은 위에서 내려온다. 위가 뚫린 데서.<br><br>바람이 가장 센 자리는 그림의 계단과 반대쪽이다. 청소 도구실 문이다. 열자 철계단이 위로 감겨 올라간다. 직원용이다. 층계참마다 출근부가 걸려 있다. 칸마다 같은 시각. 네 시 오십삼 분.<br><br>사람의 길과 바람의 길은 다르다. 이 건물이 사람을 어디로 보내고 싶은지보다 공기가 어디로 빠지는지가 먼저 보인다. 이제는 문을 열기 전에 바람부터 읽는다.`,
      ng:`바람을 따라갔다. 바람이 멈춘다. 다시 분다. 숨 쉬듯이.<br><br>환기구 안에서 무언가 숨을 쉬고 있었다. 철망에 털이 끼어 있다. 갈색이다. 좀약 냄새가 확 끼친다.<br>뒷걸음치다 대피도 액자에 등을 찧었다. 액자가 떨어졌다. 깨진 유리 밑에서 스티커가 이쪽 발을 따라 웃는다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-18 }, wake:1 },
    { l:'② 그림대로 비상계단 문을 연다.', k:'luck', dc:22,
      ok:`그림대로 갔다. 비상구 문이 있다. 열린다. 계단이다. 진짜다.<br><br>층계참에 아이 장화 한 짝이 떨어져 있다. 그 안에 꿀 봉지 하나가 접혀 들어 있다. 누가 아껴 둔 것이다.<br>그림이 맞을 때도 있다. 맞은 까닭을 모르면 다음에는 안 맞는다.`,
      ng:`문을 열었다. 계단이 아니다. 벽에 계단이 그려져 있다. 페인트로. 그림자까지.<br><br>한 발 디뎠다. 이마를 벽에 박았다. 피가 눈으로 흘러든다.<br>그림 계단참에 그려진 노란 해가 이쪽을 본다. 아까는 반대쪽을 보고 있었다.`,
      win:{ exp:14, dream:2, item:'꿀 한 줌' }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A2', t:'기숙사 복도 — 물 위의 먼지',
  x:`기숙사 복도는 무릎까지 물이다. 고인 것 같지만 아니다. 아주 느리게 흐른다.<br><br>
    수면에 먼지가 얹혀 있다. 먼지가 한쪽으로 간다. 물이 빠지는 쪽이다.<br>
    물이 빠지는 데에는 아래층이 있다.<br><br>
    먼지 사이로 한 줄만 깨끗하다. 누가 방금 지나간 줄이다. 일행은 아직 아무도 그리로 안 갔다.`,
  o:[
    { l:'① 먼지가 흘러가는 쪽으로 내려갈 길을 찾는다.', k:'sense', dc:22,
      ok:`깨끗한 줄은 밟지 않았다. 먼지를 따라 벽 쪽으로 붙어 걸었다.<br><br>먼지가 모이는 데가 있다. 복도 끝 배식 통로 철문이다. 문 밑 틈으로 물이 빨려 든다. 아래층 물이 숨을 쉴 때마다 문틈이 조금씩 운다. 문 너머가 계단이다.<br>깨끗한 줄은 반대로 사감실 쪽으로 나 있었다.<br><br>물은 늘 낮은 데를 안다. 그 앎을 빌리는 법이 몸에 붙었다. 이제 물 위의 먼지 한 톨도 길로 읽힌다.`,
      ng:`먼지를 보며 걷다 깨끗한 줄을 한 발 밟았다.<br><br>밟은 자리 물이 차다. 다른 데보다 훨씬. 발목에서 무릎까지 소름이 올라온다.<br>멀리서 열쇠 소리가 났다. 찰랑. 한 번. 고개를 드는 소리였다. 벽에 붙어 오래 숨을 참았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-22 }, wake:1 },
    { l:'② 깨끗한 줄을 따라간다. 지나간 것이 길을 안다.', k:'hide', dc:23,
      doom:{ title:'깨끗한 물길', what:'사감에게 손목을 잡혀 끌려갑니다', dc:18, sec:55,
        text:`깨끗한 줄을 따라 걸었다. 걷기 쉽다. 물이 갈라져 길을 내 준다.<br><br>줄은 복도 가운데 유리문 앞에서 끝난다. 사감실이다. 의자가 문 쪽을 보고 놓였다. 비어 있다.<br>등 뒤에서 물 헤치는 소리가 난다. 이 줄을 낸 걸음이다. 열쇠가 찰랑인다.<br><br>손목을 잡힌다. 물처럼 차고 단단하다. "복도에서 돌아다니면 안 되지." 다정한 목소리가 이쪽을 유리문 안으로 데려간다.`,
        dieText:`사감실 유리에 김이 서렸다가 걷혔다.<br><br>의자에 누가 앉아 있다. 문 쪽을 보고. 젖은 머리가 이마에 붙었다.<br>복도 수면에 깨끗한 줄이 하나 더 났다. 두 줄이 나란히 사감실로 들어간다.` },
      ok:`깨끗한 줄을 따라 걷되 반 걸음 옆을 밟았다. 줄 안에는 발을 넣지 않았다.<br><br>줄은 사감실 앞에서 끝난다. 유리문 안 의자가 비었다. 의자 다리에 쪽지가 붙어 있다. 아이 글씨. 사감 선생님 다니는 길 밟지 마.<br>쪽지 뒷면에 화살표가 그려져 있다. 배식 통로. 그리로 돌았다. 등 뒤 복도에서 물 헤치는 소리가 사감실로 들어갔다.`,
      win:{ exp:21, dream:3 } }
  ] },

{ at:'A', t:'지도 — 그리지 않은 방',
  x:`탐험가는 걸으며 지도를 그린다. 이 층도 다 돌았다. 그린 것을 펴 본다.<br><br>
    방이 하나 더 있다. 복도 끝, 계단 옆. 네모 하나에 문 표시까지.<br>
    그린 기억이 없다. 그런데 이쪽 글씨다. 연필을 누르는 버릇도 같다.<br><br>
    네모 안에 작게 적혀 있다. 쉬는 곳.`,
  o:[
    { l:'① 그 방을 비켜 가는 길을 다시 짠다.', k:'sense', dc:22,
      ok:`지도를 다시 봤다. 그 방으로 가는 선은 하나뿐이다. 그 선만 더 진하다. 이쪽 연필보다.<br><br>그 선을 빼고 다시 이었다. 반 시진이 더 든다. 그래도 그 네모를 거치지 않는다.<br>멀리 돌았다. 계단 옆을 지날 때 벽에 문이 있었다. 지도대로였다. 문틈에서 따뜻한 바람이 나왔다. 이불 냄새가 났다.<br><br>지도는 이제 이쪽 손만 그리는 것이 아니다. 무엇이 같이 그리는지 가려 읽는 눈이 생겼다. 진한 선과 제 선을.`,
      ng:`비켜 가는 길을 짜는데 연필이 저절로 그 방 쪽으로 미끄러진다.<br><br>손을 떼도 선이 이어진다. 종이 위로 연필 자국이 혼자 자라 그 네모로 들어간다.<br>지도를 접었다. 접힌 종이 안에서 연필 긁는 소리가 한참 났다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-20 }, wake:1 },
    { l:'② 그 방이 정말 있는지 보러 간다.', k:'gaze', dc:23,
      doom:{ title:'쉬는 곳', what:'이불 속으로 끌려 들어갑니다', dc:18, sec:55,
        text:`계단 옆에 문이 있다. 아까는 없었다. 지도대로다.<br><br>열었다. 작은 방이다. 이불이 깔려 있다. 베개가 일행 수만큼. 하나는 이미 눌려 있다. 이쪽 머리 모양으로.<br>발이 저절로 문턱을 넘는다. 이불 귀퉁이가 들린다. 안에서 누가 들어오라고 들어 준다.<br><br>손이 발목을 잡는다. 따뜻하다. 눕혀진다. 이불이 덮인다. 얼굴까지.`,
        dieText:`일행이 계단 옆에 왔을 때 벽은 벽이었다.<br><br>지도를 펴니 그 네모가 없다. 대신 그 자리에 연필로 적혀 있다. 이쪽 글씨다.<br>쉬는 중.` },
      ok:`문은 있었다. 지도대로. 열지 않았다.<br><br>문틈에 눈을 대지도 않았다. 문 밑 바닥만 봤다. 먼지가 안쪽으로 쓸려 있다. 들어간 자국만 있다. 나온 자국이 없다.<br>지도의 그 네모에 가위표를 쳤다. 문 안에서 이불 펄럭이는 소리가 한 번 났다. 그리고 조용해졌다.`,
      win:{ exp:20, dream:3, spirit:6 } },
    { l:'③ 지도를 찢고 처음부터 새로 그린다.', k:'steady', dc:21,
      ok:`다 그린 지도를 찢었다. 일행이 놀란 눈으로 본다.<br><br>처음부터 다시 걸었다. 걸음을 세고 꺾인 데를 적었다. 이번엔 일행 하나에게 옆에서 지켜보게 했다.<br>새 지도에는 그 방이 없다. 한참 걸렸다. 그 대신 이 지도는 이쪽 것이다.`,
      ng:`찢은 조각을 버리고 새로 그렸다. 반쯤 그렸을 때 일행 하나가 바닥에서 조각을 주워 온다.<br><br>그 네모가 그려진 조각이다. 찢긴 적 없는 것처럼 반듯하다.<br>새 지도에 대 보니 딱 맞는다. 빈자리가 그 모양으로 남아 있었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-15, spirit:-18 } }
  ] },

{ at:'A1', t:'세트 뒤 — 그려 놓은 복도',
  x:`세트 뒤는 판자 숲이다. 각목에 붙인 합판마다 그림이 그려져 있다. 숲, 집, 복도.<br><br>
    복도 그림을 잘 그렸다. 원근이 맞고 문이 줄지어 있다. 바닥 광택까지 그렸다.<br>
    그 옆에 진짜 복도가 있다. 어둡다. 둘이 나란히 입을 벌리고 있다.<br><br>
    그림 쪽이 더 밝다. 조명이 거기만 비춘다.`,
  o:[
    { l:'① 그림자가 지는 쪽으로 그림과 진짜를 가린다.', k:'sense', dc:22,
      ok:`발밑을 봤다. 진짜 복도에는 이쪽 그림자가 앞으로 길게 뻗는다. 조명이 등 뒤에 있으니까.<br><br>그림 복도에도 그림자가 그려져 있다. 문마다. 그런데 그림자가 전부 이쪽을 향한다. 빛이 그림 안쪽 끝에서 온다는 뜻이다.<br>그림 속 복도 끝에 빛을 든 누가 서 있다는 뜻이기도 하다. 어두운 쪽으로 갔다.`,
      ng:`그림자를 견주느라 오래 서 있었다. 그림 속 문 하나가 아주 조금 열려 있다. 아까는 닫혀 있었다.<br><br>문틈으로 하얀 손가락 넷이 나와 있다. 판자 그림에서. 그려진 손이 아니다.<br>눈을 뗄 수 없었다. 일행이 팔을 잡아끌 때까지. 목이 굳었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-22 } },
    { l:'② 밝은 쪽, 그림 복도에 손을 대 본다.', k:'evade', dc:23,
      doom:{ title:'잘 그린 복도', what:'그림 복도 안으로 끌려 들어갑니다', dc:18, sec:50,
        text:`손을 댔다. 합판이 아니다. 차갑고 텅 빈 공기다. 손이 그림 속으로 들어간다.<br><br>빼려는데 손목을 잡혔다. 그림 문틈에서 나온 하얀 장갑이다. 손가락이 넷이다.<br>당긴다. 어깨가 들어가고 머리가 들어간다. 안은 밝다. 너무 밝다. 바닥 광택에 이쪽 얼굴이 비친다. 웃고 있다.`,
        dieText:`세트 뒤 판자 그림에 사람이 하나 늘었다.<br><br>복도 한가운데 서 있다. 등을 보이고. 문을 향해 걷는 자세다.<br>다음에 왔을 때는 두 걸음 더 들어가 있었다.` },
      ok:`손끝만 댔다가 바로 뗐다. 손가락이 그림 속으로 한 마디 들어갔다 나왔다.<br><br>판자가 아니다. 그림이 문이다. 어두운 진짜 복도 쪽으로 몸을 돌렸다.<br>등 뒤 그림 속에서 문 하나가 탁 닫혔다. 아쉬운 소리였다. 손끝에 물감이 묻어 있다. 아직 마르지 않았다.`,
      win:{ exp:21, dream:3 } }
  ] },

{ at:'A2', t:'교실동 — 같은 교실',
  x:`교실동 복도는 허리까지 물이다. 교실 문마다 팻말이 붙었다. 3학년 2반.<br><br>
    다음 문도 3학년 2반이다. 그다음도.<br>
    안을 보면 같다. 책상 배치, 칠판 글씨, 창가 화분. 화분 잎 개수까지.<br><br>
    교실을 보지 않는다. 창밖을 본다. 길 잃은 데서는 늘 바깥을 먼저 본다.`,
  o:[
    { l:'① 창밖 종탑 자리로 방향을 잡는다.', k:'sense', dc:22,
      ok:`창마다 물속이다. 그래도 위쪽 유리로 희미하게 빛이 든다. 빛 가운데 검은 기둥이 하나. 종탑이다.<br><br>교실이 같아도 종탑은 하나다. 문을 지날 때마다 창에 비친 종탑이 조금씩 옮겨 간다. 다섯째 교실에서 종탑이 창 가운데 왔다. 여섯째에서도 같은 자리다.<br>여섯째는 다섯째다. 같은 것을 또 보여 주는 것이다. 그 문을 건너뛰었다. 복도가 끝났다. 계단이 나왔다.<br><br>안이 같으면 바깥으로 읽는다. 바깥에 하나뿐인 것을 기준 삼는 법이 손에 잡혔다.`,
      ng:`종탑을 찾는 사이 교실 안에서 의자 끄는 소리가 났다.<br><br>책상마다 누가 앉아 있다. 물이 거기만 조금 무겁다. 서른 개의 무게가 일제히 창 쪽으로 돈다. 이쪽이 보는 쪽으로.<br>물러서다 물속 문턱에 걸려 넘어졌다. 입으로 물이 들어왔다. 분필 맛이 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-12, spirit:-15 }, wake:1 },
    { l:'② 팻말을 하나씩 손으로 쓸어 본다.', k:'gaze', dc:22,
      ok:`팻말을 손가락으로 쓸었다. 글씨는 같다. 나사가 다르다. 셋째 문만 나사가 새것이다.<br><br>그 팻말을 떼어 보니 뒤에 원래 팻말이 있다. 교무실 앞 계단.<br>누가 다 같은 반으로 바꿔 달았다. 길을 잃으라고. 아니면 다 같은 반으로 남으라고.`,
      ng:`쓸어 보는데 글씨가 손가락에 묻어난다. 젖은 분필이다.<br><br>손끝이 하얗게 됐다. 닦아도 지워지지 않는다. 글씨 모양 그대로. 3학년 2반.<br>그 손으로 다음 문을 짚었다. 그 문 팻말도 그렇게 바뀌었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-15, spirit:-20 } }
  ] },

{ at:'A', t:'갈림길 — 길 끝의 목소리',
  x:`갈림길이다. 왼쪽 길 끝에서 목소리가 부른다. 일행 하나의 목소리다. 이름을 부른다. 이쪽 이름을.<br><br>
    그 일행은 지금 이쪽 바로 뒤에 서 있다. 입을 다물고.<br>
    오른쪽 길은 조용하다.<br><br>
    탐험가는 목소리보다 바람을 본다. 바람이 어느 쪽에서 오는지.`,
  o:[
    { l:'① 목소리 길을 버리고 바람을 따른다.', k:'sense', dc:22,
      ok:`손등을 들었다. 바람은 왼쪽에서 온다. 목소리 쪽에서.<br><br>그래도 왼쪽으로 가지 않았다. 바람이 너무 고르다. 숨처럼 들어왔다 나간다. 길에서 부는 바람은 그렇게 고르지 않다.<br>오른쪽은 공기가 멈춰 있다. 막힌 줄 알았는데 끝에 낮은 문이 있었다. 문틈으로 진짜 바람이 들어왔다. 고르지 않게.<br><br>뒤에서 목소리가 한 번 더 불렀다. 이번에는 이름 끝이 조금 틀렸다.`,
      ng:`바람을 읽는 사이 목소리가 가까워졌다. 왼쪽 길이 짧아진 것처럼.<br><br>이름이 귀 바로 옆에서 불렸다. 대답이 목까지 올라왔다. 이를 악물었다. 어금니가 하나 흔들렸다.<br>오른쪽으로 뛰었다. 한참 동안 그 목소리가 등 뒤에서 이쪽 걸음을 셌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 일행 손을 줄줄이 잡게 하고 대답하지 말라고 한다.', k:'bond', dc:21,
      ok:`손짓으로 일행 손을 잡게 했다. 앞사람 손목, 뒷사람 손목.<br><br>목소리가 다른 이름을 부른다. 일행 이름을 하나씩. 손이 하나씩 움찔한다. 그때마다 꽉 쥐었다.<br>오른쪽 길로 다 빠져나왔다. 손을 놓고 보니 손목마다 손자국이 남았다. 세어 보니 일행 수보다 하나 많다.`,
      ng:`맨 뒤 일행이 손을 놓쳤다. 제 이름이 불렸을 때였다.<br><br>되돌아가 손목을 잡았다. 차다. 끌어오는데 왼쪽 길에서 무언가 반대로 당긴다. 팔이 빠질 듯했다.<br>겨우 끌어왔다. 그 일행은 한참 제 이름을 기억하지 못했다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-24, mind:-16 } },
    { l:'③ 목소리 길에 한 발만 들여 본다.', k:'luck', dc:23,
      doom:{ title:'부르는 길', what:'부르는 목소리에 이끌려 끌려갑니다', dc:18, sec:55,
        text:`한 발만 들였다. 목소리가 반가워한다. 이름을 한 번 더, 더 다정하게 부른다.<br><br>두 발째는 들인 기억이 없다. 길이 발밑에서 앞으로 흐른다. 서 있는데 가까워진다.<br>어둠 속에서 손이 나와 손을 잡는다. 일행 손이다. 손가락 마디까지 같다. 그 손이 끈다. 뒤에 선 진짜 일행이 멀어진다.`,
        dieText:`왼쪽 길 끝에서 목소리가 불렀다. 이번에는 다른 일행 이름이다.<br><br>목소리가 둘이다. 하나는 아까 그 목소리. 하나는 이쪽 목소리다.<br>둘이 번갈아 부른다. 다정하게.` },
      ok:`한 발을 들였다가 그 발로 바닥을 쓸어 봤다. 먼지가 없다. 이 길은 매일 누가 쓴다.<br><br>발을 뺐다. 목소리가 멈칫한다. 문턱에 떨어진 것을 하나 주웠다. 신발 끈이다. 일행 것과 같다. 아직 따뜻하다.<br>들어간 사람은 많고 나온 사람은 없는 길이다. 오른쪽으로 갔다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A1', t:'방청석 — 옮겨 다니는 출구 등',
  x:`방청석은 계단식이다. 의자가 수백. 다 접혀 있다. 어둡다.<br><br>
    출구 표시등이 셋 켜져 있다. 초록. 왼쪽, 오른쪽, 뒤.<br>
    하나를 보고 있으면 다른 하나가 꺼졌다 켜진다. 자리를 옮겨서.<br><br>
    탐험가는 표시등을 안 본다. 바닥을 본다.`,
  o:[
    { l:'① 닳은 카펫으로 사람이 정말 드나든 길을 찾는다.', k:'sense', dc:22,
      ok:`계단 카펫이 줄마다 닳은 데가 다르다. 사람은 늘 같은 길로 나간다. 표시등과 상관없이.<br><br>가운데 통로 셋째 줄에서 카펫이 옆으로 길게 닳았다. 의자 사이를 지나 벽까지. 벽에 손잡이 없는 문이 있다. 직원 문이다. 밀자 열렸다.<br>바닥에 붙은 껌 자국도 그리로 이어진다. 아이들이 몰래 뱉은 것이다. 껌 자국은 거짓말을 안 한다.<br><br>표시는 누가 바꿔 달 수 있다. 닳은 자리는 못 바꾼다. 수백 사람이 몇 해를 걸어 낸 길을 한 번 보고 읽는 눈이 생겼다.`,
      ng:`카펫을 보느라 허리를 숙였다. 접힌 의자 하나가 펴지는 소리가 났다. 바로 옆에서.<br><br>펴진 의자에 아무도 없다. 방석만 오목하게 눌려 있다. 방금 누가 앉은 만큼.<br>또 하나가 펴진다. 그 옆도. 이쪽을 둘러싸며. 기어서 빠져나오는 동안 팔꿈치가 다 까졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-18 }, wake:1 },
    { l:'② 의자 줄 밑으로 기어 뒤 출구까지 간다.', k:'hide', dc:22,
      ok:`의자 줄 밑으로 엎드려 기었다. 먼지와 사탕 껍질.<br><br>위에서 표시등이 자리를 옮기는 소리가 났다. 딸깍. 아무도 서 있지 않으니 비출 데가 없다.<br>뒤 출구 밑에 닿았다. 문 아래 틈으로 계단 불빛이 든다. 한 번도 안 꺼진 쪽이 진짜였다.`,
      ng:`기는데 의자 밑에 손이 하나 있다. 이쪽 손 옆에. 작고 하얗다.<br><br>멈췄다. 그 손도 멈췄다. 이쪽이 움직이면 같이 움직인다. 뒤 출구까지 그 손과 나란히 기었다.<br>일어섰을 때 손등에 크레용 글씨가 묻어 있었다. 오늘의 친구.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'A2', t:'식당동 — 물 밑 문',
  x:`식당동으로 가는 문은 물속에 있다. 복도 끝이 비스듬히 잠겨 들었다.<br><br>
    숨을 참고 문을 지나 건너편 공기까지 가야 한다. 얼마나 먼지 모른다.<br>
    탐험가는 물에 귀를 댄다.<br><br>
    물 밑에서 거품 터지는 소리가 난다. 저쪽에 공기가 있다는 뜻이다. 누가 숨 쉬는 소리일 수도 있다.`,
  o:[
    { l:'① 거품 박자로 거리를 재고 줄을 매고 들어간다.', k:'sense', dc:22,
      ok:`거품이 셋을 세면 하나 오른다. 오르는 소리가 멀다. 열다섯 걸음쯤.<br><br>허리에 줄을 맸다. 일행이 끝을 쥐었다. 숨을 크게 쉬고 들어갔다. 문틀을 짚고, 배식대 다리를 짚고. 셋째로 짚은 손이 수면을 뚫었다.<br>공기다. 천장 밑 한 뼘. 줄을 두 번 당겼다. 일행이 줄을 따라 하나씩 왔다.<br><br>천장 밑 공기에서 다른 숨소리가 났다. 이쪽 것이 아니다. 아주 얕다.`,
      ng:`거품 박자를 세는데 박자가 바뀐다. 이쪽이 세는 것에 맞춰서.<br><br>들어가 반쯤 갔을 때 앞이 막혔다. 의자가 쌓여 있다. 돌아섰다. 숨이 터졌다. 물을 먹었다.<br>일행이 줄을 당겨 끌어냈다. 가슴이 불에 덴 것 같다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 줄 없이 곧장 헤엄쳐 간다.', k:'evade', dc:23,
      doom:{ title:'물 밑 식당', what:'물 밑으로 발목을 잡혀 가라앉습니다', dc:18, sec:50,
        text:`숨을 들이켜고 문을 지났다. 차다. 눈을 떴다. 식당이다. 식탁마다 의자가 차 있다. 의자가 다 이쪽을 보고 있다.<br><br>천장 쪽으로 손을 뻗었다. 수면이 멀다. 발목을 무엇이 잡는다. 작은 손이다. 둘. 셋.<br>당긴다. 의자 쪽으로. 빈 의자가 하나 있다. 가라앉는다. 숨이 입가에서 방울로 빠져나간다.`,
        dieText:`일행이 줄을 매고 따라 들어왔을 때 식당은 조용했다.<br><br>식탁마다 의자가 차 있었다. 빈 데가 없었다.<br>한 의자 밑에 신발 한 짝이 떠 있었다. 끈이 풀려 있었다.` },
      ok:`숨을 들이켜고 문을 지났다. 물속에서 눈을 뜨지 않았다. 손으로 벽만 짚었다.<br><br>발목에 무엇이 스친다. 차다. 발을 차지 않고 오므렸다. 스친 것이 지나갔다.<br>머리가 수면을 뚫었다. 천장 밑 공기다. 돌아보니 일행이 줄을 맨 채 따라오고 있다. 다들 눈을 감고.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'막다른 길 — 등 뒤의 벽',
  x:`돌아섰다. 들어온 길이 없다. 벽이다.<br><br>
    방금 지나온 문이 있던 자리다. 문 테두리가 희미하게 남았다. 회반죽이 새것이다. 아직 축축하다.<br>
    앞쪽은 원래 막다른 길이다.<br><br>
    막다른 길은 대개 반쯤만 막혀 있다. 여기서는 그 반이 등 뒤에 있다.`,
  o:[
    { l:'① 벽을 짚어 오래된 벽과 새로 바른 벽을 가린다.', k:'sense', dc:22,
      ok:`손바닥으로 벽을 쓸었다. 등 뒤 벽은 축축하고 미지근하다. 체온만큼.<br><br>앞쪽 막다른 벽은 차다. 차고 마른 벽은 오래된 벽이다. 오래된 벽에는 금이 간다. 금을 따라 손가락을 넣었다. 돌 하나가 흔들린다. 밀었다. 바람이 들어왔다.<br>새로 바른 벽보다 오래된 벽이 정직하다. 오래된 쪽으로 길을 냈다.<br><br>손바닥이 이제 벽의 나이를 안다. 대기만 하면 어느 벽이 지은 사람 것이고 어느 벽이 아닌지.`,
      ng:`등 뒤 벽을 짚었다. 축축한 회반죽에 손바닥이 들어간다. 손목까지.<br><br>안이 따뜻하다. 무언가 손가락을 하나씩 쓰다듬는다. 손을 뺐다. 회반죽에 손자국이 남는다. 손가락이 여섯이다.<br>손등에 말라붙은 회반죽이 살갗을 당긴다. 떼어 낼 때 피가 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-20 }, wake:1 },
    { l:'② 덜 마른 벽을 어깨로 부순다.', k:'break', dc:23,
      ok:`덜 마른 회반죽은 잘 부서진다. 어깨로 받았다.<br><br>벽이 무너진다. 들어온 문이 그대로 있다. 문 너머 복도도 그대로다.<br>다만 복도 바닥에 흙손이 하나 놓여 있다. 손잡이가 아직 따뜻하다.`,
      ng:`어깨로 받았다. 벽이 받아 낸다. 안에서 누가 미는 것처럼.<br><br>두 번째에 어깨에서 뚝 소리가 났다. 벽에는 금도 안 갔다.<br>벽 안쪽에서 흙손 긋는 소리가 났다. 한 겹 더 바르는 소리였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'A', t:'쉬는 자리 — 문이 하나인 방',
  x:`일행이 더 못 걷는다. 쉬어야 한다. 쉴 방을 고르는 건 앞장선 사람의 일이다.<br><br>
    문이 하나인 방이 있다. 막기 좋다. 문이 둘인 방이 있다. 달아나기 좋다.<br>
    문이 하나인 방에 벽장이 있다. 벽장 문이 손가락 하나만큼 열려 있다.<br><br>
    문이 하나라는 말은, 들어오는 것도 하나라는 뜻이 아니다.`,
  o:[
    { l:'① 문이 둘인 방을 골라 문마다 등을 기대게 한다.', k:'sense', dc:22,
      ok:`문이 둘인 방에 일행을 앉혔다. 문마다 하나씩 등을 기대게 했다.<br><br>밤중에 한쪽 문 손잡이가 아주 천천히 돌았다. 기댄 일행이 깨어 다들 깨웠다. 다 같이 다른 문 쪽으로 옮겼다. 그 문은 끝내 열리지 않았다. 손잡이만 돌다 멈췄다.<br>문이 둘이면 한쪽이 막혀도 다른 쪽이 남는다. 아침까지 아무도 잃지 않았다.`,
      ng:`문이 둘인 방에 앉았다. 두 문이 동시에 조금씩 열린다. 바람도 없는데.<br><br>둘 다 막느라 아무도 못 잤다. 새벽에 보니 두 문 손잡이에 같은 손자국이 찍혀 있다. 안쪽에서 잡은 자국이다.<br>눈 밑이 검게 꺼졌다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ hp:-22, mind:-18 } },
    { l:'② 문이 하나인 방에서 벽장을 막고 쉰다.', k:'steady', dc:22,
      ok:`벽장 문을 닫고 의자를 괴었다. 그리고 방문을 막았다.<br><br>밤새 벽장 안에서 아무 소리도 없었다. 그게 오래 마음에 걸렸다. 아침에 의자를 치우고 벽장을 열었다.<br>안에 이불이 개어져 있다. 그 위에 맑은 물 한 병. 누가 두고 갔다. 손님 대접처럼.`,
      ng:`벽장을 막았다. 의자가 밤새 한 뼘씩 밀려났다. 소리 없이.<br><br>새벽에 의자가 쓰러지는 소리에 깼다. 벽장 문이 활짝 열려 있다. 안은 비었다.<br>방 안에 사람이 일행 수보다 하나 많은 것 같았다. 불을 켜고 세어 보니 맞았다. 그래도 그 기분이 아침까지 갔다.`,
      win:{ exp:15, dream:2, item:'맑은 물' }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A1', t:'부조정실 — 일 분 앞의 화면',
  x:`부조정실 벽이 모니터다. 층마다 카메라가 있다. 복도, 계단, 방청석.<br><br>
    한 화면에 이쪽 일행이 걷고 있다. 계단을 오르는 중이다. 지금 이쪽은 이 방에 서 있다.<br>
    화면 구석 시계가 흐른다. 네 시 오십육 분. 벽시계는 오십오 분이다.<br><br>
    화면 속 일행은 이쪽보다 일 분 앞에 있다.`,
  o:[
    { l:'① 화면 속 일행이 가는 길을 지도에 옮기고 그 길만 피한다.', k:'sense', dc:22,
      ok:`화면 속 일행을 따라 그렸다. 계단, 오른쪽 복도, 소품 창고. 거기서 화면 속 일행이 하나 줄었다.<br><br>창고 문 앞에서 하나가 옆으로 끌려 나갔다. 화면 밖으로. 누구인지 보기 전에 눈을 돌렸다.<br>지도에서 그 길에 줄을 긋고 왼쪽 복도로 돌았다. 일 분 뒤 소품 창고 쪽에서 박수가 났다. 이쪽은 거기 없었다.<br><br>길은 이제 지나온 데만 그리는 게 아니다. 아직 안 간 데의 일 분 앞도 지도 위에 얹는다.`,
      ng:`화면을 보며 그리는데 화면 속 일행 하나가 고개를 든다. 카메라를 본다. 이쪽 얼굴이다.<br><br>입이 움직인다. 이쪽은 입을 다물고 있었다. 화면 속 이쪽이 말한다. 이리 와.<br>일 분 뒤 그 말이 이쪽 목에서 났다. 목이 쉬도록 나왔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 }, wake:1 },
    { l:'② 일행이 비치는 화면만 끄고 빈 복도로 간다.', k:'gaze', dc:22,
      ok:`일행이 비치는 화면만 껐다. 남은 화면은 빈 복도뿐이다.<br><br>빈 복도 화면 하나에 철문이 보인다. 직원 계단. 그리로 갔다. 도착해서 천장 카메라를 올려다봤다.<br>렌즈 위에 테이프가 붙어 있다. 누가 먼저 와서 가렸다. 볼펜 글씨. 여긴 안 보여.`,
      ng:`화면을 끄는데 꺼진 화면에 이쪽 얼굴이 비친다. 까만 유리에.<br><br>비친 얼굴 뒤에 누가 서 있다. 노란 얼굴. 웃는 입이 길다. 돌아봤다. 아무도 없다. 화면을 보면 있다.<br>나머지 화면을 끄지 못하고 나왔다. 등 뒤가 오래 뜨거웠다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-15, spirit:-24 } },
    { l:'③ 화면 속 일행을 일 분 늦게 그대로 따라간다.', k:'luck', dc:23,
      doom:{ title:'일 분 앞', what:'일 분 먼저 온 쪽에게 손목을 잡혀 무대로 끌려갑니다', dc:18, sec:50,
        text:`화면 속 일행이 간 대로 갔다. 계단, 오른쪽 복도. 일 분 늦게.<br><br>소품 창고 문이 열려 있다. 화면에서 본 대로. 안에서 손이 나온다. 이쪽 손이다. 일 분 먼저 온 이쪽.<br>손목을 잡는다. 같은 손이라 힘이 같다. 빠지지 않는다. 일 분 먼저 온 쪽이 끈다. 무대 쪽으로.`,
        dieText:`부조정실 모니터 하나에 무대가 비친다.<br><br>오늘의 친구 의자에 누가 앉아 있다. 그 옆에 똑같은 사람이 서서 손을 잡고 있다.<br>화면 구석 시계가 다시 일 분 빨라졌다.` },
      ok:`일 분 늦게 따라갔다. 소품 창고 앞에서 멈췄다. 화면에서 하나가 끌려 나간 자리다.<br><br>문 앞 바닥에 신발 자국이 둘 겹쳐 있다. 같은 신발. 하나는 들어가고 하나는 끌려 나왔다.<br>그 자리를 넘지 않았다. 일 분 먼저 간 쪽이 대신 끌려갔다. 돌아와 보니 화면 속 일행 수가 이쪽과 같아져 있었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'교무실 — 학교 배치도',
  x:`교무실 벽에 학교 배치도가 붙어 있다. 물에 잠기기 전 것이다. 층마다 방 이름이 적혔다.<br><br>
    맨 아래가 강당이다. 강당으로 가는 계단은 그려져 있지 않다.<br>
    배치도 귀퉁이에 낙서가 있다. 연필로 그린 작은 화살표. 체육관에서 아래로.<br><br>
    탐험가는 그린 사람의 손과 고친 사람의 손을 가린다.`,
  o:[
    { l:'① 방 크기를 더해 벽 속에 빠진 계단을 찾는다.', k:'sense', dc:22,
      ok:`층마다 방 크기를 더했다. 체육관 동쪽 벽이 바깥벽보다 두 걸음 안쪽이다. 두 걸음만큼 비었다.<br><br>그 두 걸음이 계단이다. 그리지 않은 계단. 낙서한 아이는 알았다. 몰래 다녔으니까.<br>배치도에 연필로 그 계단을 그려 넣었다. 아이 화살표 옆에. 두 손이 같은 길을 가리킨다.<br><br>건물은 감춘 것까지 숫자로 남긴다. 숫자를 더하면 빈 데가 나온다. 이제 벽 두께가 눈에 보인다.`,
      ng:`방 크기를 더하는 사이 교무실 전화가 울렸다. 물에 반쯤 잠긴 전화다.<br><br>받지 않았다. 울릴 때마다 숫자가 날아간다. 다시 더했다. 또 울린다.<br>열네 번째에 그쳤다. 그쳤을 때 머릿속에 숫자가 하나도 안 남았다. 관자놀이가 지끈거린다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-18 }, wake:1 },
    { l:'② 배치도대로 본관 계단으로 내려간다.', k:'luck', dc:22,
      ok:`본관 계단으로 갔다. 계단 중간이 무너졌다. 무너진 데 사이로 아래층 천장이 보인다.<br><br>그 틈으로 내려갈 수 있다. 내려가다 계단참 소화기함 안에 비상식량 상자를 봤다. 말린 고기다. 비닐이 터지지 않았다.`,
      ng:`본관 계단 아래가 물이다. 물속으로 계단이 계속 간다.<br><br>그 계단에 줄지어 앉은 것들이 있다. 보이지 않는다. 물이 칸마다 무겁다.<br>돌아 나왔다. 난간에 젖은 손자국이 이쪽 손 높이로 따라왔다.`,
      win:{ exp:15, dream:2, item:'말린 고기' }, lose:{ hp:-22, spirit:-20 } }
  ] },

{ at:'A', t:'앞장선 등 — 발소리 하나 더',
  x:`탐험가가 앞장선다. 뒤로 일행 발소리가 따라온다.<br><br>
    세어 보면 한 사람 몫이 더 있다. 맨 뒤에서.<br>
    돌아보면 일행뿐이다. 돌아본 사이 발소리도 멈춘다.<br><br>
    앞장선 사람은 뒤를 보지 않고 뒤를 알아야 한다.`,
  o:[
    { l:'① 걸음 박자를 일부러 바꿔 하나만 늦게 바뀌는 발을 찾는다.', k:'sense', dc:22,
      ok:`걸음을 셋에 한 번 끊었다. 일행이 따라 끊는다. 다들 이쪽 등을 보고 걸으니까.<br><br>하나만 반 박 늦게 끊는다. 이쪽 등이 아니라 일행 등을 보고 걷는 발이다. 맨 뒤다.<br>다음 갈림길에서 일행을 손짓으로 왼쪽에 붙이고, 오른쪽 문을 열어 둔 채 지났다. 늦은 발소리가 오른쪽으로 들어갔다. 문을 닫았다.<br><br>앞장선 등이 이제 뒤를 듣는다. 일행 발소리 하나하나의 무게를 등이 기억한다.`,
      ng:`박자를 바꾸자 하나 남는 발소리가 먼저 바꾼다. 이쪽보다 먼저.<br><br>앞에서 들린다. 이쪽 앞에서. 앞장선 것은 이쪽이 아니었다.<br>멈췄다. 앞의 발소리도 멈췄다. 숨을 죽이고 한참 서 있었다. 그것이 다시 걷기 시작할 때까지.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-14, spirit:-18 }, wake:1 },
    { l:'② 돌아보지 않고 걸음을 빨리한다.', k:'evade', dc:22,
      ok:`걸음을 빨리했다. 일행도 빨라진다. 하나 남는 발소리도.<br><br>모퉁이를 돌자마자 일행을 벽감에 밀어 넣었다. 하나 남는 발소리가 모퉁이를 돌아 지나갔다. 아무 모습도 없이 발소리만. 멀어졌다.<br>한참 뒤에 나왔다. 바닥 먼지에 발자국이 한 줄 남았다. 맨발이다.`,
      ng:`빨라질수록 하나 남는 발소리가 가까워진다. 맨 뒤에서 가운데로. 가운데에서 이쪽 바로 뒤로.<br><br>목덜미에 숨이 닿았다. 뛰었다. 넘어졌다. 무릎이 바닥에 찍혔다.<br>일어섰을 때 발소리는 다시 맨 뒤에 있었다. 기다려 준 것처럼.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'A1', t:'놀이 세트 — 공 바다 위의 기둥',
  x:`놀이 세트 한가운데 공 바다가 있다. 알록달록한 공이 방 하나를 채웠다. 어른 허리 깊이다. 그렇게 보인다.<br><br>
    건너편에 계단이 있다. 돌아가는 길은 없다.<br>
    공 위로 놀이 틀이 서 있다. 노란 기둥, 파란 그물, 빨간 미끄럼틀.<br><br>
    공 몇 개가 혼자 굴러 이쪽으로 온다. 밑에서 무언가 지나갈 때처럼.`,
  o:[
    { l:'① 기둥 간격으로 바닥을 읽고 기둥만 짚어 건넌다.', k:'sense', dc:22,
      ok:`기둥은 바닥에 박혀야 선다. 기둥 사이 간격을 보면 바닥이 어디 있는지 안다.<br><br>셋째와 넷째 사이가 넓다. 그 밑은 바닥이 꺼졌다. 거기를 피해 기둥을 타고 그물을 잡고 건넜다.<br>공이 발밑에서 사그락거렸다. 한 번 발목에 무엇이 닿았다. 털 같았다. 발을 들었다. 건너편에 닿았다.`,
      ng:`셋째 기둥이 손에서 흔들린다. 박혀 있지 않다. 공에 받쳐 서 있었다.<br><br>기둥이 기울며 공 속으로 들어간다. 매달린 몸이 반쯤 잠겼다. 공 밑이 차다.<br>그물을 잡고 겨우 올라왔다. 바지에 젖은 털이 붙어 있다. 갈색이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 공을 헤치며 곧장 걸어 건넌다.', k:'steady', dc:23,
      doom:{ title:'공 바다', what:'공 바다 밑으로 끌려 가라앉습니다', dc:18, sec:50,
        text:`공을 헤치며 걸었다. 허리. 가슴. 생각보다 깊다. 바닥이 안 닿는다.<br><br>공이 사방에서 눌러 온다. 숨이 가쁘다. 공 사이로 손이 들어온다. 하얀 장갑이다. 손가락이 넷이다. 발목을 쥔다.<br>당긴다. 머리 위로 공이 덮인다. 알록달록한 빛이 위로 멀어진다.`,
        dieText:`공 바다 수면이 다시 평평해졌다.<br><br>공 하나가 떠올라 굴러 나왔다. 노란 공이다. 웃는 얼굴이 그려져 있다. 아까는 없던 그림이다.<br>놀이 세트 스피커에서 박수가 났다.` },
      ok:`걷되 발을 끌지 않고 매번 들어서 디뎠다. 발밑 공이 단단히 받칠 때만.<br><br>가운데쯤 발밑이 푹 꺼졌다. 다른 발은 이미 단단한 데를 밟고 있었다. 꺼진 데서 하얀 것이 허공을 쥐었다 놓는다.<br>건너편 계단에 앉았다. 신발 속에 공 하나가 들어 있다. 뺄 때 손이 떨렸다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'체육관 — 천장 밑 공기',
  x:`체육관은 물 밑이다. 천장 들보 사이에만 공기가 갇혀 있다. 주머니처럼. 띄엄띄엄.<br><br>
    건너편 배수로까지 가려면 주머니에서 주머니로 숨을 이어 가야 한다.<br>
    공기 주머니는 크면 오래 쉰다. 크면 다른 것도 거기서 쉰다.<br><br>
    가장 큰 주머니에서 숨소리가 난다. 여럿이다. 아주 얕다.`,
  o:[
    { l:'① 들보를 따라 작은 주머니만 이어 간다.', k:'sense', dc:22,
      ok:`작은 주머니는 숨 둘이면 다 쓴다. 대신 아무도 없다.<br><br>들보를 손으로 짚고 물 밑으로 건넜다. 주머니마다 일행이 차례로 얼굴만 내밀고 숨을 둘 쉬고 내려갔다. 아홉 번.<br>큰 주머니 옆을 지날 때 물속에서 올려다봤다. 수면에 얼굴들이 떠 있다. 숨 쉬는 척만 한다. 거품이 안 난다.`,
      ng:`다섯째 주머니가 생각보다 작았다. 둘째 숨에서 공기가 다 됐다.<br><br>다음 주머니까지 숨이 모자랐다. 물을 먹었다. 들보를 놓칠 뻔했다.<br>일행이 머리를 수면으로 밀어 올렸다. 가슴이 찢어지는 것 같다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 가장 큰 주머니에서 쉬어 간다.', k:'luck', dc:22,
      ok:`큰 주머니에 얼굴을 내밀었다. 숨이 편하다. 얼굴들이 떠 있다. 학생들이다. 다 눈을 감았다.<br><br>아무도 이쪽을 보지 않는다. 쉬는 시간이다. 들보 위에 누가 올려 둔 도시락 통이 있다. 안이 말랐다. 꿀 단지가 들어 있다.<br>가져가도 되냐고 묻지 않았다. 묻는 순간 대답할 것 같았다.`,
      ng:`큰 주머니에서 숨을 쉬는데 옆 얼굴이 눈을 뜬다.<br><br>그 얼굴이 이쪽 숨을 따라 쉰다. 들이쉬면 같이. 공기가 두 배로 준다.<br>내려와 다음 주머니로 갔다. 그 얼굴이 수면 밑에서 한참 따라왔다.`,
      win:{ exp:15, dream:2, item:'꿀 한 줌' }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'빛 — 마지막 등잔',
  x:`등잔 기름이 바닥났다. 불꽃이 콩알만 하다.<br><br>
    불이 작아질수록 어둠이 다가온다. 어둠 가장자리에 무언가 서 있다. 불빛이 닿는 데 바로 바깥에.<br>
    불이 꺼지면 그것과 이쪽 사이에 아무것도 없다.<br><br>
    탐험가는 지나온 길을 머릿속에 편다.`,
  o:[
    { l:'① 불을 먼저 끄고 머릿속 길로 걷는다.', k:'sense', dc:23,
      ok:`스스로 불을 껐다. 그것이 먼저 끄게 두지 않았다.<br><br>어둠이 한 번에 내려앉는다. 걸음을 꺼냈다. 문에서 열둘, 왼쪽, 일곱. 문턱 하나. 기둥 셋.<br>일행 손을 줄줄이 잡게 하고 걸었다. 기둥을 짚었다. 문턱을 넘었다. 어둠 속에서 무언가 기둥을 짚는 소리가 따라왔다. 이쪽이 짚은 기둥만.<br><br>빛이 있는 데까지 갔다. 눈이 아니라 지나온 걸음이 길을 비췄다. 이제는 불이 없어도 길이 꺼지지 않는다.`,
      ng:`불을 껐다. 걸음을 꺼냈다. 열둘에서 문턱이 없다.<br><br>문턱이 옮겨졌다. 셋째 기둥 자리에 기둥 대신 무언가 서 있다. 손에 닿았다. 따뜻했다.<br>비명을 삼키고 반대로 뛰었다. 벽에 이마를 박았다. 불을 다시 켤 기름은 없다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 }, wake:1 },
    { l:'② 불을 손으로 가리고 갈림길에서만 비춘다.', k:'luck', dc:22,
      ok:`손으로 불을 가리고 걸었다. 갈림길에서만 손을 뗐다.<br><br>손을 뗄 때마다 어둠 가장자리가 물러선다. 그것도 물러선다. 한 걸음씩.<br>마지막 갈림길에서 불이 꺼졌다. 다행히 앞쪽에 문틈 빛이 있었다.`,
      ng:`손을 뗄 때마다 그것이 한 걸음 가까이 서 있다.<br><br>세 번째 갈림길에서 손을 떼자 불빛 안쪽에 서 있었다. 얼굴이 보였다. 다 보기 전에 불을 껐다.<br>본 것이 눈꺼풀 안쪽에 남았다. 한참 눈을 감을 수 없었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-24 } }
  ] },

{ at:'A', t:'계단 — 내려가도 같은 층',
  x:`계단을 한 층 내려왔다. 층계참 벽에 얼룩이 있다. 사람 머리 모양이다.<br><br>
    한 층 더 내려왔다. 같은 얼룩이 있다. 같은 높이에.<br>
    또 한 층. 얼룩이 조금 더 진하다. 막 기댔다 뗀 것처럼.<br><br>
    같은 것 속에서 다른 것 하나를 찾아야 한다.`,
  o:[
    { l:'① 난간 흠집으로 같은 층인지 가린다.', k:'sense', dc:22,
      ok:`난간을 쓸며 내려갔다. 흠집이 있다. 층마다 같은 자리에.<br><br>하나만 다르다. 이쪽 손톱으로 낸 흠이다. 내려오며 일부러 그었다. 그 흠은 셋째 층계참에만 있다.<br>셋째에서 멈추고 벽에 문을 찾았다. 얼룩 뒤였다. 얼룩을 밀자 문이 열렸다. 기댔던 머리 자국이 문고리 높이였다.`,
      ng:`흠집을 보는데 흠이 늘어난다. 층마다 하나씩. 이쪽 손톱 자국과 같은 모양으로.<br><br>누가 이쪽보다 먼저 내려가며 긋고 있다. 같은 손으로.<br>무릎이 풀렸다. 층계참 얼룩에 등을 기댔다. 뗄 때 등에 무엇이 묻었다. 젖은 머리카락이었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 돌아서서 한 층 올라가 본다.', k:'gaze', dc:22,
      ok:`돌아서 한 층 올랐다. 얼룩이 없다. 맨 처음 층이다.<br><br>내려가는 계단만 같은 층을 보여 준다. 올라가는 계단은 정직하다. 위층 복도로 돌아 다른 계단을 찾았다.<br>다른 계단 첫 층계참에도 얼룩이 있었다. 아주 흐리다. 아직 덜 기댔다.`,
      ng:`올라갔다. 얼룩이 있다. 더 진하다.<br><br>얼룩 옆에 하나가 더 생겼다. 조금 작다. 일행 하나의 키다.<br>일행이 이쪽을 본다. 아무도 기댄 적이 없다고 한다. 얼룩은 아직 축축하다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-22 } },
    { l:'③ 계단 가운데 빈 데로 줄을 내려 깊이를 잰다.', k:'fix', dc:23,
      doom:{ title:'계단 틈', what:'줄에 감겨 계단 아래로 끌려 내려갑니다', dc:18, sec:55,
        text:`줄 끝에 돌을 달아 가운데 빈 데로 내렸다. 줄이 한참 풀린다. 끝이 안 닿는다.<br><br>줄이 멈춘다. 닿은 게 아니다. 아래에서 누가 잡았다. 한 번 당긴다. 묻는 것처럼.<br>놓으려 했다. 손목에 감아 둔 매듭이 조여든다. 두 번째 당김이 온다. 몸이 난간 위로 넘어간다.`,
        dieText:`계단 가운데 빈 데로 줄이 끝없이 풀려 내려갔다.<br><br>아래쪽 층계참마다 얼룩이 하나씩 늘었다. 내려간 자리를 따라.<br>맨 아래에서 누가 줄을 다 감아올리는 소리가 났다.` },
      ok:`줄을 손목에 감지 않았다. 손가락 끝으로만 잡고 내렸다.<br><br>줄이 멈추고 아래에서 당긴다. 그대로 놓았다. 줄이 아래로 빨려 내려갔다. 소리 없이.<br>바닥은 없다. 같은 층을 도는 게 아니라 끝없이 내려가는 계단이었다. 위로 올라가 다른 길을 찾았다.`,
      win:{ exp:21, dream:3 } }
  ] },

{ at:'A', t:'벽 — 이쪽 손의 화살표',
  x:`탐험가는 갈림길마다 분필 화살표를 남긴다. 끝이 갈라진 모양으로. 버릇이다.<br><br>
    처음 보는 갈림길이다. 화살표가 이미 그려져 있다. 끝이 갈라졌다. 이쪽 버릇이다.<br>
    분필 가루가 아직 떨어지고 있다.<br><br>
    화살표는 오른쪽을 가리킨다.`,
  o:[
    { l:'① 화살표를 뜯어보고 반대로 간다.', k:'sense', dc:22,
      ok:`화살표를 따르지 않았다. 대신 오래 봤다. 꺾인 각이 이쪽 것보다 조금 둥글다. 서두르지 않은 손이다.<br><br>이쪽은 늘 서두른다. 이 화살표는 서두를 필요가 없는 쪽이 그었다. 왼쪽으로 갔다.<br>왼쪽 끝에 계단이 있었다. 돌아보니 오른쪽 어둠에서 분필 긋는 소리가 났다. 다음 화살표를 그리는 소리다.`,
      ng:`왼쪽으로 갔다. 다음 갈림길에도 화살표가 있다. 이번엔 왼쪽을 가리킨다. 이쪽이 갈 쪽을 먼저.<br><br>그다음도. 그다음도. 다 맞혔다. 이쪽 생각을.<br>머리를 감싸고 주저앉았다. 끝이 갈라진 화살표가 눈을 감아도 보인다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-18 } },
    { l:'② 제 표시를 아무도 모르는 모양으로 바꾼다.', k:'fix', dc:22,
      ok:`분필을 꺼냈다. 화살표 대신 점 셋을 찍었다. 가는 쪽에 둘, 온 쪽에 하나. 일행에게만 알려 줬다.<br><br>그 뒤로 갈림길마다 점을 찍었다. 갈라진 화살표는 계속 나타났다. 다 틀린 쪽을 가리켰다. 점은 하나도 틀리지 않았다.<br>표시는 남이 읽으라고 남긴다. 여기서는 읽지 말아야 할 것도 읽는다. 누가 읽을지까지 셈에 넣는 표시가 손에 생겼다.`,
      ng:`점을 찍었다. 다음 갈림길에 점 셋이 먼저 찍혀 있다. 방금 정한 모양이다.<br><br>일행에게 속삭인 말을 누가 들었다. 일행 사이에서.<br>아무도 서로를 보지 않았다. 분필을 쥔 손이 한참 떨렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-22 }, wake:1 }
  ] },

{ at:'A', t:'쉬는 자리 — 남은 거리',
  x:`쉬는 자리다. 일행 하나가 묻는다. 얼마나 남았냐고.<br><br>
    탐험가가 대답하기 전에 다른 목소리가 대답한다. 조금만 더. 일행 목소리다.<br>
    둘러봤다. 다들 입을 다물고 있다. 다들 이쪽을 본다.<br><br>
    남은 거리를 아는 사람은 이쪽뿐이어야 한다.`,
  o:[
    { l:'① 남은 길을 걸음으로 쪼개 정확히 알려 준다.', k:'sense', dc:21,
      ok:`정확히 말했다. 이 복도 끝까지 서른. 꺾어서 열넷. 계단 마흔둘.<br><br>숫자를 들은 일행 얼굴이 조금씩 풀린다. 끝이 있는 길은 걸을 수 있다.<br>조금만 더, 하던 목소리는 다시 나지 않았다. 숫자 앞에서는 할 말이 없다.`,
      ng:`숫자를 말하는데 다른 목소리가 따라 말한다. 하나씩 더해서. 서른하나. 열다섯.<br><br>일행이 어느 쪽을 믿어야 할지 몰라 이쪽을 본다. 이쪽도 헷갈렸다.<br>그날 걸은 길은 두 숫자 어디에도 맞지 않았다.`,
      win:{ exp:15, dream:2, mind:8 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 일행 수를 얼굴을 보며 다시 센다.', k:'gaze', dc:22,
      ok:`손가락으로 셌다. 하나씩 얼굴을 보며. 맞다.<br><br>그러면 목소리는 일행 수 밖에서 났다. 등잔 그림자 쪽을 봤다. 벽에 비친 그림자가 일행 수보다 하나 많다.<br>등잔을 옮겼다. 그림자 하나가 따라오지 않았다. 그 그림자를 두고 떠났다.`,
      ng:`셌다. 맞다. 다시 셌다. 하나 많다. 또 셌다. 맞다.<br><br>세는 손가락이 누구를 두 번 짚었는지 모르겠다.<br>아무도 쉬지 못했다. 다들 서로를 오래 봤다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] }
]);

// ------------------------------------------
// 사수 (marksman) · 자원: 무력
// ------------------------------------------
kJob('marksman', 'A', [
{ at:'A', t:'복도 끝 — 손 흔드는 것',
  x:`복도 끝에 누가 서 있다. 손을 흔든다. 천천히. 좌우로.<br><br>
    멀다. 화살 한 바탕 거리다. 그 거리에서 사람 얼굴은 안 보인다. 손만 보인다. 손이 크다.<br>
    사수는 활을 들고 시위를 반만 당긴다.<br><br>
    손은 쉬지 않는다. 일행이 들어온 뒤로 한 번도.`,
  o:[
    { l:'① 시위를 반만 당긴 채 손의 박자를 센다.', k:'sense', dc:22,
      ok:`쏘지 않았다. 손을 봤다. 흔드는 박자가 고르다. 숨 박자다. 이쪽 숨.<br><br>숨을 멈췄다. 손이 멈춘다. 흔들던 손이 허공에 선 채로. 그때 보였다. 손목 아래가 없다. 팔이 아니라 줄에 매달린 장갑이다. 줄은 천장 틈으로 올라간다.<br>줄을 겨눴다. 놓았다. 장갑이 바닥에 떨어졌다. 천장 틈에서 무언가 줄을 거둬 가는 소리가 났다. 급하게.<br><br>보이는 것을 쏘던 눈이 이제 보이는 것을 움직이는 데까지 간다. 과녁 뒤의 과녁. 손이 그쪽을 먼저 찾는다.`,
      ng:`숨을 세는데 손이 이쪽 박자를 따르지 않는다. 일행 하나의 숨을 따라간다.<br><br>그 일행이 앞으로 걸어 나간다. 손에 맞춰. 붙잡았다. 일행이 뿌리친다. 팔꿈치에 턱을 맞았다.<br>겨우 끌어 앉혔다. 복도 끝 손은 아직 흔든다. 이쪽을.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16 }, wake:1 },
    { l:'② 무력을 실어 손바닥 한가운데를 꿰뚫는다.', k:'break', dc:22, cost:{ might:25 },
      ok:`끝까지 당겼다. 팔이 떨릴 만큼. 놓았다.<br><br>화살이 복도를 가로질러 손바닥을 꿰고 뒤 벽에 박혔다. 손이 벽에 못 박힌 채 계속 흔든다. 박힌 채로.<br>흔들릴 때마다 벽에서 쇠 긁는 소리가 난다. 그 소리를 등지고 옆 문으로 빠졌다.`,
      ng:`놓는 순간 손이 화살보다 먼저 옆으로 비킨다. 흔드는 박자 그대로.<br><br>화살은 어둠으로 사라졌다. 떨어지는 소리가 나지 않는다. 누가 받았다.<br>손이 흔들기를 멈추고 손가락을 접는다. 하나씩. 세는 것 같았다. 화살통에 남은 수를.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'A1', t:'조명 다리 — 매달린 등',
  x:`무대 천장에 조명 다리가 걸려 있다. 쇠 난간 위로 큰 등이 줄줄이 매달렸다.<br><br>
    그 다리 위를 무언가 걸어온다. 갈색 털. 등이 굽었다. 뭉치다. 단추 눈이 아래를 본다. 이쪽을.<br>
    다리 끝에 사다리가 있다. 일행이 오를 사다리이기도 하다.<br><br>
    사수는 등을 매단 고리를 센다. 고리 하나에 등 하나.`,
  o:[
    { l:'① 뭉치 앞 등의 고리만 쏘아 다리를 막는다.', k:'sense', dc:22,
      ok:`고리는 손가락 한 마디만 하다. 열다섯 걸음 위다.<br><br>뭉치가 셋째 등을 지날 때 넷째 고리를 쐈다. 등이 한쪽으로 기울며 다리 위로 넘어진다. 쇠 부딪는 소리. 다리가 막혔다. 뭉치가 넘어진 등 앞에 서서 고개를 갸웃한다.<br>그 사이 반대쪽 사다리로 일행을 올렸다.<br><br>짐승을 쏘는 대신 짐승이 갈 길을 쏘았다. 화살 하나가 벽이 될 수 있다. 맞힐 자리를 고르는 눈이 하나 늘었다.`,
      ng:`고리를 맞혔다. 등이 떨어진다. 다리 위가 아니라 아래로. 무대 바닥으로.<br><br>유리가 터졌다. 파편이 일행 쪽으로 튀었다. 뺨이 찢어졌다.<br>위에서 뭉치가 박수를 친다. 털 난 손바닥이 부딪는 소리가 둔하다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-16 }, wake:1 },
    { l:'② 무력을 실어 등을 쏘아 터뜨린다.', k:'break', dc:22, cost:{ might:25 },
      ok:`뭉치 바로 앞 등을 꿰었다. 등이 하얗게 터진다. 뭉치가 앞발로 단추 눈을 가린다.<br><br>빛에 눈먼 짐승은 멈춘다. 털로 된 것도 그렇다. 그 사이 사다리를 다 올랐다.<br>뒤에서 뭉치가 앞발을 내리는 소리가 났다. 이쪽 냄새를 찾으며 킁킁댔다.`,
      ng:`등이 터졌다. 빛이 이쪽 눈을 먼저 멀게 했다.<br><br>한참 아무것도 안 보였다. 좀약 냄새가 가까워졌다 멀어졌다. 털이 볼을 스쳤다.<br>눈을 떴을 때 일행 하나의 외투 단추가 다 뜯겨 있었다. 하나만 남았다. 웃는 해 모양 단추다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14, spirit:-16 } }
  ] },

{ at:'A2', t:'물 위 — 따라오는 물결',
  x:`종탑으로 노를 젓는다. 물이 평평하다. 안개가 얹혔다.<br><br>
    배 뒤쪽 물에 줄이 하나 그어진다. 물결이다. 배를 따라온다. 노를 멈추면 물결도 멈춘다.<br>
    사수는 화살을 물에 겨눠 본다.<br><br>
    물속은 보이는 자리보다 아래에 있다. 이 물은 얼마나 아래까지 있는지 모른다.`,
  o:[
    { l:'① 쏘지 않고 물결 끝 한 뼘 아래만 지켜본다.', k:'sense', dc:22,
      ok:`활을 겨눈 채 노를 일행에게 넘겼다.<br><br>물결 끝이 가끔 솟는다. 솟을 때마다 수면 아래 하얀 것이 비친다. 손이다. 작다. 배 뒤를 잡으려다 놓친다. 잡을 만큼 가까워지면 멈춘다.<br>잡지 않는다. 따라올 뿐이다. 학교로 가는 배를 학생이 따라오는 것이다. 활을 내렸다. 종탑에 닿을 때까지 물결은 그 거리를 지켰다.<br><br>쏠 것과 쏘지 않을 것을 겨누고 나서 고른다. 시위를 당긴 채 기다리는 손이 전보다 오래 버틴다.`,
      ng:`지켜보는데 물결이 둘이 된다. 셋이 된다.<br><br>배 둘레로 물결이 줄을 선다. 한 줄로. 차례를 지켜서. 배가 조금씩 기운다.<br>활을 내리고 노를 같이 저었다. 종탑 창에 닿았을 때 손바닥이 다 벗겨져 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-20 }, wake:1 },
    { l:'② 무력을 실어 줄 단 화살을 종탑 창틀에 박고 배를 끌어당긴다.', k:'fix', dc:22, cost:{ might:25 },
      ok:`줄을 맨 화살로 종탑 창틀 나무를 겨눴다. 결을 가로질러 박았다.<br><br>줄을 감아 당겼다. 팔에 힘을 다 실었다. 배가 물결보다 빠르게 미끄러진다.<br>창틀에 닿았다. 돌아보니 물결이 멈춰 있다. 놓친 것이 아쉬운 듯 한참 떠 있다가 가라앉았다.`,
      ng:`화살이 박혔다. 당겼다. 배가 오지 않는다. 배 밑에서 반대로 잡고 있다.<br><br>줄이 팽팽해진다. 팔이 빠질 듯하다. 놓았다. 줄이 튕기며 손등을 갈랐다.<br>물결이 배 바로 밑에서 멈췄다. 한동안 아무도 노를 젓지 못했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A', t:'화살통 — 돌아온 화살',
  x:`쉬는 자리에서 화살통을 셌다. 열넷.<br><br>
    아까는 열하나였다. 셋이 늘었다.<br>
    늘어난 셋은 젖어 있다. 깃이 눌렸다. 사수 것이다. 아까 쏘고 못 찾은 것.<br><br>
    누가 주워다 넣었다. 자는 사이에.`,
  o:[
    { l:'① 깃을 하나씩 보고 제 손으로 단 깃인지 가린다.', k:'sense', dc:22,
      ok:`깃 묶음을 손톱으로 쓸었다. 이쪽은 실을 셋 감고 끝을 안으로 넣는다.<br><br>셋 중 둘은 이쪽 매듭이다. 하나는 실을 넷 감았다. 끝이 밖으로 나왔다. 이쪽 화살을 흉내 낸 것이다. 촉 대신 작은 이가 박혀 있다. 사람 이다.<br>그 하나를 버렸다. 둘은 닦아서 넣었다. 그 밤은 화살통을 베고 잤다.`,
      ng:`깃을 보는데 셋이 다 같다. 다 이쪽 매듭이다.<br><br>그런데 하나가 손에 차다. 다른 것보다 훨씬. 쥐고 있으니 손가락이 저려 온다.<br>놓으려 했는데 손이 늦게 펴졌다. 손바닥에 화살대 자국이 하얗게 남아 오래 안 빠졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-12, spirit:-18 } },
    { l:'② 돌아온 화살 하나를 어둠 쪽으로 쏘아 본다.', k:'luck', dc:23,
      doom:{ title:'돌아온 화살', what:'시위에 손목이 감겨 어둠 속으로 끌려갑니다', dc:18, sec:55,
        text:`젖은 화살을 메겼다. 어둠 쪽으로 당겼다. 놓았다.<br><br>화살이 날아가지 않는다. 시위가 앞으로 끌려간다. 화살 끝을 어둠 속에서 누가 쥐었다. 놓기도 전에 받아 간 것이다.<br>시위가 손목을 감는다. 활째 당겨진다. 발이 바닥을 긁는다. 어둠 속에서 젖은 손이 화살을 따라 시위를 더듬어 온다.`,
        dieText:`쉬는 자리에 화살통이 놓여 있었다. 일행이 셌다. 열다섯.<br><br>하나가 늘었다. 젖어 있다. 깃 매듭이 이쪽 매듭이다.<br>활은 끝내 찾지 못했다.` },
      ok:`메기기 전에 시위를 손목에서 풀어 손가락에만 걸었다. 그리고 놓았다.<br><br>화살이 날아가지 않고 앞으로 끌려간다. 어둠 속에서 누가 받았다. 시위도 따라 끌려간다. 손가락을 폈다. 활이 바닥에 떨어졌다. 시위만 어둠으로 빨려 갔다.<br>활은 남았다. 시위는 새로 매면 된다. 어둠 속에서 젖은 손가락이 빈 허공을 더듬다 거둬졌다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A1', t:'방청석 — 박자를 이끄는 장갑',
  x:`방청석 위로 하얀 장갑이 수백 개 떠 있다. 손뼉을 친다. 박자에 맞춰.<br><br>
    박수가 나는 동안 무대 쪽으로 바람이 분다. 일행 옷자락이 무대 쪽으로 날린다. 발이 조금씩 끌린다.<br>
    박수에는 늘 먼저 치는 손이 있다.<br><br>
    사수는 수백 개의 손 가운데 반 박 빠른 하나를 찾는다.`,
  o:[
    { l:'① 반 박 빠른 장갑 하나만 맞힌다.', k:'sense', dc:23,
      ok:`박수가 열 번 지나는 동안 봤다. 무대 바로 위, 셋째 줄. 그 장갑이 먼저 손을 벌린다. 나머지가 따라 벌린다.<br><br>손을 벌린 순간에 놓았다. 화살이 손바닥 사이를 지나 두 장갑을 겹쳐 꿰었다. 그 자리에서 떨어졌다.<br>박수가 흐트러진다. 수백 개가 저마다 다른 박자로 친다. 바람이 멎었다. 그 사이에 방청석을 가로질렀다.<br><br>많은 것을 쏘지 않는다. 많은 것이 따르는 하나를 쏜다. 그 하나를 고르는 데 이제 숨 몇 번이면 된다.`,
      ng:`찾는 사이 박수가 빨라진다. 반 박 빠른 손이 박자를 올렸다.<br><br>바람이 세졌다. 일행이 무대 쪽으로 미끄러진다. 활을 버리고 의자 등받이를 잡았다. 일행 허리띠를 잡았다.<br>박수가 그칠 때까지 버텼다. 손가락 둘이 접질렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-16 }, wake:1 },
    { l:'② 쏘지 않고 박수와 박수 사이에만 걷게 한다.', k:'fix', dc:22,
      ok:`박수가 날 때 바람이 분다. 박수와 박수 사이에는 멎는다.<br><br>멎을 때만 걸었다. 손짓으로 일행을 하나씩 옮겼다. 열네 박자 만에 방청석 끝 문에 닿았다.<br>문을 닫는 순간 박수가 한 번 크게 났다. 칭찬하는 듯이.`,
      ng:`사이를 셌는데 박수가 사이를 줄인다. 걸을 틈이 없다.<br><br>한 박자 늦게 디딘 일행이 무대 쪽으로 쓸려 간다. 붙잡으러 뛰어들었다. 둘이 같이 계단 셋을 굴렀다.<br>무대 바로 앞에서 멈췄다. 조명이 이쪽을 비췄다. 박수가 쏟아졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-18 } }
  ] },

{ at:'A2', t:'기숙사 복도 — 사감의 열쇠',
  x:`복도 저쪽 끝에 검은 치맛단이 물 위에 떠 있다. 사감이다. 등을 보이고 섰다.<br><br>
    허리에 열쇠 꾸러미가 매달렸다. 한 걸음 걸을 때마다 찰랑인다. 그 소리가 날 때마다 호실 문 하나가 열린다.<br>
    일행이 숨은 호실도 곧 열린다.<br><br>
    사수는 꾸러미를 매단 고리를 본다. 화살 두 바탕 거리. 고리는 손톱만 하다.`,
  o:[
    { l:'① 사감이 걸음을 떼는 순간 열쇠 고리를 쏜다.', k:'sense', dc:23,
      ok:`걸음을 셌다. 사감은 문 앞에서 멈췄다가 다시 뗀다. 뗄 때 꾸러미가 허리에서 뜬다.<br><br>뜬 순간에 놓았다. 고리가 끊어지고 꾸러미가 물로 떨어졌다. 소리가 물에 먹혔다.<br>사감이 선다. 허리를 더듬는다. 천천히 물속을 내려다본다. 그 자리에서 오래. 그사이 일행을 끌고 반대쪽 계단으로 나왔다.<br><br>목숨을 쏘지 않았다. 그것이 쥔 것을 쏘았다. 쏠 것이 사람 모양이 아니어도 된다는 걸 손이 먼저 알았다.`,
      ng:`고리를 맞혔다. 고리가 아니라 열쇠 하나를 맞혔다. 쇳소리가 복도를 울린다.<br><br>사감이 돌아선다. 몸만. 얼굴은 아직 반대쪽이다. 열쇠가 다시 찰랑인다. 이쪽으로 오는 걸음이다.<br>호실 침대 밑에 다들 물에 잠긴 채 숨을 참았다. 걸음이 문 앞에서 오래 멈췄다가 지나갔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-14, spirit:-20 }, wake:1 },
    { l:'② 쏘지 않고 찰랑임 사이를 노려 맞은편 호실로 건너간다.', k:'hide', dc:22,
      ok:`열쇠가 찰랑일 때 사감은 문을 본다. 그 사이엔 복도를 본다.<br><br>찰랑일 때만 건넜다. 한 번에 한 사람. 넷째 찰랑임에 마지막 일행이 건넜다.<br>건너간 호실은 이미 열린 방이다. 사감은 연 방을 다시 열지 않는다.`,
      ng:`건너던 일행이 물속 무엇을 밟았다. 실내화다. 물이 출렁였다.<br><br>찰랑임이 멈춘다. 복도가 고요하다. 그리고 다정한 목소리. 거기 누구니.<br>대답하지 않았다. 대답하지 않는 데 온 힘이 들었다. 이를 너무 세게 물어 잇몸에서 피가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A', t:'어둠 속 — 눈이 한 쌍 더',
  x:`불빛 바깥 어둠에 눈이 떠 있다. 둘씩 짝을 지어. 다섯 쌍.<br><br>
    한 쌍이 일행 하나의 어깨 바로 뒤에 떠 있다. 그 일행은 모른다.<br>
    사수는 눈 사이 간격을 본다.<br><br>
    간격을 알면 머리 크기를 알고, 머리 크기를 알면 무엇인지 안다.`,
  o:[
    { l:'① 눈 사이 간격으로 그 한 쌍을 가려 쏜다.', k:'sense', dc:23,
      ok:`다른 넷은 간격이 손가락 둘. 짐승이다. 멀다.<br><br>일행 뒤의 한 쌍은 간격이 사람 것이다. 그런데 높이가 정수리 위다. 사람이 아니다. 일행 어깨 너머로 한 뼘. 거기를 겨눴다. 일행에게 고개를 숙이라고 했다.<br>숙인 순간 놓았다. 눈 하나가 꺼진다. 다른 하나가 천천히 감긴다. 어둠 속으로 무언가 무겁게 주저앉았다.<br><br>사람 곁에 붙은 것을 사람을 다치지 않고 쏜다. 한 뼘이면 충분하다. 손이 한 뼘을 믿게 됐다.`,
      ng:`일행에게 숙이라고 했다. 일행이 숙이지 않는다. 그 눈이 일행 귀에 무언가 속삭이고 있었다.<br><br>쏘지 못했다. 활을 내리고 뛰어가 일행을 끌어당겼다. 뒤에서 손톱 같은 것이 등을 길게 긁었다.<br>일행은 한참 무엇을 들었는지 말하지 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-18 }, wake:1 },
    { l:'② 무력을 실어 불화살을 천장 높이로 쏜다.', k:'fix', dc:22, cost:{ might:25 },
      ok:`천에 기름을 먹여 화살 끝에 감았다. 불을 붙여 천장 높이로 쏘았다.<br><br>불이 떨어지며 방이 한 번 다 비친다. 눈들이 흩어진다. 짐승 넷. 그리고 일행 뒤에 선 키 큰 것 하나. 빛을 받자 그것이 먼저 물러났다.<br>불이 꺼지기 전에 일행을 다 문 쪽으로 몰았다.`,
      ng:`불이 떨어지며 방을 비췄다. 눈은 다섯 쌍이 아니다. 벽마다, 천장마다.<br><br>본 것을 일행도 다 봤다. 하나가 소리를 질렀다. 눈들이 일제히 그 소리 쪽으로 돌았다.<br>모두 뛰었다. 문을 닫고 한참 등으로 막았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A1', t:'부조정실 — 화면 속 과녁',
  x:`부조정실 모니터에 7층 복도가 비친다. 화면 속 복도 끝에서 방글이가 걸어온다. 카메라 쪽으로.<br><br>
    한 걸음 올 때마다 화면이 바뀐다. 다음 카메라. 다음 카메라. 이쪽이 있는 층으로 내려오고 있다.<br>
    이 방 천장 구석에도 카메라가 하나 있다. 빨간 불이 깜빡인다.<br><br>
    쏠 것이 화면 속에도 있고 화면 밖에도 있다.`,
  o:[
    { l:'① 이 방 천장 카메라의 렌즈를 쏜다.', k:'sense', dc:22,
      ok:`천장 구석 렌즈를 겨눴다. 유리알만 하다. 놓았다. 렌즈가 깨진다.<br><br>모니터 하나가 까매진다. 이 방을 비추던 화면이다. 다른 화면 속 방글이가 멈춘다. 고개를 갸웃한다. 어디로 가야 할지 모르는 얼굴이다.<br>그 사이 부조정실을 나와 다른 계단으로 내려갔다. 위에서 방글이가 화면을 하나씩 다시 찾아가는 발소리가 났다.`,
      ng:`렌즈를 맞혔다. 빨간 불이 꺼지지 않는다. 깨진 유리 속에서 계속 깜빡인다.<br><br>모니터 속 방글이가 이쪽 화면으로 몸을 돌린다. 화면 가득 노란 얼굴. 웃는 입이 화면 밖으로 길어진다.<br>눈을 감고 뒷걸음질 쳤다. 눈을 감아도 노란빛이 눈꺼풀을 뚫었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 다가오는 화면 속 노란 얼굴을 쏜다.', k:'luck', dc:23,
      doom:{ title:'화면 속 과녁', what:'깨진 화면 속으로 빨려 들어갑니다', dc:18, sec:50,
        text:`화면 속 노란 얼굴 한가운데를 쐈다. 유리가 깨진다.<br><br>깨진 틈으로 바람이 빨려 든다. 화면 안쪽으로. 종이가 날리고 머리카락이 날린다. 틈이 넓어진다. 손을 뻗어 조정판을 잡았다.<br>화면 속에서 방글이가 손을 내민다. 깨진 유리 너머로. 손이 밖으로 나온다. 이쪽 손목을 잡는다. 따뜻하다. 털이 있다. 당긴다.`,
        dieText:`부조정실 모니터가 하나만 켜져 있다. 7층 스튜디오다.<br><br>오늘의 친구 자리에 누가 앉아 있다. 화면 쪽을 보고. 손에 활을 쥐고.<br>화면 밑에 자막이 지나간다. 오늘은 활을 잘 쏘는 친구가 왔어요.` },
      ok:`화면을 겨눴다. 놓기 직전에 화살 끝을 내렸다. 화면 밑 전원선을 꿰었다.<br><br>모니터 벽이 한꺼번에 꺼진다. 까만 유리에 방 안이 비친다. 일행과, 이쪽 등 뒤에 선 노란 것.<br>돌아보지 않았다. 비친 것은 화면이 식으며 천천히 흐려졌다. 문을 열고 나왔다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'수영장 — 다이빙대 끝',
  x:`수영장은 검다. 물 위로 다이빙대만 솟아 있다. 높다.<br><br>
    판 끝에 학생 하나가 서 있다. 등을 보이고. 수영모를 썼다. 발끝을 판 끝에 맞췄다.<br>
    호루라기가 울린다. 어디서 우는지 모른다. 울릴 때마다 일행 하나가 물가 쪽으로 한 걸음 나간다. 저도 모르게.<br><br>
    사수는 다이빙대를 받친 쇠 경첩을 본다.`,
  o:[
    { l:'① 판 끝 경첩을 쏘아 다이빙대를 꺾는다.', k:'sense', dc:22,
      ok:`경첩 나사 머리를 셌다. 넷. 위의 둘이 녹슬었다.<br><br>녹슨 둘을 차례로 쐈다. 판이 꺾인다. 학생이 판을 따라 기울다가, 떨어지지 않고 판 끝에 매달린 채 고개를 돌린다. 얼굴이 없다. 수영모 아래가 물이다.<br>호루라기가 그쳤다. 뛸 데가 없으니까. 일행 발이 멈췄다.`,
      ng:`하나를 맞혔다. 판이 흔들린다. 학생이 흔들림에 맞춰 무릎을 굽힌다. 뛸 준비다.<br><br>호루라기가 길게 운다. 일행 하나가 물가까지 뛰어간다. 뒤에서 붙잡아 같이 타일에 넘어졌다. 턱이 찢어졌다.<br>물속에서 박수 같은 소리가 났다. 물 치는 소리였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 무력을 실어 판 받침을 통째로 부러뜨린다.', k:'break', dc:22, cost:{ might:30 },
      ok:`끝까지 당겼다. 팔뚝에 핏줄이 섰다. 판 받침 한가운데를 꿰었다.<br><br>판이 통째로 부러져 물로 떨어진다. 학생도 같이. 소리 없이 들어간다. 물이 한 번 크게 일렁였다가 잠잠해진다.<br>호루라기는 다시 울리지 않았다. 물가로 수영모 하나가 떠밀려 왔다.`,
      ng:`화살이 판 받침에 박혔다. 부러지지 않는다.<br><br>팔이 풀려 활을 떨어뜨렸다. 활이 타일 위를 미끄러져 물가에 걸렸다. 주우러 가는 손을 일행이 붙잡았다.<br>물가에서 활이 천천히 물속으로 끌려 들어갔다. 줄 끝에 무게가 달린 것처럼.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-12, spirit:-20 } },
    { l:'③ 다이빙대에 올라가 학생을 데리고 내려온다.', k:'bond', dc:23,
      doom:{ title:'다이빙대 밑', what:'학생 손에 잡혀 검은 물 밑으로 끌려갑니다', dc:18, sec:45,
        text:`사다리를 올랐다. 판 끝까지 걸어가 학생 어깨를 잡았다. 차다. 젖은 수영복 감촉이다.<br><br>학생이 돌아선다. 수영모 아래가 물이다. 얼굴 대신 물이 고여 출렁인다. 그 물이 손을 잡는다.<br>호루라기가 울린다. 둘이 같이 판 끝을 디딘다. 판이 휜다. 휜 판이 둘을 물 위로 던진다. 검은 물이 아래에서 입을 벌린다.`,
        dieText:`수영장 물이 다시 평평해졌다.<br><br>다이빙대 끝에 학생이 서 있다. 등을 보이고. 둘이다. 하나는 수영모를 쓰지 않았다.<br>호루라기가 울린다. 둘이 같이 무릎을 굽힌다.` },
      ok:`사다리를 반만 올라 활 끝을 내밀었다. 학생 발목 가까이.<br><br>학생이 활 끝을 내려다본다. 잡을 것을 주니 잡는다. 아이들은 그런다. 활을 당겨 판에서 내렸다. 학생이 사다리에 앉는다. 무릎을 끌어안고. 그리고 물처럼 풀려 사다리를 타고 흘러내린다.<br>사다리 발치에 젖은 수영모만 남았다. 호루라기가 그쳤다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'겨눈 자리 — 일행 얼굴을 한 것',
  x:`앞쪽 어둠에서 일행 하나가 걸어 나온다. 얼굴이 일행이다. 옷도.<br><br>
    그 일행은 지금 이쪽 옆에 서 있다. 활을 쥔 이쪽 팔을 잡고.<br>
    둘 중 하나다. 둘 다 이쪽을 본다. 둘 다 같은 얼굴로 무서워한다.<br><br>
    사수는 활을 들어 둘 사이를 겨눈다. 아무도 맞지 않는 자리.`,
  o:[
    { l:'① 걸어오는 쪽의 걸음걸이를 끝까지 본다.', k:'gaze', dc:22,
      ok:`걸어오는 쪽을 봤다. 걸음이 고르다. 너무 고르다. 지친 사람은 저렇게 못 걷는다.<br><br>옆에 선 쪽은 오른다리를 끈다. 아까 계단에서 접질린 다리다. 그건 흉내 내지 못했다.<br>걸어오는 쪽 발 앞에 화살을 박았다. 그것이 멈추고 웃는다. 일행 얼굴로. 그리고 뒷걸음으로 어둠에 들어갔다. 끝까지 다리를 끌지 않았다.`,
      ng:`걸음을 보는데 둘 다 다리를 끈다. 같은 다리를. 같은 박자로.<br><br>옆에 선 일행 손이 팔을 더 세게 잡는다. 손이 차다. 아까도 찼던가. 기억나지 않는다.<br>둘 다 쏘지 못했다. 걸어온 쪽이 어둠으로 돌아갈 때까지 활을 든 채 떨었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 발치 한 뼘 앞에 화살을 박아 누가 움찔하는지 본다.', k:'sense', dc:22,
      ok:`걸어오는 쪽 발 앞 한 뼘에 박았다. 그것이 움찔하지 않는다.<br><br>옆에 선 일행이 움찔한다. 화살 소리에. 사람은 그렇게 움찔한다.<br>다음 화살을 메겼다. 걸어오던 것이 멈추더니 고개를 돌렸다. 뒤통수에도 얼굴이 있었다. 다른 일행 얼굴이었다.`,
      ng:`화살이 박혔다. 둘 다 움찔했다. 똑같이.<br><br>옆에 선 일행이 팔을 놓고 걸어오는 쪽으로 간다. 맞잡는다. 두 얼굴이 이쪽을 본다.<br>다시 붙잡아 끌어오는데 어느 쪽 손을 잡았는지 몰랐다. 밤새 그 손을 놓지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-12, spirit:-20 } },
    { l:'③ 이쪽 팔을 잡은 옆의 것을 쏜다.', k:'break', dc:24,
      doom:{ title:'옆에 선 얼굴', what:'일행 얼굴을 한 것에게 끌려갑니다', dc:19, sec:50,
        text:`팔을 뿌리치고 돌아서 옆의 것을 겨눴다. 가깝다. 빗나갈 거리가 아니다.<br><br>놓으려는 순간 그것이 운다. 일행 목소리로. 이쪽 이름을 부르며. 손가락이 굳었다.<br>뒤에서 걸어오던 쪽이 어깨를 잡는다. 차다. 다정하다. 이쪽 활을 같이 내려 준다. 그리고 끈다. 어둠 쪽으로. 우는 쪽이 따라온다. 계속 이름을 부르며.`,
        dieText:`일행이 불을 들고 왔을 때 활이 바닥에 놓여 있었다.<br><br>시위가 당겨진 채로. 화살이 메겨진 채로. 아무도 쏘지 않았다.<br>어둠 속에서 얼굴 셋이 이쪽을 봤다. 하나는 사수 얼굴이었다.` },
      ok:`돌아서 옆의 것을 겨눴다. 그것이 울며 이름을 부른다. 놓지 않고 버텼다. 숨 셋.<br><br>앞에서 걸어오던 쪽이 먼저 움직였다. 이쪽 등 뒤로 달려든다. 그쪽이었다. 돌아서며 놓았다. 가슴에 맞았다. 일행 얼굴이 종이처럼 구겨졌다.<br>옆의 일행은 아직 울고 있었다. 진짜였다. 진짜를 겨눴던 활을 오래 내려다봤다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'A', t:'계단 난간 — 내려다보는 머리',
  x:`계단 가운데가 뚫려 있다. 위층 난간에서 머리 하나가 내려다본다. 거꾸로.<br><br>
    목이 길다. 머리는 이쪽을 따라 돈다. 이쪽이 계단을 돌 때마다.<br>
    한 층 오를 때마다 그 머리가 한 층 내려온다. 목만 길어진다.<br><br>
    사수는 위로 쏜 화살이 어떻게 휘는지 안다.`,
  o:[
    { l:'① 위로 쏘는 각을 재어 목이 걸친 난간을 쏜다.', k:'sense', dc:22,
      ok:`머리를 쏘지 않았다. 목이 걸쳐진 난간을 봤다. 목이 거기서 꺾인다. 꺾인 자리가 받침이다.<br><br>위로 쏘는 화살은 힘이 빠지며 처진다. 한 뼘 위를 겨눴다. 놓았다. 난간 나무가 쪼개졌다. 목이 받침을 잃고 미끄러진다. 머리가 계단 가운데로 쑥 내려왔다가 위로 감겨 올라갔다.<br>그 사이 두 층을 올랐다. 위에서 목이 다시 난간을 찾는 소리가 났다. 나무 긁는 소리.`,
      ng:`한 뼘이 모자랐다. 화살이 난간 밑을 때리고 되돌아 떨어진다. 이쪽으로.<br><br>피했다. 화살이 일행 어깨를 스쳤다. 피가 계단에 떨어진다.<br>위의 머리가 그 냄새에 한 층 더 내려왔다. 코앞에서 눈을 깜빡였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 무력을 실어 목 한가운데를 난간 기둥에 꿰어 박는다.', k:'break', dc:23, cost:{ might:30 },
      ok:`끝까지 당겨 목 한가운데를 겨눴다. 놓았다.<br><br>화살이 목을 꿰고 뒤 난간 기둥에 박혔다. 목이 기둥에 매였다. 머리가 내려오지 못하고 그 자리에서 버둥거린다.<br>그 밑을 지나 위층에 올랐다. 지날 때 머리가 바로 위에서 이쪽을 내려다봤다. 원망하는 눈이 아니었다. 기억하는 눈이었다.`,
      ng:`화살이 목을 스쳤다. 목이 움찔하며 접힌다.<br><br>접힌 목이 다시 펴질 때 머리가 단번에 세 층을 내려왔다. 이빨이 활대를 물었다. 놓지 않았다. 당기고 당겨졌다.<br>활대에 이빨 자국이 깊게 났다. 손바닥이 찢어졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'A1', t:'인형극 무대 — 실 끝의 손',
  x:`인형극 무대 막이 열려 있다. 손 인형 셋이 고개를 까딱인다. 방글이, 뭉치, 삐뚤이. 작다.<br><br>
    손 인형인데 밑에 손이 없다. 위에서 실이 내려와 머리에 꿰어 있다. 실은 천장 어둠으로 올라간다.<br>
    인형들이 일행을 하나씩 가리킨다. 가리킬 때마다 천장에서 실 하나가 더 내려온다. 일행 쪽으로.<br><br>
    사수는 실이 모이는 자리를 찾는다.`,
  o:[
    { l:'① 실이 한데 모이는 천장 고리를 쏜다.', k:'sense', dc:23,
      ok:`실은 셋이다. 위로 갈수록 가까워진다. 천장 어둠 속 한 점에서 만난다. 쇠고리다. 희미하게 빛난다.<br><br>그 점을 겨눴다. 놓았다. 고리가 튕기고 실 셋이 한꺼번에 풀렸다. 인형들이 무대에 엎어진다. 일행 쪽으로 내려오던 실도 힘없이 떨어졌다.<br>천장 어둠에서 누가 혀를 찼다. 쯧. 그리고 조용해졌다.<br><br>인형을 쏘지 않는다. 인형을 놀리는 손이 쥔 데를 쏜다. 눈이 실을 따라 위로 올라가는 버릇이 들었다.`,
      ng:`고리를 찾는 사이 실 하나가 일행 손목에 감겼다.<br><br>일행 손이 들린다. 인형처럼. 까딱. 그 손이 이쪽 활을 가리킨다. 실이 하나 더 내려온다. 이쪽으로.<br>화살촉으로 실을 끊어 냈다. 손가락을 베었다. 끊긴 실 끝이 꿈틀대며 위로 감겨 올라갔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-12, spirit:-20 }, wake:1 },
    { l:'② 인형 셋을 차례로 쏜다.', k:'break', dc:22,
      doom:{ title:'인형극 막', what:'실에 감겨 무대 천장으로 끌려 올라갑니다', dc:18, sec:45,
        text:`방글이 인형부터 쐈다. 맞았다. 인형이 뒤로 젖혀졌다가 그대로 다시 고개를 든다. 실이 붙든다.<br><br>뭉치, 삐뚤이. 다 맞았다. 다 다시 고개를 든다. 그리고 셋이 동시에 이쪽을 가리킨다.<br>실이 내려온다. 손목, 팔꿈치, 목. 차례로 감긴다. 몸이 들린다. 발끝이 바닥을 떠난다. 천장 어둠에서 손가락이 실을 감아올린다.`,
        dieText:`인형극 막이 닫혔다가 열렸다.<br><br>무대 위에 인형이 넷이다. 넷째는 크다. 활을 든 손이 까딱인다.<br>천장에서 박수가 났다. 실 감는 소리와 같이.` },
      ok:`방글이 인형을 맞혔다. 인형이 젖혀졌다 다시 든다. 둘째 화살은 인형 대신 머리 위 실을 꿰었다.<br><br>실이 끊긴 인형이 툭 쓰러진다. 남은 둘도 그렇게 끊었다. 쏠 것은 인형이 아니라 실이었다.<br>천장에서 실 끝 셋이 허우적거리다 거둬진다. 무대 막이 저절로 닫혔다. 공연이 끝났다는 듯이.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'교실 — 혼자 쓰는 분필',
  x:`교실 칠판에 분필이 혼자 글씨를 쓴다. 물이 가슴까지 찼는데 칠판 위쪽은 말랐다.<br><br>
    분필이 이름을 쓴다. 번호와 이름. 하나씩. 이 반 학생들 이름이다.<br>
    마지막 줄에 다음 번호를 쓴다. 그리고 이름 첫 글자를 쓰기 시작한다. 일행 하나의 이름 첫 글자다.<br><br>
    칠판까지 교실 하나. 분필은 손가락만 하다.`,
  o:[
    { l:'① 분필이 획을 멈춘 틈에 끝을 쏘아 부러뜨린다.', k:'sense', dc:22,
      ok:`분필이 둘째 획을 그으려고 멈춘 순간 놓았다.<br><br>분필이 두 동강 났다. 반쪽이 물로 떨어진다. 남은 반쪽이 칠판에 붙은 채 떨린다. 쓸 수 있는 길이가 아니다.<br>칠판에 이름 첫 획만 남았다. 획 하나로는 아무도 안 불린다. 교실을 나와 문을 닫았다.`,
      ng:`분필을 맞혔다. 부러진 반쪽이 칠판 홈에 떨어진다. 홈에 분필이 한가득이다. 새것이 하나 떠오른다.<br><br>새 분필이 이어서 쓴다. 이름 끝까지. 다 쓰고 밑줄을 긋는다.<br>물속 의자들이 일제히 그 이름 쪽으로 돈다. 일행 하나가 얼굴이 하얘져 한참 말을 못 했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 칠판 한가운데를 쏘아 글씨를 가른다.', k:'luck', dc:22,
      ok:`칠판 한가운데를 꿰었다. 칠판에 금이 간다. 금이 글씨를 가로지른다.<br><br>갈라진 이름들이 위아래로 어긋난다. 분필이 멈춘다. 어느 줄에 써야 할지 모르는 것처럼.<br>금 사이로 물이 스민다. 글씨가 녹아내렸다. 일행 이름 첫 글자도.`,
      ng:`칠판에 화살이 박혔다. 그런데 금이 가지 않는다. 화살이 칠판 속으로 천천히 들어간다. 물속으로 들어가듯.<br><br>화살이 다 들어갔다. 분필이 이름 옆에 작게 그림을 그린다. 화살 하나.<br>교실 뒤에서 누가 낄낄 웃었다. 아이 웃음이었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-20 } }
  ] },

{ at:'A', t:'떨리는 손 — 따라 쉬는 숨',
  x:`사수는 쏘기 전에 숨을 반만 뱉고 멈춘다. 오래된 버릇이다.<br><br>
    어둠 속에 무언가 있다. 겨눴다. 숨을 멈췄다.<br>
    어둠 속에서도 숨이 멈춘다. 이쪽이 쉬면 쉬고, 멈추면 멈춘다.<br><br>
    숨을 따라 하는 것은 이쪽이 언제 쏘는지 안다.`,
  o:[
    { l:'① 숨이 아니라 심장 박동 사이에 놓는다.', k:'steady', dc:23,
      ok:`숨을 그대로 쉬었다. 쉬는 채로 겨눴다. 저쪽도 쉰다. 이쪽 숨을.<br><br>숨 대신 가슴 속을 셌다. 쿵. 쿵. 박동과 박동 사이. 숨은 따라 할 수 있어도 박동은 안 들린다.<br>그 사이에 놓았다. 숨을 쉬는 도중에. 어둠 속에서 숨 하나가 끊겼다.<br><br>쏘는 때를 숨이 아니라 심장이 정한다. 아무도 듣지 못하는 박자로 쏘는 법을 몸이 익혔다.`,
      ng:`박동을 세는데 박동이 들린다. 두 개. 하나는 가슴 속에서, 하나는 등 뒤에서.<br><br>등 뒤 박동이 이쪽 것보다 느리다. 조금씩 이쪽 것을 늦춘다. 숨이 가빠지고 눈앞이 흐려진다.<br>활을 떨어뜨리고 무릎을 꿇었다. 박동이 하나로 돌아올 때까지 한참 걸렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16 }, wake:1 },
    { l:'② 일부러 숨을 흘려 저쪽 숨이 나는 자리를 듣는다.', k:'sense', dc:22,
      ok:`숨을 길게, 소리 나게 뱉었다. 저쪽도 따라 뱉는다. 소리 나게.<br><br>그 소리가 어디서 나는지 들었다. 앞이 아니다. 위다. 천장 들보 위.<br>앞쪽 어둠은 비어 있었다. 들보 위를 겨눴다. 저쪽 숨이 처음으로 흐트러졌다. 달아나는 소리가 들보를 타고 멀어졌다.`,
      ng:`숨을 흘렸다. 저쪽도 흘린다. 이쪽 귀 바로 옆에서.<br><br>목덜미에 따뜻한 숨이 닿는다. 소리 없이 굳었다. 숨이 몇 번 더 닿고 떠났다.<br>목덜미에 젖은 자국이 남았다. 오래 닦았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-24 } }
  ] },

{ at:'A1', t:'스튜디오 — 카메라 셋의 빨간 불',
  x:`생방송 스튜디오다. 카메라 셋이 무대를 본다. 빨간 불이 켜진 카메라가 지금 찍는 카메라다.<br><br>
    빨간 불이 옮겨 다닌다. 왼쪽, 가운데, 오른쪽. 켜진 카메라 앞에 선 사람은 무대로 끌려간다. 바닥 테이프 선을 따라 한 뼘씩.<br>
    일행은 셋 사이를 지나야 한다. 송출 부스가 무대 뒤에 있다.<br><br>
    사수는 빨간 불 셋의 박자를 센다.`,
  o:[
    { l:'① 빨간 불이 옮겨 갈 자리를 앞질러 하나씩 끈다.', k:'sense', dc:23,
      ok:`왼쪽, 가운데, 오른쪽, 다시 왼쪽. 셋을 세면 옮긴다.<br><br>불이 왼쪽으로 오기 직전에 왼쪽 불을 쐈다. 불이 갈 데를 잃고 가운데에서 깜빡인다. 가운데도 쐈다. 오른쪽 불이 혼자 남아 어디로도 못 간다. 마지막으로 쐈다.<br>스튜디오가 어둡다. 아무도 찍히지 않는다. 찍히지 않는 사람은 무대에 오를 수 없다. 무대 뒤로 걸어 들어갔다.<br><br>불 하나를 쏘는 게 아니라 불이 갈 다음 자리를 쏜다. 한 박자 앞을 겨누는 손이 이제 망설이지 않는다.`,
      ng:`왼쪽 불을 쐈다. 맞혔다. 불이 꺼지는 대신 가운데로 뛴다. 박자가 빨라졌다.<br><br>가운데 카메라 앞에 이쪽이 서 있었다. 발이 테이프 선을 따라 미끄러진다. 한 뼘. 두 뼘.<br>일행이 허리를 감아 버텼다. 무대 턱 앞에서 멈췄다. 조명이 얼굴을 다 비췄다. 눈앞이 한참 하얬다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-14, spirit:-18 }, wake:1 },
    { l:'② 무력을 실어 카메라 받침 바퀴 축을 쏘아 넘어뜨린다.', k:'break', dc:22, cost:{ might:30 },
      ok:`가운데 카메라 받침 바퀴 축을 겨눴다. 끝까지 당겼다. 축이 부러지며 카메라가 옆으로 넘어진다. 옆 카메라까지.<br><br>두 대가 엉켜 렌즈가 바닥을 본다. 남은 하나만 무대를 본다. 그 앞만 피해 지나갔다.<br>바닥을 보는 렌즈 둘에도 빨간 불이 켜져 있다. 바닥에 비친 것을 찍고 있다. 바닥에는 이쪽 그림자가 있었다.`,
      ng:`받침이 넘어가지 않는다. 화살이 축에 박힌 채 카메라가 이쪽으로 돈다. 바퀴 소리.<br><br>빨간 불이 켜진다. 정면이다. 발이 끌려간다.<br>활을 바닥에 박아 버텼다. 활대가 휘었다. 팔꿈치가 꺾일 듯했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'A2', t:'체육관 — 물 위로 든 손',
  x:`체육관 물 위로 손이 솟아 있다. 줄지어. 점호 때 손 드는 것처럼. 손만 보인다.<br><br>
    앞줄 한가운데 손 하나가 호루라기를 쥐었다. 줄이 손목에 감겼다.<br>
    호루라기가 울리면 손들이 일제히 내려간다. 물 밑으로. 그 근처에 있던 것도 같이.<br><br>
    지나가야 한다. 손들 사이로.`,
  o:[
    { l:'① 호루라기 줄의 매듭을 쏘아 떨군다.', k:'sense', dc:22,
      ok:`줄은 손목에 두 번 감겼다. 매듭이 손등 쪽이다. 매듭을 맞히면 풀린다.<br><br>매듭을 맞혔다. 호루라기가 물로 떨어져 가라앉는다. 그 손이 허공을 쥔다. 빈손이다.<br>손들은 그대로 들려 있다. 내려갈 신호가 없다. 그 사이로 지났다. 들린 손들이 지나가는 소매를 하나씩 스쳤다. 붙잡지 않았다.`,
      ng:`매듭을 맞혔다. 호루라기가 떨어지며 물에 닿기 전에 한 번 운다. 삑.<br><br>손들이 일제히 내려간다. 물이 소용돌이친다. 가까이 있던 일행이 휩쓸릴 뻔했다. 머리채를 잡아 끌어냈다.<br>손들이 다시 올라왔다. 한 줄이 늘었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 쏘지 않고 손과 손 사이를 숨죽여 지난다.', k:'hide', dc:22,
      ok:`손과 손 사이는 한 걸음이다. 그 사이로만 걸었다. 물을 젓지 않고 밀었다.<br><br>손들이 살짝 기운다. 지나가는 쪽으로. 냄새를 맡는 것처럼.<br>마지막 줄을 지나 돌아봤다. 호루라기 쥔 손이 이쪽을 가리키다가 천천히 다시 들렸다.`,
      ng:`걷다 손 하나에 어깨가 닿았다. 손이 내려온다. 이쪽 어깨에 얹힌다. 차다.<br><br>얹힌 손이 무겁다. 점점 무겁다. 물속으로 누른다. 턱까지 잠겼다.<br>일행이 손가락을 하나씩 떼어 냈다. 어깨에 손자국이 파랗게 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-12, spirit:-18 } }
  ] },

{ at:'A', t:'바닥 — 어둠에서 당기는 끈',
  x:`일행 하나의 발목에 끈이 감겨 있다. 언제 감겼는지 아무도 모른다.<br><br>
    끈은 바닥을 따라 어둠 속으로 길게 뻗었다. 느슨하다. 아직은.<br>
    일행이 풀려고 하면 끈이 조인다. 손대지 않으면 가만있다.<br><br>
    사수는 끈을 따라 어둠까지 눈으로 간다. 팽팽해지기 전에 끊어야 한다.`,
  o:[
    { l:'① 끈이 바닥에서 뜨는 한순간을 쏘아 끊는다.', k:'sense', dc:23,
      ok:`끈은 바닥에 붙어 있다. 붙은 끈은 쏘아도 바닥에 박힐 뿐이다.<br><br>기다렸다. 어둠 속에서 끈이 한 번 당겨진다. 맛을 보듯이. 그때 끈이 바닥에서 손가락 하나만큼 뜬다. 그 틈을 쐈다. 끊어졌다.<br>끊긴 끈 끝이 어둠으로 빨려 들어갔다. 일행 발목에 남은 끈은 칼로 끊었다.<br><br>쏠 데가 생기는 한순간을 기다리는 법. 과녁이 뜰 때까지 손이 서두르지 않는다.`,
      ng:`끈이 뜨기를 기다리는 사이 당김이 세졌다. 일행이 넘어진다.<br><br>쏘았다. 끈이 아니라 바닥을 맞혔다. 일행이 바닥을 긁으며 끌려간다. 뛰어가 다리를 안았다.<br>둘이 같이 몇 걸음 끌려가다 끈이 스스로 풀렸다. 놓아준 것이다. 이번엔.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-16 }, wake:1 },
    { l:'② 끈을 손으로 잡아 반대로 당긴다.', k:'break', dc:23,
      doom:{ title:'당기는 끈', what:'끈에 감겨 어둠 속으로 끌려갑니다', dc:18, sec:55,
        text:`끈을 잡았다. 반대로 당겼다. 활 당기는 팔이다. 힘은 있다.<br><br>어둠 속에서 끈이 멈췄다가 당겨진다. 한 번에. 끈이 손바닥을 미끄러지며 살을 벗긴다. 놓으려 했는데 끈이 손목을 한 바퀴 감고 있다.<br>일행 발목 끈이 풀린다. 대신 이쪽이 묶였다. 바닥에 등이 끌린다. 어둠이 다가온다. 끈을 감아 들이는 소리가 난다.`,
        dieText:`어둠 속에서 끈 감는 소리가 그쳤다.<br><br>일행이 불을 비췄다. 바닥에 긁힌 자국이 길게 이어진다. 끝에 활이 놓여 있다.<br>시위가 끊겨 있다. 끊긴 끝이 끈과 같은 꼬임이었다.` },
      ok:`끈을 잡고 당기는 척만 하다 손을 놓았다. 어둠 속에서 끈이 크게 출렁인다. 당기던 쪽이 몸을 가누지 못한 소리.<br><br>그 틈에 일행 발목 끈을 칼로 끊었다. 끈이 어둠으로 빨려 들어간다.<br>손바닥에 끈 자국이 붉게 남았다. 꼬임이 시위와 같은 꼬임이었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A', t:'화살통 — 마지막 하나',
  x:`화살통에 하나 남았다.<br><br>
    앞에서 무언가 다가온다. 아주 천천히. 한 걸음에 숨 열 번.<br>
    서두르지 않는 것은 이쪽에 남은 수를 안다.<br><br>
    사수는 마지막 화살을 메긴다. 메긴 채로 기다린다.`,
  o:[
    { l:'① 끝까지 기다렸다가 한 발에 끝낸다.', k:'sense', dc:23,
      ok:`기다렸다. 그것이 불빛에 들어온다. 발. 무릎. 가슴. 얼굴은 아직 어둡다.<br><br>얼굴이 들어오기 직전. 목이 드러난다. 목은 얼굴보다 먼저 보인다. 거기 놓았다.<br>그것이 무릎을 꿇는다. 천천히. 걸어올 때처럼. 쓰러지고 나서야 얼굴이 불빛에 들어왔다. 보지 않았다.<br><br>남은 하나가 전부일 때 손은 떨지 않는다. 하나로 충분하다는 것을 이번엔 몸이 알았다.`,
      ng:`기다리는데 그것이 멈춘다. 불빛 바로 밖에서. 더 오지 않는다.<br><br>기다림은 이쪽 팔에서 먼저 끝났다. 팔이 떨렸다. 화살을 놓쳤다. 바닥에 떨어진 소리를 듣고 그것이 한 걸음 왔다.<br>맨손으로 일행을 끌고 물러났다. 어둠 속에서 그것이 마지막 화살을 주워 드는 소리가 났다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-22 }, wake:1 },
    { l:'② 화살을 아끼고 무력을 실어 활대로 길을 연다.', k:'break', dc:22, cost:{ might:30 },
      ok:`화살을 아꼈다. 활을 거꾸로 쥐고 힘을 실었다.<br><br>그것이 불빛에 들어온 순간 활대로 내리쳤다. 무릎을. 그것이 기운다. 그 옆을 지나 일행을 밀어냈다.<br>마지막 화살은 아직 화살통에 있다. 쓸 일이 있을 것이다. 더 나쁜 데서.`,
      ng:`활대가 그것에 닿았다. 무르다. 활대가 파묻힌다.<br><br>빼려는데 안 빠진다. 활째 놓고 물러났다. 그것이 활을 몸에 꽂은 채 계속 다가온다.<br>맨손으로 문을 닫았다. 문 너머에서 시위가 퉁 하고 울렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'A', t:'소리 과녁 — 이름 부르는 목소리',
  x:`어둠 속에서 목소리가 일행 이름을 하나씩 부른다. 대답할 때까지 부른다.<br><br>
    보이지 않는다. 소리만 있다.<br>
    소리도 과녁이다. 사수는 귀로 겨눈다.<br><br>
    목소리가 높은 데서 난다. 사람 입 높이보다 한참 위.`,
  o:[
    { l:'① 목소리 높이로 키를 재고 그 아래 몸통 자리를 쏜다.', k:'sense', dc:22,
      ok:`목소리가 사람 키 둘 높이에서 난다. 입이 거기 있다면 몸은 그 아래로 길다.<br><br>입 높이가 아니라 그 아래, 몸통일 자리를 겨눴다. 놓았다. 둔한 소리가 났다. 목소리가 이름 중간에 끊긴다.<br>한참 있다 다시 부른다. 이번엔 낮은 데서. 무릎 꿇은 높이다. 더 다가오지 않았다.`,
      ng:`높이를 쟀는데 목소리가 움직인다. 이름 한 글자마다 다른 자리에서.<br><br>화살이 빈 어둠으로 갔다. 목소리가 웃는다. 그리고 이쪽 이름을 부른다. 대답이 입술까지 올라왔다.<br>손등을 깨물어 막았다. 이빨 자국에서 피가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 쏘지 않고 화살을 거둔다. 소리 나는 것을 다 쏠 수는 없다.', k:'steady', dc:21,
      ok:`활을 내렸다. 일행에게 귀를 막게 했다. 이쪽도 막았다.<br><br>목소리가 오래 불렀다. 한 이름씩, 열 번씩. 아무도 대답하지 않았다.<br>목소리가 지쳐 그쳤다. 대답이 없는 과녁은 쏠 필요가 없다.`,
      ng:`귀를 막았다. 목소리가 손바닥 안쪽에서 들린다. 귀 안에서.<br><br>막을수록 가깝다. 손을 뗐다. 그제야 멀어졌다.<br>한동안 일행 말소리가 모두 그 목소리로 들렸다.`,
      win:{ exp:15, dream:2, mind:6 }, lose:{ mind:-18, spirit:-20 } },
    { l:'③ 무력을 실어 목소리가 난 천장 판자를 꿰뚫는다.', k:'break', dc:23, cost:{ might:25 },
      ok:`목소리가 다시 부르는 순간 천장 판자를 겨눴다. 끝까지 당겨 놓았다.<br><br>판자가 뚫리고 위에서 무언가 몸을 접는 소리가 났다. 길게. 목소리가 천장 속으로 멀어진다.<br>뚫린 구멍에서 먼지와 함께 이름표가 하나 떨어졌다. 낡았다. 먼저 온 누군가의 것이다.`,
      ng:`판자가 뚫렸다. 목소리가 구멍으로 고개를 내민다. 얼굴이 아니다. 입만 있다.<br><br>입이 이름을 부른다. 바로 위에서. 화살을 다시 메길 틈이 없었다.<br>일행을 밀고 뛰었다. 구멍에서 침 같은 것이 떨어져 어깨를 태웠다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'A', t:'거울 — 먼저 당긴 시위',
  x:`복도 끝에 큰 거울이 서 있다. 거울 속에 일행이 비친다. 활을 든 이쪽도.<br><br>
    거울 속 이쪽이 시위를 당기고 있다. 이쪽은 당기지 않았다.<br>
    거울 속 화살 끝이 일행 하나를 겨눈다.<br><br>
    사수는 거울 속 겨눔이 어디로 닿는지 본다.`,
  o:[
    { l:'① 거울 속 화살 끝을 따라 겨눔이 닿는 자리를 본다.', k:'gaze', dc:22,
      ok:`거울 속 화살 끝을 따라 봤다. 일행 하나를 겨누는 게 아니다. 그 등 뒤 벽이다. 벽에 무언가 붙어 있다. 거울에만 보인다.<br><br>거울 속 이쪽이 고개를 끄덕인다. 이쪽도 시위를 당겼다. 거울 속 각을 그대로. 일행에게 비키라고 했다.<br>놓았다. 화살이 빈 벽에 박혔다. 거울 속 벽에서 무언가 떨어졌다. 거울 속 이쪽이 활을 내렸다.`,
      ng:`화살 끝을 따라가는데 거울 속 이쪽이 먼저 놓는다.<br><br>거울 속 일행이 쓰러진다. 거울 밖 일행은 멀쩡하다. 그런데 일행이 가슴을 움켜쥔다. 숨을 못 쉰다.<br>거울을 깨뜨렸다. 그제야 숨이 돌아왔다. 깨진 조각마다 이쪽이 활을 들고 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 돌아서서 거울 반대쪽 어둠을 쏜다.', k:'evade', dc:22,
      ok:`거울은 등 뒤를 비춘다. 거울 속 이쪽이 겨눈 방향의 반대가 진짜다.<br><br>돌아서 그쪽을 쐈다. 어둠에서 무언가 넘어지는 소리. 거울 속 이쪽이 화살을 내리고 사라진다.<br>거울에는 이제 일행만 비친다. 이쪽은 비치지 않는다. 활을 든 손을 봤다. 여기 있다.`,
      ng:`돌아섰다. 거울 속 이쪽은 돌아서지 않았다. 이쪽 등을 겨눈다.<br><br>등 한가운데가 뜨겁다. 무언가 박힌 것처럼. 만져 보니 아무것도 없다.<br>그 자리가 오래 쑤셨다. 숨 쉴 때마다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] }
]);

// ------------------------------------------
// 추적자 (tracker) · 자원: 무력
// ------------------------------------------
kJob('tracker', 'A', [
{ at:'A', t:'먼지 바닥 — 하나 많은 발자국',
  x:`먼지 바닥에 일행 발자국이 찍혀 있다. 방금 지나온 자리다.<br><br>
    추적자는 버릇처럼 센다. 신발 바닥 무늬가 다 다르다. 일행 수만큼이어야 한다.<br>
    하나가 많다.<br><br>
    많은 하나도 신발이다. 일행 누구의 신발과 무늬가 같다. 다만 조금 더 깊다.`,
  o:[
    { l:'① 무늬와 깊이를 맞춰 누구 발자국을 흉내 냈는지 찾는다.', k:'sense', dc:22,
      ok:`쪼그려 앉아 하나씩 맞췄다. 무늬가 같은 두 줄. 하나는 일행 것. 하나는 더 깊다.<br><br>깊은 쪽은 뒤꿈치가 먼저 닿지 않는다. 앞꿈치부터 디딘다. 사람은 그렇게 안 걷는다. 발끝으로 서서 신은 것이다. 남의 신발을.<br>그 일행 신발을 봤다. 뒤축이 젖어 있다. 아무도 젖은 데를 밟지 않았는데.<br><br>발자국 하나가 사람 하나를 다 말한다. 이제 무늬 하나 깊이 하나로 걸은 것의 몸을 그린다. 흉내 낸 것까지.`,
      ng:`맞추는데 깊은 쪽 발자국이 이쪽 발 바로 옆에 하나 더 찍힌다. 먼지가 퍽 일어난다.<br><br>아무것도 없다. 발자국만 찍힌다. 하나, 또 하나. 이쪽을 두르며.<br>뒷걸음질 치다 넘어졌다. 손바닥 옆에 마지막 발자국이 찍혔다. 그리고 멈췄다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-22 }, wake:1 },
    { l:'② 맨 뒤에 서서 뒤만 보며 걷는다.', k:'steady', dc:21,
      ok:`맨 뒤로 갔다. 뒷걸음으로 걸었다. 일행 발소리를 등으로 들으며.<br><br>한참 아무것도 없다. 그러다 먼지 위에 발자국 하나가 생긴다. 이쪽 쪽으로. 그리고 멈춘다.<br>보고 있으면 오지 않는다. 계단까지 뒷걸음으로 갔다. 목이 뻣뻣하게 굳었다.`,
      ng:`뒤를 보며 걷는데 등 뒤에서 일행 발소리가 하나 줄었다.<br><br>돌아봤다. 다 있다. 다시 뒤를 봤다. 바로 앞 먼지에 발자국이 찍혀 있다. 코앞에.<br>목덜미 털이 다 섰다. 그 발자국이 다음 걸음을 떼지 않는 동안 한 걸음도 움직이지 못했다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, mind:-14, spirit:-16 } }
  ] },

{ at:'A1', t:'로비 — 털 묻은 발자국',
  x:`로비 대리석 바닥에 발자국이 찍혀 있다. 크다. 발가락 자국이 없다. 둥근 털 뭉치 모양.<br><br>
    발자국 테두리에 갈색 털이 빠져 있다. 좀약 냄새가 난다.<br>
    발자국은 로비를 돈다. 여러 바퀴를.<br><br>
    추적자는 털이 빠진 자리를 센다. 털은 몸을 돌릴 때 많이 빠진다.`,
  o:[
    { l:'① 털 빠진 자리로 뭉치가 지금 어디 서 있는지 읽는다.', k:'sense', dc:22,
      ok:`털이 많이 빠진 자리는 셋이다. 접수대 앞, 진열장 앞, 계단 밑. 몸을 돌린 자리다. 거기서 오래 섰다.<br><br>셋 중 계단 밑만 털이 젖어 있다. 방금 빠진 털이다. 뭉치는 지금 계단 밑 어둠에 서 있다. 계단을 막고.<br>일행을 접수대 뒤 직원 통로로 돌렸다. 지날 때 계단 밑에서 단추 두 개가 반짝였다. 이쪽을 보지 않았다. 계단만 봤다.<br><br>자국이 끝난 자리가 아니라 자국이 가장 짙은 자리를 본다. 놈이 어디서 기다리는지가 자국 위에 쌓인다.`,
      ng:`세는데 털이 손등에 내려앉는다. 위에서.<br><br>올려다봤다. 로비 천장 난간에 뭉치가 매달려 있다. 털이 떨어진다. 단추 눈이 이쪽을 본다. 팔을 벌린다. 반갑다는 몸짓이다.<br>뛰었다. 등 뒤로 둔한 것이 떨어지는 소리. 직원 통로 문을 닫고 등으로 막았다. 문이 한 번 크게 울렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-18 }, wake:1 },
    { l:'② 발자국이 한 번도 가지 않은 쪽으로 간다.', k:'luck', dc:22,
      ok:`발자국이 한 번도 안 간 자리가 있다. 매점 쪽이다.<br><br>매점 셔터 밑으로 기어 들어갔다. 안쪽에 직원 계단이 있다. 선반에 육포 봉지가 남아 있다. 하나를 챙겼다.<br>뭉치는 매점에 오지 않는다. 매점 안이 좀약 냄새로 가득했다. 제 냄새가 싫은 것이다.`,
      ng:`발자국이 안 간 쪽은 까닭이 있었다. 바닥이 젖었다. 미끄러졌다.<br><br>넘어진 소리가 로비를 울린다. 발자국 끝에서 털 스치는 소리가 다가온다.<br>기어서 매점까지 갔다. 무릎과 팔꿈치가 다 깨졌다.`,
      win:{ exp:15, dream:2, item:'말린 고기' }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'A2', t:'기숙사 — 마르지 않은 맨발 자국',
  x:`기숙사 복도 끝은 물이 빠져 바닥이 드러났다. 거기 젖은 발자국이 있다. 맨발이다. 작다.<br><br>
    발자국은 물에서 나와 호실 하나로 들어간다. 412호.<br>
    발가락 자국 안에 물이 아직 고여 있다.<br><br>
    추적자는 젖은 자국이 마르는 빠르기를 안다.`,
  o:[
    { l:'① 마른 정도로 언제 지나갔는지와 지금 어디 있는지 읽는다.', k:'sense', dc:22,
      ok:`호실 앞 발자국은 테두리만 말랐다. 오래되지 않았다. 물가 발자국은 물에서 막 나왔다.<br><br>그런데 물가 쪽이 더 젖었다. 순서가 거꾸로다. 물에서 나와 들어간 게 아니다. 호실에서 나와 물로 들어간 것이다. 뒷걸음으로.<br>412호는 비었다. 발자국 주인은 물속에 있다. 이쪽이 호실로 들어가기를 기다리면서. 호실에 가지 않고 계단으로 갔다.<br><br>자국은 순서를 말한다. 순서를 거꾸로 놓은 것까지 읽게 됐다. 앞뒤가 바뀌어도 눈이 속지 않는다.`,
      ng:`마르는 걸 보다 물 쪽을 등졌다.<br><br>등 뒤 물에서 철벅 소리가 났다. 돌아봤을 때 수면에 동그란 물결만 남았다. 바로 발밑에 새 발자국이 하나 찍혀 있다. 이쪽 발끝에 발끝을 맞대고.<br>오래 숨을 참았다. 발자국 속 물이 다 마를 때까지 아무도 움직이지 못했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-12, spirit:-20 }, wake:1 },
    { l:'② 발자국을 따라 412호 문을 연다.', k:'luck', dc:23,
      doom:{ title:'412호', what:'침대 밑 물속으로 끌려 들어갑니다', dc:18, sec:55,
        text:`발자국을 밟으며 따라갔다. 412호 문이 반쯤 열려 있다. 열었다.<br><br>침대가 열둘. 이불이 다 개어져 있다. 발자국이 침대 밑으로 들어간다. 무릎을 꿇고 들여다봤다.<br>침대 밑에서 손이 나온다. 작다. 둘. 셋. 발목, 손목. 당긴다. 침대 밑은 물이다. 바닥이 없다. 몸이 침대 밑 물속으로 미끄러져 들어간다.`,
        dieText:`412호 문이 닫혔다.<br><br>복도 바닥에 발자국이 새로 찍혔다. 큰 발자국이다. 신발 자국. 412호에서 나와 물로 들어간다. 뒷걸음으로.<br>밤 아홉 시 점호에서 412호 인원이 하나 늘었다.` },
      ok:`문을 열되 문지방을 넘지 않았다. 발자국은 침대 밑으로 들어간다.<br><br>침대 밑은 들여다보지 않았다. 대신 문 옆 사물함 위를 봤다. 이 방 아이들이 숨겨 둔 깡통이 있다. 뚜껑에 412호 공동. 안에 꿀 사탕이 굳어 덩어리가 됐다.<br>깡통을 들고 문을 닫았다. 침대 밑에서 무언가 바닥을 긁었다. 늦게.`,
      win:{ exp:21, dream:3, item:'꿀 한 줌' } }
  ] },

{ at:'A', t:'끌린 자국 — 손톱 넷',
  x:`바닥에 끌린 자국이 길게 나 있다. 무거운 것이 끌려갔다.<br><br>
    양옆에 손톱자국이 있다. 손가락 넷씩. 바닥을 긁으며 버틴 자국이다.<br>
    자국은 복도 끝 문 밑으로 들어간다.<br><br>
    추적자는 끌린 자국의 굵기를 본다. 끌린 것이 무엇이었는지, 언제였는지.`,
  o:[
    { l:'① 자국의 굵기와 먼지로 끌려간 때를 잰다.', k:'sense', dc:22,
      ok:`자국 위 먼지가 얇다. 오래되지 않았다. 반나절.<br><br>손톱자국이 넷이다. 사람 손톱은 다섯이다. 엄지는 버틸 때 바닥에 닿지 않는다. 그러니 넷이 맞다. 끌려간 쪽이 사람이다.<br>그런데 끄는 쪽 자국이 없다. 발자국 하나 없이 끌었다. 천장을 봤다. 바닥 자국과 나란히 천장에도 긁힌 줄이 나 있다. 위에서 끌었다.<br>그 복도를 지날 때 천장을 먼저 봤다. 문은 열지 않았다.<br><br>자국이 하나면 하나만 보던 눈이 이제 짝이 되는 자국을 찾는다. 끌린 것이 있으면 끈 것도 어딘가 남긴다.`,
      ng:`굵기를 재는데 자국 끝 문이 조금 열린다. 안에서.<br><br>문틈에서 손톱 긁는 소리가 난다. 넷. 안쪽에서 문을 긁는다. 열어 달라는 것처럼.<br>물러섰다. 그 소리가 일행 이름을 부르는 것 같아 귀를 막았다. 손톱 소리는 귀를 막아도 들렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 }, wake:1 },
    { l:'② 자국을 따라 문을 열고 끌려간 이를 찾는다.', k:'bond', dc:23,
      doom:{ title:'끌린 자국', what:'천장에서 내려온 것에게 끌려갑니다', dc:18, sec:55,
        text:`자국을 따라 문 앞에 섰다. 열었다. 안이 어둡다. 자국이 더 길게 이어진다.<br><br>들어갔다. 자국 끝에 아무것도 없다. 손톱자국만 깊다. 거기서 마지막으로 버텼다.<br>위에서 무엇이 내려온다. 차가운 것이 등을 덮는다. 손가락이 겨드랑이 밑으로 들어온다. 발이 바닥을 떠난다. 이쪽 손가락이 바닥을 긁는다. 넷.`,
        dieText:`일행이 불을 들고 들어왔을 때 방은 비었다.<br><br>바닥에 끌린 자국이 두 줄이다. 하나는 오래됐고 하나는 새것이다.<br>새것 양옆에 손톱자국이 있다. 넷씩.` },
      ok:`문을 열기 전에 문틀 위를 봤다. 천장에 긁힌 줄이 문 안으로 이어진다.<br><br>문을 열고 들어가지 않았다. 문틈으로 횃불만 밀어 넣었다. 천장에서 무언가 빛을 피해 안쪽으로 물러났다. 길쭉하다.<br>바닥 자국 끝에 신발 한 짝이 떨어져 있다. 끈이 묶인 채. 갈고리로 끌어냈다. 아무도 그 신발을 신지 않았다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A1', t:'분장실 — 분가루 위 손자국',
  x:`분장실 바닥에 분가루가 쏟아져 있다. 흰 가루 위에 손자국이 찍혔다. 손가락이 넷이다.<br><br>
    손자국은 문과 거울 사이에 나 있다. 거울은 전구로 둘러싸였다. 다 켜져 있다.<br>
    거울 앞 의자 하나가 빠져 있다. 누가 앉으라고.<br><br>
    추적자는 손자국이 어느 쪽을 향했는지 본다.`,
  o:[
    { l:'① 손가락 방향으로 장갑이 어디서 나와 어디로 갔는지 읽는다.', k:'sense', dc:22,
      ok:`손가락 끝이 문을 향한다. 문에서 거울로 간 게 아니다. 거울에서 나와 문으로 간 것이다.<br><br>그리고 돌아오지 않았다. 문 밖 어딘가에 있다. 아니면 지금 문 뒤에.<br>문을 보지 않고 거울을 봤다. 거울 속 문 뒤에 하얀 장갑이 하나 매달려 있다. 일행을 문 반대편 옷장 쪽으로 붙였다. 장갑은 끝내 문 뒤에서 나오지 않았다.`,
      ng:`방향을 보는데 손자국이 하나 더 찍힌다. 가루가 폭 내려앉는다. 이쪽 발 옆이다.<br><br>손가락 넷. 끝이 이쪽을 향한다. 또 하나. 다리 쪽으로 기어 온다.<br>뛰었다. 의자에 걸려 넘어졌다. 거울 속 이쪽이 그 의자에 앉아 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14, spirit:-18 } },
    { l:'② 무력을 실어 분장대를 밀어 문을 막는다.', k:'steady', dc:22, cost:{ might:25 },
      ok:`분장대 모서리에 어깨를 대고 힘을 실었다. 무겁다. 밀렸다. 문 앞을 막았다.<br><br>문이 한 번 덜컥인다. 밖에서. 분장대가 버틴다.<br>막아 놓고 반대편 환기구로 빠졌다. 분장대 위 분첩들이 하나씩 떨어지는 소리가 따라왔다.`,
      ng:`분장대를 미는데 다리가 바닥 틈에 걸린다. 밀리지 않는다.<br><br>힘을 더 실었다. 분장대 거울이 흔들리다 떨어진다. 산산이 깨졌다. 조각마다 하얀 손이 비친다.<br>파편에 종아리가 찢어졌다. 피가 분가루를 적셨다. 거기에 곧 손자국이 찍혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } },
    { l:'③ 손자국이 시작되는 거울 앞에 서 본다.', k:'gaze', dc:23,
      doom:{ title:'넷째 손가락', what:'거울 속으로 끌려 들어갑니다', dc:18, sec:55,
        text:`손자국이 시작되는 자리에 섰다. 거울을 봤다. 전구가 얼굴을 비춘다. 얼굴이 하얗다.<br><br>거울 속 이쪽이 분첩을 든다. 이쪽은 들지 않았다. 거울 속 이쪽이 볼에 분을 바른다. 볼이 차갑다. 이쪽 볼이.<br>거울 속 손이 이쪽으로 뻗는다. 유리를 지나 나온다. 장갑이다. 손가락 넷. 목덜미를 잡는다. 거울 쪽으로.`,
        dieText:`분장실 거울 앞 의자가 채워졌다.<br><br>앉은 사람 얼굴이 하얗다. 볼에 둥근 분홍이 그려졌다. 입꼬리가 귀까지 그려져 있다.<br>바닥 분가루에 손자국이 하나 늘었다. 손가락이 다섯이다.` },
      ok:`거울 앞에 섰다. 거울은 보지 않고 거울 아래 서랍을 봤다. 손자국 하나가 서랍 손잡이에 묻어 있다.<br><br>서랍을 열었다. 분첩, 연필, 그리고 분장 순서표. 오늘의 친구 — 네 시 오십팔 분. 이름 칸이 비었다.<br>순서표를 찢어 주머니에 넣었다. 빈칸이 없으면 채울 수도 없다. 거울 속에서 누가 고개를 떨궜다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'교실동 — 물결을 거스른 자국',
  x:`교실동 복도 물은 한쪽으로 흐른다. 물 위 먼지도, 떠다니는 종이도 다 같은 쪽으로 간다.<br><br>
    그 속에 한 줄만 반대로 접혀 있다. 누가 흐름을 거슬러 걸었다.<br>
    다른 자국은 다 흐름을 따랐다. 아이들은 시키는 대로 간다.<br><br>
    추적자는 혼자 다른 쪽으로 간 걸음을 쫓는다.`,
  o:[
    { l:'① 거꾸로 접힌 물결이 펴지기 전에 따라간다.', k:'sense', dc:22,
      ok:`접힌 물결은 금방 펴진다. 펴지기 전에 따라갔다. 벽에 손자국. 창틀에 긁힌 자국. 사물함 문짝 하나가 비뚤다.<br><br>자국은 화장실 맨 끝 칸에서 멈췄다. 칸 문 안쪽에 연필 글씨. 3-2 17. 여기 숨으면 안 찾아. 그 밑에 다른 날짜, 또 다른 날짜. 몇 번이고 숨었다.<br>칸 위 환기창이 아래층으로 통한다. 숨어 다니던 아이의 길이다. 그 길로 일행을 내렸다.<br><br>무리가 간 길이 아니라 혼자 다른 데로 간 걸음을 쫓았다. 그런 걸음이 대개 나가는 길을 안다. 이제 눈이 그 하나부터 찾는다.`,
      ng:`따라가는 사이 물결이 펴졌다. 놓쳤다. 다른 자국과 섞였다.<br><br>섞인 자국을 따라가다 교실 하나로 들어갔다. 다들 앉아 있는 교실이다. 보이지 않지만 물이 무겁다. 문이 등 뒤에서 닫혔다.<br>창으로 빠져나왔다. 창틀에 허벅지를 길게 베었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-14 }, wake:1 },
    { l:'② 무력으로 물을 밀며 흐름을 거슬러 곧장 간다.', k:'steady', dc:22, cost:{ might:25 },
      ok:`허리에 힘을 주고 흐름을 거슬렀다. 물이 다리를 민다. 밀리지 않았다.<br><br>일행을 뒤에 붙였다. 이쪽 몸이 물을 갈랐다. 갈라진 물로 일행이 따라온다.<br>복도 끝 계단에 닿았다. 돌아보니 갈라진 물이 다시 닫힌다. 그 위로 작은 물결 하나가 이쪽을 따라 접혔다가 멈췄다.`,
      ng:`흐름이 갑자기 세졌다. 이쪽이 거스르자 물도 힘을 실었다.<br><br>무릎이 꺾였다. 휩쓸려 복도 끝까지 밀려갔다. 방화문에 등을 박았다.<br>숨이 한참 안 쉬어졌다. 방화문 틈으로 물이 빨려 나가는 소리가 귀 옆에서 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'A', t:'냄새 — 씻은 살 냄새',
  x:`앞이 어둡다. 추적자는 불을 끄고 코로 본다.<br><br>
    먼지. 젖은 나무. 그리고 하나 더.<br>
    살 냄새다. 썩은 냄새가 아니다. 갓 씻은 살. 비누 냄새까지.<br><br>
    이런 데서 씻은 냄새가 나면 안 된다.`,
  o:[
    { l:'① 바람을 마주하고 냄새를 갈라 자리를 짚는다.', k:'sense', dc:22,
      ok:`바람을 얼굴로 받았다. 먼지는 바닥. 젖은 나무는 왼쪽 벽. 비누 냄새는 앞이다. 가슴께 높이.<br><br>그런데 바람이 바뀌어도 비누 냄새는 앞이다. 바람과 상관없이. 냄새가 이쪽을 따라 돈다.<br>냄새가 따라오는 반대쪽으로 일행을 돌렸다. 냄새가 멀어지지 않는다. 다만 가까워지지도 않았다. 계단을 내려갈 때까지 그 거리를 지켰다.`,
      ng:`냄새를 가르는데 비누 냄새가 짙어진다. 코앞이다.<br><br>무언가 볼에 닿는다. 젖은 머리카락이다. 씻은 지 얼마 안 된. 볼을 쓰다듬고 떠난다.<br>불을 켰다. 아무것도 없다. 볼에 물기가 남았다. 비누 냄새가 오래 안 빠졌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 무력으로 숨을 눌러 참고 냄새 속을 뚫고 지난다.', k:'steady', dc:22, cost:{ might:25 },
      ok:`숨을 깊이 들이켜 가슴에 가뒀다. 힘으로 눌렀다.<br><br>냄새를 안 맡으면 이쪽 냄새도 덜 퍼진다. 서로 못 맡는 채 서른 걸음을 지났다.<br>숨을 뱉었다. 등 뒤에서 누가 크게 숨을 들이쉬는 소리가 났다. 이쪽 냄새를 찾는 소리였다.`,
      ng:`서른 걸음은 길었다. 스무째에 숨이 터졌다.<br><br>크게 들이켰다. 비누 냄새가 가슴 밑까지 들어온다. 그 냄새 속에 이쪽 냄새가 섞이는 것을 그것도 맡았다.<br>뛰었다. 등 뒤에서 젖은 발소리가 한참 따라왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'A1', t:'방청석 — 크레용 자국',
  x:`방청석 벽에 크레용 선이 이어진다. 아이 허리 높이다. 크레용을 쥐고 벽을 긋고 걸어간 자국.<br><br>
    빨강. 노랑. 파랑. 색이 바뀐다. 한 자루가 닳아 끝날 때마다 새것으로.<br>
    선은 무대 쪽으로 간다.<br><br>
    추적자는 닳아 가는 선의 굵기를 본다.`,
  o:[
    { l:'① 크레용이 닳은 정도로 마지막 아이가 어디서 멈췄는지 읽는다.', k:'sense', dc:22,
      ok:`선이 가늘어지다 끊긴다. 다음 색이 시작된다. 한 자루가 닳는 데 열다섯 걸음.<br><br>마지막 색은 검정이다. 선이 굵다. 새 크레용이다. 그런데 다섯 걸음 만에 끊긴다. 닳아서가 아니다. 크레용이 바닥에 떨어져 있다. 부러지지 않은 채로.<br>거기서 손을 놓았다. 떨어진 자리는 무대 계단 바로 앞이다. 그 아래 무대 밑 틈이 열려 있다. 일행을 그 자리에서 멀리 돌렸다.<br><br>선이 끝난 자리는 멈춘 자리가 아니다. 무언가 끝낸 자리다. 그 차이를 이제 선 굵기 하나로 안다.`,
      ng:`굵기를 보는데 벽에서 크레용 긋는 소리가 난다. 바로 옆에서.<br><br>선이 새로 이어진다. 혼자. 검정으로. 이쪽 허리 높이에서. 이쪽 쪽으로.<br>선이 소매를 지나 손등을 긋는다. 검은 줄이 손등에 남았다. 문지를수록 진해졌다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-22 }, wake:1 },
    { l:'② 크레용 선을 끝까지 따라가 아이를 찾는다.', k:'bond', dc:23,
      doom:{ title:'무대 밑', what:'무대 밑 틈으로 끌려 내려갑니다', dc:18, sec:50,
        text:`선을 따라갔다. 색이 바뀔 때마다 걸음이 빨라진다. 누가 기다리는 것 같다.<br><br>검은 선이 끊긴 자리에 크레용이 떨어져 있다. 주웠다. 따뜻하다. 방금까지 쥐고 있던 것처럼.<br>무대 밑 틈에서 작은 손이 나온다. 크레용을 돌려 달라는 손이다. 내밀었다. 손이 크레용 대신 손목을 잡는다. 틈으로 당긴다. 무대 밑은 낮고 길고 어둡다.`,
        dieText:`방청석 벽에 새 크레용 선이 생겼다. 어른 허리 높이다.<br><br>검정. 무대 밑 틈에서 나와 무대 위로 올라간다.<br>오늘의 친구 의자 다리에서 끊긴다.` },
      ok:`선을 따라가되 크레용이 떨어진 자리 다섯 걸음 앞에서 섰다.<br><br>무대 밑 틈에서 작은 손이 나와 바닥을 더듬는다. 크레용을 찾는다. 갈고리로 크레용을 틈 쪽으로 밀어 줬다. 손이 쥐고 들어간다.<br>틈 안에서 크레용 긋는 소리가 한참 났다. 즐거운 소리였다. 그 사이 무대 옆을 지나갔다.`,
      win:{ exp:21, dream:3 } }
  ] },

{ at:'A2', t:'식당동 — 사감이 다니는 길',
  x:`식당 물은 가슴께다. 물이 고요하지 않다. 다 조금씩 출렁인다.<br><br>
    한 줄만 고요하다. 출입문에서 배식대까지, 배식대에서 조리실까지. 물결 하나 없는 길.<br>
    사감이 매일 다니는 길이다. 물도 그 길에서는 숨을 죽인다.<br><br>
    추적자는 그 길을 언제 마지막으로 걸었는지 본다.`,
  o:[
    { l:'① 길가 물결로 지나간 때와 다음에 올 때를 잰다.', k:'sense', dc:22,
      ok:`길 가장자리 물이 아주 조금 접혀 있다. 지나간 지 오래되면 접힌 데가 펴진다. 거의 펴졌다.<br><br>펴지는 빠르기로 쟀다. 한 바퀴에 이백 숨. 지나간 지 백팔십 숨. 스무 숨 남았다.<br>스무 숨 동안 길을 가로질러 조리실 반대편 저장고로 갔다. 열아홉째 숨에 출입문 쪽에서 열쇠 소리가 났다. 찰랑. 고요한 길이 더 고요해졌다.`,
      ng:`재는 사이 고요한 길이 이쪽으로 휘었다.<br><br>사감 길이 바뀐 게 아니다. 이쪽이 그 길 위에 서 있었다. 물이 이쪽 둘레에서도 숨을 죽인다.<br>열쇠 소리. 가까이. 머리까지 잠겨 배식대 밑에 숨었다. 숨이 끊어질 무렵 걸음이 지나갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 고요한 길을 물방울 하나 없이 뛰어넘는다.', k:'evade', dc:22,
      ok:`길 폭은 한 걸음 반이다. 물속에서 뛰기에는 넓다.<br><br>배식대 다리를 짚고 몸을 띄웠다. 물을 차고 넘었다. 길 위에 물방울 하나 떨어지지 않게.<br>건너편에 닿아 돌아봤다. 고요한 길이 그대로 고요하다. 출입문 쪽에서 아무 소리도 나지 않았다.`,
      ng:`넘다가 발끝이 길 위 물을 쳤다. 고요한 길에 물결 하나가 생겼다.<br><br>물결이 길을 따라 출입문 쪽으로 퍼져 간다. 알리러 가는 것처럼. 열쇠 소리가 났다.<br>숨을 곳까지 물을 헤치며 달렸다. 그날 내내 숨이 짧았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A', t:'돌아오는 길 — 겹친 발자국',
  x:`돌아오는 길이다. 아까 남긴 일행 발자국 위에 다른 발자국이 겹쳐 있다.<br><br>
    일행 발자국을 그대로 밟았다. 하나도 빼놓지 않고. 크기도 같다. 깊이만 얕다.<br>
    가볍다. 아니면 발끝으로만 디뎠다.<br><br>
    쫓는 걸음이다. 이쪽 일행을.`,
  o:[
    { l:'① 걸음을 일부러 바꿔 따라오는 것의 버릇을 본다.', k:'sense', dc:22,
      ok:`일행에게 걸음을 바꾸게 했다. 셋째마다 옆으로 반 걸음. 다섯째마다 멈춤.<br><br>한참 뒤에 되짚어 봤다. 겹친 발자국은 반 걸음을 따라 했다. 멈춘 자리에서는 멈췄다. 그런데 멈춘 자리마다 발끝이 벽 쪽을 향했다. 멈출 때마다 벽에 붙는다. 숨는 버릇이다.<br>숨는 것은 보이면 멈춘다. 맨 뒤 일행에게 불을 들고 뒤를 비추게 했다. 그 뒤로 겹친 발자국은 따라오지 않았다.<br><br>쫓는 것의 버릇을 쫓기는 쪽이 먼저 알았다. 자국을 읽는 데서 자국을 남기게 만드는 데까지 손이 닿았다.`,
      ng:`걸음을 바꿨다. 겹친 발자국도 바꿨다. 한 박자 먼저.<br><br>이쪽이 바꾸기 전에 바뀐 발자국이 앞에 찍혀 있다. 앞에서 기다리며 찍은 것이다.<br>쫓기는 줄 알았는데 앞에서 이끌리고 있었다. 일행 얼굴이 하얘졌다. 다들 오래 말이 없었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 }, wake:1 },
    { l:'② 무력을 실어 겹친 발자국을 거꾸로 쫓아 덮친다.', k:'break', dc:23, cost:{ might:30 },
      doom:{ title:'뒤에 있던 것', what:'천장에 매달린 것에게 붙잡혀 끌려 올라갑니다', dc:18, sec:50,
        text:`발자국을 거꾸로 쫓았다. 빠르게. 힘을 실어. 모퉁이 앞에서 발자국이 끝났다.<br><br>위를 봤다. 늦었다. 천장에 무언가 거꾸로 매달려 있다. 일행 신발을 신고. 발끝으로 천장을 디디고.<br>내려온다. 어깨를 잡는다. 힘을 실은 팔도 들리지 않는다. 발이 바닥을 떠난다. 천장 어둠 속으로 감겨 올라간다.`,
        dieText:`일행이 모퉁이를 돌았을 때는 발자국만 있었다.<br><br>둘이 겹쳐서 모퉁이 앞에서 끝난다.<br>천장에서 물이 한 방울 떨어졌다. 신발 하나가 같이 떨어졌다.` },
      ok:`거꾸로 쫓다 모퉁이 세 걸음 앞에서 멈췄다. 발자국이 거기서 끝날 줄 알았다. 끝났다.<br><br>위를 보지 않고 위로 쳤다. 힘을 실은 주먹이 천장에서 내려오던 무언가의 턱을 올려쳤다. 그것이 떨어져 바닥에 굴렀다.<br>일행 신발을 신고 있다. 신발을 벗겨 냈다. 그것이 맨발로 어둠 속으로 기어 들어갔다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'A', t:'핏방울 — 일행의 것',
  x:`바닥에 핏방울이 떨어져 있다. 일행이 걸어온 길을 따라.<br><br>
    누가 다쳤다. 본인도 모른다. 추적자는 일행 다리를 하나씩 본다. 한 사람 바짓단이 검게 젖었다.<br>
    핏방울은 길을 그린다.<br><br>
    길을 그리면 무언가 그 길을 따라온다.`,
  o:[
    { l:'① 핏방울을 따라올 것을 셈해 길을 꺾는다.', k:'sense', dc:22,
      ok:`핏방울 간격을 봤다. 걸음마다 하나. 그렇다면 따라오는 것은 걸음 수만큼 맛을 본다.<br><br>상처를 천으로 감고, 감기 전 마지막 방울들을 손가락으로 찍어 다른 길로 이었다. 스무 방울. 막다른 길까지.<br>한참 뒤 그 막다른 길 쪽에서 무언가 바닥을 핥는 소리가 났다. 오래. 끝까지 가서 멈췄다.`,
      ng:`길을 꺾었는데 피가 천을 뚫고 또 떨어졌다. 상처가 생각보다 깊다.<br><br>따라오는 소리가 핥는 소리에서 뛰는 소리로 바뀌었다. 피가 진해지는 쪽을 안다.<br>일행을 업고 달렸다. 등이 젖었다. 피인지 땀인지 몰랐다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 무력으로 상처를 꽉 묶고 피 묻은 천을 반대쪽으로 던진다.', k:'fix', dc:22, cost:{ might:25 },
      ok:`상처 위를 힘껏 조였다. 피가 멎었다. 일행이 이를 악문다.<br><br>피 묻은 천을 뭉쳐 힘껏 던졌다. 어둠 저편으로 멀리. 천이 떨어지는 소리가 아주 멀다.<br>그 소리 쪽으로 무언가 달려가는 소리가 났다. 바닥을 긁으며. 이쪽은 반대로 걸었다.`,
      ng:`너무 세게 조였다. 일행 다리가 하얗게 질린다. 풀었다 다시 묶느라 피가 쏟아졌다.<br><br>천을 던졌는데 이쪽 손에도 피가 흥건하다.<br>어둠 속 무언가가 천을 지나쳐 손 쪽으로 왔다. 손을 등 뒤로 숨기고 뛰었다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-24, spirit:-18 } },
    { l:'③ 다친 일행을 앞에 세우고 맨 뒤에서 피를 덮어 지운다.', k:'bond', dc:22,
      ok:`다친 일행을 앞에 세웠다. 맨 뒤에서 걸으며 떨어진 피를 흙으로 덮었다. 한 방울씩.<br><br>느리다. 그래도 길이 그려지지 않는다.<br>뒤에서 무언가 킁킁댔다. 흙 냄새만 맡고 멈췄다.`,
      ng:`덮느라 고개를 숙인 사이 어둠 속에서 무언가 손등의 피를 핥았다.<br><br>혀가 차갑다. 손을 뺐다. 손등 살갗이 벗겨져 있었다.<br>그것은 더 따라오지 않았다. 맛은 이미 봤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-12, spirit:-18 } }
  ] },

{ at:'A1', t:'세트 뒤 — 끌려간 의자 자국',
  x:`세트 뒤 바닥에 의자 다리 자국이 길게 끌려 있다. 넷. 나란히.<br><br>
    작은 의자다. 방청석 의자. 누가 앉은 채로 끌려갔다.<br>
    자국은 세트 문 너머 녹화장 쪽으로 간다. 카드를 든 무대 감독이 서 있던 쪽이다.<br><br>
    추적자는 의자 다리가 남긴 깊이를 본다. 앉은 무게를 말한다.`,
  o:[
    { l:'① 의자 다리 자국 깊이로 앉은 이의 무게를 읽는다.', k:'sense', dc:22,
      ok:`앞다리 자국이 깊다. 뒷다리는 얕다. 앞으로 쏠려 앉았다. 버둥거리며 일어나려던 무게다.<br><br>그런데 무게가 어른 것이다. 작은 의자에 어른이 앉아 끌려갔다. 일행보다 먼저 온 누군가다.<br>자국 끝 세트 문 앞에 명찰이 떨어져 있다. 방청객. 이름 칸은 비었다. 주워서 다른 데 버렸다. 이 문 앞에 두면 다음 사람이 줍는다.`,
      ng:`깊이를 재는데 자국이 지금 생긴다. 바로 옆에.<br><br>의자 끄는 소리가 난다. 아무것도 안 보인다. 의자 다리 넷이 바닥을 긁으며 세트 문으로 간다. 앉은 무게로.<br>무게가 일행 하나와 같다. 그 일행은 여기 서 있다. 그래도 한참 그 일행 손을 놓지 못했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 무력으로 세트 판자를 뜯어 끌려가는 길을 막는다.', k:'break', dc:22, cost:{ might:30 },
      ok:`세트 판자 하나를 뜯어 문 앞에 가로질렀다. 각목으로 받쳤다. 힘을 실어 박았다.<br><br>문 너머에서 의자 끄는 소리가 다가오다 멈춘다. 판자에 의자 다리가 부딪는다. 몇 번.<br>그리고 소리가 돌아간다. 다른 길을 찾으러. 그 사이 반대쪽으로 빠졌다.`,
      ng:`판자를 뜯는데 못이 손바닥에 박혔다.<br><br>빼는 사이 문 너머에서 카드 넘기는 소리가 났다. 조용히. 다음 순서.<br>판자를 세우지 못하고 물러났다. 손바닥에서 피가 오래 났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'A2', t:'수영장 — 나간 자국과 들어온 자국',
  x:`수영장 물가 타일에 젖은 자국이 나 있다. 물에서 나와 탈의실로 간다.<br><br>
    탈의실에서 나와 다시 물로 간 자국도 있다.<br>
    추적자는 센다. 나간 것이 열둘. 돌아온 것이 열하나.<br><br>
    하나는 아직 탈의실에 있다.`,
  o:[
    { l:'① 나간 자국과 돌아온 자국을 짝지어 남은 하나를 가린다.', k:'sense', dc:22,
      ok:`발 크기로 짝을 지었다. 열하나는 짝이 맞다. 남은 하나는 다른 것보다 크다. 학생 발이 아니다.<br><br>어른 맨발이다. 탈의실로 들어가 나오지 않았다. 사감은 신을 신는다. 그러면 이것은 학생도 사감도 아니다.<br>탈의실을 지나지 않고 물가 둘레로 돌았다. 지날 때 탈의실 문틈으로 사물함 문 하나가 아주 천천히 닫히는 소리가 났다.`,
      ng:`짝을 짓는데 돌아온 자국이 하나 늘었다. 열둘. 짝이 맞는다.<br><br>그런데 물이 출렁인다. 방금 들어간 것이 있다. 그러면 탈의실에서 나올 것이 하나 더 남았다.<br>셈이 계속 바뀐다. 셈을 놓았다. 머리가 깨질 듯 아팠다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 무력으로 녹슨 비상문을 비틀어 탈의실을 비켜 간다.', k:'break', dc:22, cost:{ might:30 },
      ok:`탈의실을 지나지 않으려면 비상문밖에 없다. 녹이 슬어 잠겼다. 손잡이에 힘을 다 실었다.<br><br>녹이 비명을 지르며 문이 열렸다. 그 너머가 배수로다.<br>문 열리는 소리에 탈의실 사물함 문이 일제히 열렸다. 아무것도 나오지 않았다. 문을 닫고 걸쇠를 걸었다.`,
      ng:`문이 안 열린다. 힘을 더 실었다. 손잡이가 부러졌다.<br><br>부러지는 소리가 수영장을 울린다. 탈의실 문이 열린다. 젖은 맨발 소리가 타일 위로 나온다.<br>일행을 물가 벽에 붙였다. 젖은 발소리가 바로 앞을 지나 물로 들어갔다. 한 발 차이로.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A', t:'자국 없는 것 — 소리만 있는 걸음',
  x:`걸음 소리가 난다. 바로 옆 복도에서. 이쪽과 나란히.<br><br>
    그 복도 바닥은 먼지가 두껍다. 불을 비추면 매끈하다. 자국이 없다.<br>
    소리는 계속 난다. 이쪽이 멈추면 멈춘다.<br><br>
    바닥에 자국을 남기지 않는 것은 다른 데 남긴다.`,
  o:[
    { l:'① 바닥 대신 거미줄의 흔들림을 읽는다.', k:'sense', dc:23,
      ok:`불을 낮추고 복도 위쪽을 봤다. 천장 모서리에 거미줄이 늘어져 있다. 먼지를 뒤집어써 하얗다.<br><br>걸음 소리가 날 때마다 거미줄이 한 칸씩 흔들린다. 키 높이에서. 바닥을 디디지 않고 무언가 그 높이로 지나간다. 떠서.<br>흔들림이 이쪽 복도와 만나는 모퉁이를 셌다. 셋째. 셋째 모퉁이 전에 옆 계단으로 빠졌다. 걸음 소리는 셋째 모퉁이에서 멈췄다. 기다렸다.<br><br>밟은 자국만 자국이 아니다. 지나간 것이 흔든 것은 다 자국이다. 이제 눈이 바닥에서 떨어져 공기 속을 읽는다.`,
      ng:`거미줄을 보는데 흔들림이 이쪽 복도로 건너온다. 벽을 지나서.<br><br>얼굴 앞 거미줄이 흔들린다. 바로 앞에 무언가 있다. 숨을 멈췄다. 뺨에 차가운 것이 스친다.<br>그것이 지나갈 때까지 굳어 있었다. 귀에서 걸음 소리가 한참 맴돌았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 }, wake:1 },
    { l:'② 옆 복도 입구에 재를 뿌려 자국이 찍히게 한다.', k:'luck', dc:22,
      ok:`등잔 재를 털어 옆 복도 입구에 뿌렸다. 얇게.<br><br>걸음 소리가 입구를 지난다. 재 위에 자국이 찍힌다. 발이 아니다. 손바닥이다. 손으로 걷는다.<br>손자국이 향하는 쪽을 봤다. 위쪽 계단. 아래로 내려갔다.`,
      ng:`재를 뿌렸다. 걸음 소리가 재 앞에서 멈춘다.<br><br>그리고 재가 날린다. 이쪽 얼굴로. 바람도 없이. 누가 불었다.<br>눈에 재가 들어가 한참 앞을 못 봤다. 눈을 비비는 동안 걸음 소리가 둘레를 돌았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A1', t:'놀이 세트 — 공이 갈라진 자리',
  x:`공 바다 수면이 고르지 않다. 공들이 한 줄로 갈라졌다 닫힌다. 밑에서 무언가 지나간 자리다.<br><br>
    갈라진 줄이 일행 쪽으로 왔다가 돌아간다. 몇 번.<br>
    공 바다 건너편이 계단이다.<br><br>
    추적자는 수면에 남은 길을 읽는다. 물 위 물결을 읽듯이.`,
  o:[
    { l:'① 공이 갈라지는 줄로 밑에 있는 것이 도는 길을 쫓는다.', k:'sense', dc:22,
      ok:`갈라지는 줄을 셌다. 둥글게 돈다. 가운데를 중심으로. 한 바퀴에 숨 스물.<br><br>돌 때마다 같은 자리에서 잠깐 멈춘다. 노란 미끄럼틀 밑. 거기가 굴이다. 밑에 있는 것은 거기로 들어갔다 나온다.<br>그것이 미끄럼틀 밑에서 멈춘 숨 다섯 동안 반대편 가장자리로 건넜다. 공이 허리까지 왔다. 다섯째 숨에 계단을 밟았다.<br><br>보이지 않는 것도 도는 길이 있다. 길이 있으면 쉬는 데가 있다. 그 쉬는 틈을 읽는 눈이 생겼다.`,
      ng:`세다가 줄이 사라졌다. 밑에 있는 것이 멈췄다. 어디서 멈췄는지 모른다.<br><br>공이 고요하다. 가장자리에 선 이쪽 발 바로 앞 공 하나가 혼자 위로 솟는다. 공 밑에 단추 눈 하나.<br>물러서다 놀이 틀 기둥에 머리를 박았다. 눈앞에 별이 튀었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-20 }, wake:1 },
    { l:'② 가장자리 그물을 손발로 타고 건넌다.', k:'evade', dc:22,
      ok:`가장자리에 파란 그물이 쳐져 있다. 공에 빠지지 않게 친 것이다. 그물을 잡고 옆으로 건넜다.<br><br>밑에서 공이 갈라지는 줄이 따라온다. 그물 바로 밑까지. 그물코 사이로 하얀 손가락이 더듬어 올라온다.<br>손가락이 그물코에 걸리기 전에 건너편에 닿았다.`,
      ng:`그물이 출렁인다. 밑에서 누가 잡아당긴다.<br><br>그물이 공 바다 쪽으로 처진다. 엉덩이가 공에 닿는다. 차가운 것이 허리를 감는다.<br>그물을 놓지 않고 버텼다. 손가락이 그물코에 파고들어 피가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A2', t:'강당 — 줄 선 발자국',
  x:`강당 바닥은 물에 잠겼다. 물이 맑다. 바닥에 발자국이 패어 있다. 줄지어. 조회 때처럼.<br><br>
    한 줄에 열 쌍. 스물한 줄. 그리고 둘이 더. 이백열둘.<br>
    맨 끝 줄에 빈자리가 있다. 패지 않은 자리. 몇 개.<br><br>
    추적자는 패인 깊이를 본다. 몇 해를 서 있었는지.`,
  o:[
    { l:'① 줄 사이 패지 않은 바닥만 밟고 무대까지 간다.', k:'sense', dc:22,
      ok:`패인 자리는 깊다. 손가락 한 마디. 몇 해를 같은 자리에 섰다.<br><br>줄과 줄 사이는 패지 않았다. 아무도 줄 사이로 다니지 않았다. 줄을 벗어나면 안 되니까. 그래서 줄 사이가 안전하다. 아무것도 그 사이를 보지 않는다.<br>줄 사이로만 걸었다. 무대 앞에 닿았다. 뒤에서 물이 줄마다 한 번씩 흔들렸다. 차렷 하듯이.`,
      ng:`줄 사이로 걷다 패인 자리 하나를 디뎠다. 발이 쏙 맞게 들어간다.<br><br>발이 빠지지 않는다. 그 자리가 발을 꼭 잡는다. 그 줄 물이 전부 이쪽으로 기운다.<br>일행이 다리를 잡아 뺐다. 신발이 그 자리에 남았다. 맨발로 걸었다. 발바닥이 차다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-12, spirit:-20 } },
    { l:'② 일행에게 줄 밖, 벽을 따라서만 걷게 한다.', k:'fix', dc:22,
      ok:`벽을 따라 강당을 돌았다. 멀다. 한 줄도 건드리지 않았다.<br><br>벽에 아이들 그림이 붙어 있다. 물속에서 색이 번졌다. 그림마다 줄 선 아이들. 맨 끝에 빈칸.<br>무대 옆 계단에 닿았다. 그림 하나에는 아이가 혼자 줄 밖에 서 있다. 그 아이 발밑에 화살표. 이 계단이다.`,
      ng:`벽을 따라 걷는데 그림 속 줄이 이쪽을 따라 고개를 돌린다.<br><br>그림 속 맨 끝 빈칸에 아이가 새로 그려지고 있다. 물감이 번지며. 일행 하나의 얼굴이다.<br>그 그림을 떼어 찢었다. 손가락에 물감이 묻었다. 그 일행 얼굴 색이었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'③ 맨 끝 줄 빈자리 하나를 밟아 본다.', k:'luck', dc:23,
      doom:{ title:'빈자리', what:'빈자리에 발이 묶여 물 밑으로 끌려 내려갑니다', dc:19, sec:40,
        text:`빈자리 하나에 발을 놓았다. 패지 않은 바닥이다. 단단하다.<br><br>밟은 순간 바닥이 패인다. 발 모양으로. 몇 해를 서 있던 것처럼 깊게. 발이 빠지지 않는다.<br>줄 앞쪽에서 목소리가 올라온다. 이름을 부른다. 앞에서부터. 이쪽 차례가 다가온다. 물이 무릎에서 허리로. 바닥이 이쪽을 아래로 당긴다. 선 자리째로.`,
        dieText:`강당 물이 다시 맑아졌다.<br><br>맨 끝 줄 빈자리가 하나 줄었다. 패인 자국이 새로 생겼다. 신발 자국이다.<br>점호에서 이백열세 번째 이름이 불렸다. 대답이 있었다.` },
      ok:`빈자리 옆에 섰다. 밟지 않고 손으로 짚었다. 손바닥 모양으로 바닥이 패인다. 천천히.<br><br>손을 뗐다. 손자국이 남았다. 빈자리가 하나 줄었다. 손자국이 채운 것이다. 사람 하나는 못 채운다.<br>줄 앞쪽에서 이름이 불리다 멈췄다. 손자국 차례에서. 대답이 없다. 그 사이 무대 쪽으로 건넜다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'끝난 자국 — 벽 앞에서',
  x:`발자국이 벽 앞에서 끝난다. 돌아선 자국이 없다. 옆으로 간 자국도 없다.<br><br>
    벽은 돌이다. 문은 없다.<br>
    추적자는 끝난 자국을 믿지 않는다. 자국은 끝나지 않는다. 바닥을 떠날 뿐이다.<br><br>
    바닥을 떠난 자국은 위로 간다.`,
  o:[
    { l:'① 위를 보지 않고 벽의 손때를 읽는다.', k:'sense', dc:22,
      ok:`위를 보면 위에 있는 것과 눈이 마주친다. 대신 벽을 봤다.<br><br>벽돌 몇 개가 반들거린다. 손때다. 사람 키 높이에서 시작해 위로 이어진다. 손 디딘 자리가 일정하다. 많이 다닌 길이다.<br>손때가 천장 구멍까지 이어진다. 그것은 지금 구멍 안에 있다. 손때 없는 반대쪽 벽을 따라 지나갔다. 구멍 밑을 지날 때 바닥만 봤다.`,
      ng:`손때를 보는데 벽돌 하나가 따뜻하다. 방금 짚었다.<br><br>손때가 바로 머리 위 벽돌에서 끝난다. 지금 짚고 있는 자리다.<br>머리 위에서 숨소리가 난다. 고개를 숙인 채 뒷걸음질 쳤다. 정수리에 손가락이 닿았다 떨어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-12, spirit:-20 } },
    { l:'② 자국이 끝난 자리에 서서 올려다본다.', k:'gaze', dc:23,
      doom:{ title:'바닥을 떠난 자국', what:'위에서 내려온 것에게 들려 끌려 올라갑니다', dc:18, sec:50,
        text:`발자국 끝에 섰다. 올려다봤다.<br><br>천장에 구멍이 있다. 구멍 안에 얼굴이 있다. 거꾸로. 이쪽을 내려다본다. 눈이 마주쳤다.<br>팔이 내려온다. 길다. 겨드랑이 밑을 받친다. 아이를 안아 올리듯. 발이 뜬다. 발자국 끝에서. 구멍이 다가온다.`,
        dieText:`일행이 불을 비췄다. 발자국이 벽 앞에서 끝난다.<br><br>두 줄이다. 하나는 맨발. 하나는 신발.<br>둘 다 거기서 끝난다. 아무도 올려다보지 않았다.` },
      ok:`올려다보기 전에 불을 먼저 들었다. 천장 구멍에 불을 밀어 넣듯이.<br><br>구멍 안에서 얼굴이 빛을 피해 안쪽으로 물러난다. 얼굴만 봤다. 사람 얼굴이다. 눈을 감고 있다.<br>불을 든 채 그 밑을 지나갔다. 위에서 무언가 구멍 가장자리를 붙잡고 기다리는 소리가 났다. 불이 지나갈 때까지.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'일행 하나 — 바뀐 걸음',
  x:`일행 하나의 걸음이 바뀌었다. 아무도 모른다. 본인도.<br><br>
    추적자는 일행 발자국을 다 외운다. 버릇처럼. 그 일행은 원래 왼발을 조금 바깥으로 딛는다.<br>
    지금은 곧다. 발끝이 반듯하다. 너무 반듯하다.<br><br>
    어느 모퉁이에서 바뀌었는지 모른다.`,
  o:[
    { l:'① 지나온 발자국을 되짚어 걸음이 바뀐 자리를 찾는다.', k:'sense', dc:22,
      ok:`되짚었다. 바깥으로 딛던 왼발. 바깥으로. 바깥으로. 문 하나를 지난 뒤부터 곧다.<br><br>그 문 앞 발자국을 봤다. 바깥으로 딛던 발자국은 문 안으로 들어간다. 곧은 발자국은 문에서 나온다. 같은 신발이다.<br>문을 열었다. 안쪽에 그 일행이 앉아 있다. 잠든 듯 눈을 감고. 흔들어 깨웠다. 일어서는 왼발이 바깥으로 비틀렸다.<br>돌아보니 곧은 발자국의 일행은 없다. 발자국만 문 앞에서 끝났다.<br><br>사람은 얼굴보다 걸음이 먼저 거짓말을 못 한다. 걸음 하나로 사람을 가려내는 눈이 몸에 붙었다.`,
      ng:`되짚는데 곧은 발자국이 처음부터 곧다. 들어올 때부터.<br><br>그 일행은 원래 이렇게 걸었던가. 외웠던 발자국이 기억에서 흐려진다.<br>아무것도 확신할 수 없었다. 그 뒤로 그 일행 등을 볼 때마다 목이 조였다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-22 }, wake:1 },
    { l:'② 모른 척하고 그 일행을 맨 앞에 세운다.', k:'hide', dc:22,
      ok:`아무 말 없이 그 일행을 앞에 세웠다. 이쪽은 바로 뒤에 붙었다.<br><br>그 일행은 길을 잘 안다. 처음 오는 데인데. 갈림길마다 망설이지 않는다.<br>세 번째 갈림길에서 그 일행이 고른 반대쪽으로 일행을 끌고 갔다. 그 일행은 따라오지 않았다. 갈림길에 서서 웃었다. 일행 얼굴이 아닌 웃음으로.`,
      ng:`그 일행을 앞에 세웠다. 그 일행이 걸음을 멈추고 돌아선다.<br><br>이쪽을 본다. 이쪽 발을 본다. 발자국을 읽는 사람을 읽는 눈이다.<br>입이 웃는다. 알았구나. 그 말은 하지 않았는데 들렸다. 그날 밤 아무도 잠들지 못했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } },
    { l:'③ 신발을 말리자며 그 일행 신을 벗겨 본다.', k:'gaze', dc:22,
      ok:`쉬는 자리에서 신발을 말리자며 벗겼다.<br><br>발이 젖어 있다. 신발은 말랐는데 발만. 발바닥이 하얗게 불었다. 물속에 오래 있던 발이다.<br>그 일행이 발을 감춘다. 그 뒤로 그 일행을 가운데 세웠다. 다들 등을 맞대고 잤다.`,
      ng:`벗기려는데 그 일행이 발을 뺀다. 세게.<br><br>발길에 가슴을 맞았다. 숨이 막혔다. 그 일행이 사과한다. 원래 목소리로.<br>그 목소리가 원래 목소리인지 확신이 서지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A', t:'추적 — 쫓으라고 남긴 자국',
  x:`무언가의 자국이 있다. 핏방울과 함께. 다쳐서 달아났다. 그렇게 보인다.<br><br>
    자국이 너무 또렷하다. 발자국마다 반듯하게 찍혔다. 핏방울 간격이 고르다.<br>
    다쳐 달아나는 것은 그렇게 걷지 못한다.<br><br>
    쫓으라고 남긴 자국이다.`,
  o:[
    { l:'① 일부러 남긴 자국 옆에서 진짜 자국을 가른다.', k:'sense', dc:22,
      ok:`또렷한 자국 옆을 훑었다. 먼지가 다르게 쓸린 자리. 아주 흐리다. 발끝만 스친 자국이다.<br><br>흐린 자국은 반대쪽으로 간다. 또렷한 자국을 찍어 놓고 흐린 쪽으로 돌아와 숨었다. 쫓는 사람 등 뒤로 오려고.<br>또렷한 쪽으로 몇 걸음 가는 척하다 돌아섰다. 흐린 자국 끝 기둥 뒤에 무언가 웅크리고 있었다. 불을 들이대자 비명을 지르고 달아났다.`,
      ng:`가르는 사이 흐린 자국이 하나 더 생긴다. 등 뒤에.<br><br>돌아섰다. 늦었다. 어깨를 무언가 문다. 차다. 이가 많다.<br>떼어 냈다. 어깨에 둥근 이빨 자국이 남았다. 사람 이빨 자국이었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 무력으로 쫓는 척하다 돌아서 먼저 친다.', k:'break', dc:22, cost:{ might:30 },
      ok:`자국을 쫓는 척 크게 걸었다. 그리고 갑자기 몸을 낮춰 힘을 실어 뒤로 뛰었다.<br><br>등 뒤로 오던 것과 마주쳤다. 그것이 예상하지 못했다. 힘을 실은 팔꿈치가 먼저 닿았다. 그것이 벽에 부딪혀 주저앉는다.<br>일어나기 전에 일행을 끌고 지나갔다. 쫓는 쪽과 쫓기는 쪽이 한 번 바뀌었다.`,
      ng:`뒤로 뛰었다. 아무것도 없다. 그것은 등 뒤가 아니라 앞에 있었다. 또렷한 자국 끝에.<br><br>앞에서 덮쳤다. 힘을 실어 밀어냈다. 밀어낸 팔에 이빨 자국이 남았다.<br>그것이 다시 어둠으로 들어갔다. 이번엔 자국 하나 남기지 않고.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'A', t:'쉬는 자리 — 밤새 늘어난 자국',
  x:`쉬는 자리에서 깼다. 둘레 먼지 위에 자국이 나 있다.<br><br>
    잠든 일행을 빙 둘렀다. 한 바퀴. 두 바퀴. 몇 바퀴인지 모르게 겹쳤다.<br>
    안으로 들어온 자국은 없다. 둘레만 돌았다.<br><br>
    추적자는 겹친 자국을 한 겹씩 벗긴다.`,
  o:[
    { l:'① 겹친 자국으로 몇 번 돌았는지, 무엇이 막았는지 읽는다.', k:'sense', dc:22,
      ok:`맨 아래 자국이 가장 흐리다. 처음 돈 것이다. 맨 위가 가장 또렷하다. 세어 보니 열세 바퀴.<br><br>바퀴마다 한 자리에서 발끝이 안쪽으로 돈다. 들어오려다 멈춘 자리다. 거기 일행 하나가 깔고 잔 외투 소매가 있다. 소매에서 소금 덩이가 굴러 나와 있다. 짐에서 흘렀다.<br>소금 앞에서 열세 번 멈췄다. 소금을 부숴 둘레에 한 줄로 뿌렸다. 그다음 밤은 자국이 한 바퀴뿐이었다.<br><br>자국이 왜 멈췄는지까지 읽는다. 무엇을 피하는지 알면 무엇을 쥐어야 하는지도 안다.`,
      ng:`세다가 자국 하나가 안으로 들어온 것을 봤다. 딱 하나. 일행 머리맡까지.<br><br>머리맡에 오래 서 있었다. 자국이 깊다. 거기서 내려다봤다.<br>그 일행을 깨웠다. 꿈에서 누가 이름을 불렀다고 했다. 대답했냐고 물었다. 대답은 하지 않았다고 했다.`,
      win:{ exp:22, dream:3, item:'소금 덩이' }, lose:{ mind:-18, spirit:-22 }, wake:1 },
    { l:'② 아무것도 묻지 않고 곧장 자리를 뜬다.', k:'evade', dc:22,
      ok:`일행을 깨웠다. 짐을 챙겼다.<br><br>자국을 밟지 않고 넘었다. 다들 넘었다. 뒤돌아보지 않았다.<br>한참 가서야 일행 하나가 물었다. 왜 서둘렀냐고. 대답하지 않았다. 대답하면 그 자국이 다시 생각날 것 같았다.`,
      ng:`서두르다 자국 하나를 밟았다. 발이 그 자국에 맞는다. 꼭.<br><br>그 뒤로 발소리가 하나 더 났다. 이쪽 걸음에 맞춰. 밟은 자국의 주인이 이쪽 걸음을 빌린 것처럼.<br>한나절 그 발소리를 달고 다녔다. 다리가 두 배로 무거웠다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] }
]);

// ------------------------------------------
// 탐지술사 (seeker) · 자원: 마력
// ------------------------------------------
kJob('seeker', 'A', [
{ at:'A', t:'첫 술식 — 숨이 하나 더',
  x:`탐지술을 편다. 마력이 바닥을 타고 일행 발밑으로 번진다.<br><br>
    일행 숨이 잡힌다. 하나씩. 따뜻하다. 박동이 있다.<br>
    하나가 더 잡힌다. 일행 사이에 서 있다. 숨은 쉬는데 따뜻하지 않다.<br><br>
    눈으로 보면 일행뿐이다.`,
  o:[
    { l:'① 숨마다 온기와 박동을 짚어 그 하나가 누구 곁인지 가린다.', k:'sense', dc:22,
      ok:`서두르지 않았다. 하나씩 짚었다. 숨, 온기, 박동. 숨, 온기, 박동.<br><br>한 자리에서 숨만 있다. 온기와 박동이 없다. 숨만 일행 숨을 따라 쉰다. 자리는 맨 뒤 일행의 등 뒤, 손 한 뼘.<br>그 일행을 불러 이쪽 앞으로 세웠다. 마력 속에서 숨 하나가 제자리에 남는다. 따라오지 못한다. 그것은 등 뒤에만 설 수 있다.<br>일행을 둥글게 세웠다. 등이 다 안쪽을 보게. 등 뒤가 없어지자 숨이 흐려졌다.<br><br>마력으로 짚는 것이 하나가 아니라 셋이 됐다. 숨과 온기와 박동. 셋이 맞지 않는 것을 마력이 먼저 골라낸다.`,
      ng:`짚는 사이 그 숨이 이쪽 마력을 느꼈다. 숨이 멈춘다.<br><br>그리고 이쪽 등 뒤에서 다시 쉰다. 차갑다. 목덜미에 닿는다.<br>술식을 끊었다. 코피가 흘렀다. 등 뒤가 한참 시렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-22 }, wake:1 },
    { l:'② 마력을 거두고 불을 들어 얼굴을 센다.', k:'gaze', dc:22,
      ok:`술식을 접었다. 불을 들어 얼굴을 하나씩 비췄다. 다 일행이다.<br><br>마지막 얼굴을 비출 때 그 그림자를 봤다. 벽에 비친 그림자가 둘이다. 하나는 그 일행. 하나는 그 뒤에 선 키 큰 것.<br>불을 내렸다. 그 일행을 가운데로 불렀다. 그림자 하나가 따라오지 않고 벽에 남았다.`,
      ng:`얼굴을 셌다. 맞다. 마력을 다시 펴 봤다. 숨이 하나 많다.<br><br>눈과 마력이 서로 다른 말을 한다. 어느 쪽을 믿어야 할지 모른다.<br>둘 다 믿지 못한 채 걸었다. 그날 머리가 깨질 듯 아팠다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'A1', t:'의상실 — 따뜻한 인형탈',
  x:`의상실에 인형탈이 줄지어 걸려 있다. 방글이, 뭉치, 삐뚤이. 여러 벌.<br><br>
    탈은 비어 있어야 한다. 사람이 들어가야 움직인다.<br>
    탐지술을 편다. 탈마다 차갑다. 천과 솜뿐이다.<br><br>
    한 벌이 따뜻하다. 사람 체온만큼.`,
  o:[
    { l:'① 따뜻한 탈 속 반응을 겹겹이 짚는다.', k:'sense', dc:22,
      ok:`마력을 그 탈에 얇게 밀었다. 안이 그려진다. 머리 자리에 머리. 팔 자리에 팔. 사람이다.<br><br>숨은 있다. 아주 얕다. 박동이 느리다. 오래 잔 숨이다. 박동 사이가 조금씩 길어진다. 탈 속 사람이 탈이 되어 가고 있다.<br>지퍼를 목덜미까지만 내렸다. 바람이 들어가자 숨이 조금 깊어졌다. 더는 어쩔 수 없었다. 그 탈 앞을 지날 때 일행 모두 고개를 숙였다.<br><br>마력이 겉이 아니라 겉 속의 겉까지 내려간다. 천 한 겹, 살 한 겹. 겹을 세는 일이 숨 쉬듯 된다.`,
      ng:`짚는 순간 따뜻한 반응이 이쪽 마력을 붙잡는다. 손처럼.<br><br>마력을 타고 무언가 올라온다. 좀약 냄새. 털. 손끝이 털로 덮이는 것 같다.<br>술식을 끊었다. 손끝이 한참 저렸다. 탈 하나가 고개를 이쪽으로 돌린 채 걸려 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-14, spirit:-18 }, wake:1 },
    { l:'② 마력으로 탈마다 냉기를 흘려 움찔하는 것을 가린다.', k:'gaze', dc:22, cost:{ mana:25 },
      ok:`냉기를 옷걸이 레일을 따라 흘렸다. 찬 것은 그대로다. 따뜻한 것은 움찔한다.<br><br>움찔한 탈이 셋이다. 하나인 줄 알았다. 둘은 따뜻하지 않은데 움찔했다. 냉기를 싫어하는 것이다.<br>셋을 피해 의상실 뒷문으로 나갔다. 나가는 동안 탈 셋이 옷걸이에서 조금씩 미끄러졌다.`,
      ng:`냉기를 흘렸다. 탈들이 일제히 움찔한다. 전부.<br><br>옷걸이 레일이 덜컹 움직인다. 탈들이 이쪽으로 밀려온다. 한 줄로.<br>레일 끝 벽에 몰렸다. 탈 사이에 끼어 숨을 못 쉬었다. 솜 냄새가 목을 막았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A2', t:'종탑 아래 — 줄 선 온기',
  x:`배 위에서 탐지술을 물 밑으로 내린다. 깊다. 마력이 한참 내려간다.<br><br>
    반응이 돌아온다. 미지근한 것이 수백. 층마다 줄지어 있다. 교실 책상 배치대로.<br>
    다 가만있다. 박동이 없다. 그런데 미지근하다.<br><br>
    줄과 줄 사이로 배가 지나가야 한다.`,
  o:[
    { l:'① 줄과 줄 사이, 반응이 없는 물길을 고른다.', k:'sense', dc:22,
      ok:`줄은 반듯하다. 사이도 반듯하다. 반듯한 사이가 물길이다.<br><br>노 젓는 일행에게 손짓으로 방향을 줬다. 왼쪽. 곧장. 오른쪽. 미지근한 줄이 배 밑으로 지나간다. 하나도 건드리지 않았다.<br>종탑에 닿을 무렵 반응 하나가 조금 따뜻해졌다. 이쪽을 알아본 것이다. 따라오지는 않았다.<br><br>수백 개 사이로 길 하나를 그린다. 반응을 세는 게 아니라 반응이 없는 데를 그린다. 그쪽이 마력이 덜 든다. 덜 든 마력이 오래 버틴다.`,
      ng:`사이를 고르는데 반응 하나가 줄을 벗어난다. 배 밑으로.<br><br>배 밑바닥에 무엇이 닿는다. 툭. 툭. 두드린다. 문 두드리듯이.<br>술식을 거두고 노를 같이 저었다. 두드림이 종탑까지 따라왔다. 배 바닥에 작은 손자국이 하얗게 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 }, wake:1 },
    { l:'② 술식을 끊고 노만 젓는다. 모르는 게 나을 때도 있다.', k:'steady', dc:21,
      ok:`마력을 거뒀다. 수백 개가 머리에서 사라진다. 물만 남는다.<br><br>노를 저었다. 물이 평평하다. 아무것도 모르는 물이다.<br>종탑에 닿았다. 배 밑에 무엇이 스쳤는지는 끝내 몰랐다. 몰라서 노를 끝까지 저을 수 있었다.`,
      ng:`마력을 거뒀다. 그런데 반응이 머리에서 안 떠난다. 수백 개가 눈꺼풀 안쪽에 줄지어 있다.<br><br>노를 저을 때마다 그 줄이 하나씩 고개를 든다. 이쪽 머릿속에서.<br>종탑에 닿았을 때 손이 떨려 밧줄을 못 묶었다. 일행이 대신 묶었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-24 } }
  ] },

{ at:'A', t:'되돌아오는 탐지 — 이쪽을 짚는 손',
  x:`술식을 펴자 반응 하나가 걸린다. 멀다. 그런데 이상하다. 저쪽에서도 마력이 온다.<br><br>
    저쪽도 짚고 있다. 이쪽을.<br>
    저쪽 마력이 일행을 하나씩 훑는다. 숨, 온기, 박동. 이쪽이 하는 것과 같은 순서로.<br><br>
    마지막으로 이쪽에 닿는다. 멈춘다.`,
  o:[
    { l:'① 마력을 일행 숨에 섞어 짚는 손을 숨긴다.', k:'hide', dc:22, cost:{ mana:30 },
      ok:`마력을 거두지 않았다. 대신 일행 숨에 섞었다. 이쪽 반응이 일행 반응 사이에 녹는다. 짚는 손이 하나 줄어든 것처럼.<br><br>저쪽 마력이 다시 훑는다. 숨, 온기, 박동. 짚는 손을 찾는다. 없다.<br>저쪽 마력이 거둬졌다. 갸웃하는 듯이. 그 사이 반대쪽 길로 일행을 이끌었다.`,
      ng:`섞으려다 마력이 흔들렸다. 저쪽이 그 흔들림을 잡았다.<br><br>머릿속에 그림이 들어온다. 이쪽 뒷모습. 일행. 멀리서 본 것이다. 저쪽이 보는 것이 이쪽 머리에 들어온다.<br>술식을 끊었다. 그림은 남았다. 뒷모습 너머로 손 하나가 이쪽 어깨를 향해 뻗어 있었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 피하지 않고 마력을 더 밀어 저쪽을 마주 짚는다.', k:'gaze', dc:23,
      doom:{ title:'마주 짚은 손', what:'정신이 저쪽으로 끌려갑니다', dc:18, sec:55,
        text:`피하지 않았다. 마력을 더 밀었다. 저쪽이 짚인다. 저쪽도 이쪽을 짚는다.<br><br>두 마력이 맞닿는다. 손바닥과 손바닥처럼. 그 순간 저쪽이 손가락을 깍지 낀다.<br>당긴다. 마력이 끌려간다. 마력을 따라 생각이 끌려간다. 몸이 멀어진다. 서 있는 자기를 멀리서 본다. 돌아가는 길이 마력 끝에서 끊긴다.`,
        dieText:`몸은 거기 서 있었다. 눈을 뜨고. 숨도 쉬었다.<br><br>일행이 불러도 돌아보지 않았다. 다만 가끔 손바닥을 펴 허공을 짚었다.<br>저 멀리 어둠 속에서 누군가 일행 숨을 하나씩 짚었다. 이쪽이 하던 순서로.` },
      ok:`마주 짚었다. 저쪽 손이 깍지를 끼려 한다. 손가락을 펴지 않았다. 주먹을 쥐듯 마력을 오므렸다.<br><br>저쪽 마력이 오므린 끝을 더듬다 놓친다. 짚을 데가 없으니까.<br>대신 저쪽 자리가 남았다. 층 반대편, 아래. 그 자리를 기억해 두고 일행을 위로 돌렸다. 마력 끝이 한참 얼얼했다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'A1', t:'테이프 보관실 — 테이프 속 숨',
  x:`테이프 보관실 선반에 녹화 테이프가 빽빽하다. 회차마다 한 개. 방글 동산 1회, 2회, 수백 회.<br><br>
    탐지술을 편다. 테이프는 차가워야 한다. 대부분 차갑다.<br>
    몇 개에서 숨이 잡힌다. 아주 작다. 테이프 속에서.<br><br>
    숨 쉬는 칸이 통로를 따라 띄엄띄엄 있다.`,
  o:[
    { l:'① 숨 쉬는 칸을 머리에 깔고 숨 없는 칸 앞으로만 지난다.', k:'sense', dc:22,
      ok:`숨 쉬는 칸을 하나씩 짚어 머리에 깔았다. 그 칸 앞을 지나지 않고 선반 사이를 돌았다.<br><br>숨 쉬는 칸 근처를 지날 때마다 테이프 속 숨이 빨라졌다. 가까이 오는 것을 안다. 그래서 가까이 가지 않았다.<br>보관실 끝 문에 닿았다. 등 뒤에서 데크 하나가 혼자 돌기 시작했다. 아무도 그 앞에 서지 않았는데.`,
      ng:`짚는데 숨 쉬는 칸이 늘어난다. 하나. 셋. 다섯. 이쪽 마력이 닿을 때마다 깬다.<br><br>마력이 깨운 것이다. 통로가 숨으로 가득해진다. 지날 칸이 없다.<br>술식을 끊고 기어서 지났다. 칸마다 테이프 줄이 조금씩 풀려 나와 바닥에서 꿈틀거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14, spirit:-18 } },
    { l:'② 숨 쉬는 테이프 하나를 꺼내 안을 짚는다.', k:'luck', dc:23,
      doom:{ title:'녹화된 숨', what:'테이프 줄에 감겨 데크 안으로 끌려 들어갑니다', dc:18, sec:50,
        text:`테이프 하나를 꺼냈다. 등에 적혀 있다. 오늘의 친구. 날짜는 비었다.<br><br>손바닥 위에서 숨이 쉰다. 마력으로 짚었다. 안에 사람이 있다. 작게 접혀서. 그 사람이 이쪽을 짚는다.<br>테이프 줄이 풀려 나온다. 손목에 감긴다. 옆 데크가 혼자 열린다. 줄이 데크로 감겨 들어간다. 손목째. 데크 입이 생각보다 넓다.`,
        dieText:`보관실 데크가 멈췄다. 딸깍.<br><br>선반에 테이프가 하나 늘었다. 등에 이쪽 이름이 적혀 있다. 오늘의 친구.<br>숨을 쉰다. 아주 작게.` },
      ok:`꺼내지 않고 칸에 꽂힌 채로 짚었다. 손끝만 테이프 등에 대고.<br><br>안에 사람이 있다. 작게 접혀서. 자고 있다. 라벨에 날짜가 있다. 몇 해 전이다. 그 밑에 적혀 있다. 오늘의 친구.<br>손을 뗐다. 그 옆 빈칸에 꽂힐 다음 테이프가 이미 준비되어 있었다. 라벨이 비었다. 라벨을 떼어 찢었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'사감실 — 의자에 앉은 냉기',
  x:`사감실 유리문 안에 의자가 문 쪽을 보고 놓였다. 비어 있다.<br><br>
    탐지술을 유리 너머로 민다. 의자에 반응이 있다. 차갑다. 물보다 차다. 앉은 모양이다.<br>
    벽에 열쇠 꾸러미가 걸려 있다. 강당 열쇠가 필요하다.<br><br>
    박동이 없는 것은 언제 일어설지 알 수 없다. 대개는.`,
  o:[
    { l:'① 냉기의 결을 읽어 일어서는 박자를 잡는다.', k:'sense', dc:22,
      ok:`박동은 없다. 그래도 냉기에 결이 있다. 아주 느리게 짙어졌다 옅어진다. 숨 쉬던 버릇이 남은 것이다.<br><br>짙어질 때 냉기가 문 쪽으로 기운다. 옅어질 때 등받이로 기댄다. 기댈 때가 문에서 가장 멀다.<br>세 번째로 기댈 때 문을 열고 들어가 열쇠를 집었다. 네 번째가 오기 전에 나왔다. 유리문이 닫히는 순간 냉기가 의자에서 일어섰다.`,
      ng:`결을 읽는데 냉기가 이쪽 마력을 마신다. 물이 열을 먹듯이.<br><br>손끝부터 얼어 온다. 마력이 냉기 쪽으로 빨려 간다. 끊으려는데 안 끊긴다.<br>일행이 손목을 잡아 유리에서 떼어 냈다. 손가락 끝이 하얗게 질려 한참 구부러지지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 마력으로 유리문 틈에 막을 쳐 냉기를 가둔다.', k:'steady', dc:22, cost:{ mana:30 },
      ok:`유리문 틈마다 마력을 발랐다. 따뜻한 막이다. 냉기는 따뜻한 것을 넘지 못한다.<br><br>막 안에서 냉기가 일어선다. 유리에 손바닥 자국이 서린다. 안쪽에서. 문이 열리지 않는다.<br>그 사이 사감실 옆 쪽창으로 손을 넣어 열쇠를 걷었다. 막이 버티는 동안 마력이 빠르게 빠져나갔다. 머리가 하얬다.`,
      ng:`막을 쳤다. 냉기가 막을 만진다. 막이 하얗게 얼어 간다.<br><br>언 막이 유리째 금이 간다. 마력을 더 부었다. 금이 이쪽 손바닥까지 기어 온다.<br>손을 떼자 막이 깨졌다. 유리문은 버텼다. 열쇠는 못 꺼냈다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'③ 의자 뒤로 돌아가 열쇠 꾸러미를 집는다.', k:'hide', dc:23,
      doom:{ title:'빈 의자', what:'사감에게 손목을 잡혀 출석부 쪽으로 끌려갑니다', dc:18, sec:50,
        text:`유리문을 소리 없이 열었다. 의자 뒤로 돌았다. 의자는 문을 보고 있다. 등 뒤는 안 본다.<br><br>열쇠에 손이 닿는다. 그때 의자 냉기가 돌아앉는다. 의자는 그대로인데 냉기만.<br>손목을 잡힌다. 물처럼 차고 단단하다. "점호 시간이 다 됐구나." 책상 위 출석부가 펼쳐진다. 그쪽으로 손목이 끌려간다. 펜이 손에 쥐여진다.`,
        dieText:`출석부 마지막 줄에 이름이 적혔다. 이쪽 글씨로.<br><br>사감실 의자가 비었다. 냉기가 둘로 늘었다. 하나는 의자에, 하나는 문 옆에 선다.<br>문 옆 냉기가 열쇠 꾸러미를 들고 있다. 찰랑.` },
      ok:`의자 뒤로 돌았다. 마력을 아주 얇게 펴서 냉기 끝만 짚었다. 냉기가 문을 향해 있다.<br><br>문을 향한 것은 뒤를 모른다. 열쇠를 들었다. 쇠끼리 닿지 않게 손바닥으로 감쌌다. 강당 열쇠가 꾸러미에 있다.<br>나오면서 유리문을 닫았다. 냉기가 그제야 돌아앉았다. 빈 고리를 향해.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'벽 너머 — 손바닥을 댄 것',
  x:`막다른 벽이다. 손바닥을 대고 탐지술을 편다.<br><br>
    벽 너머가 비었다. 길이다. 그런데 바로 벽 너머에 반응이 있다. 따뜻하다. 이쪽 손바닥 자리에 손바닥을 대고 있다.<br>
    벽 하나를 사이에 두고.<br><br>
    손을 떼면 저쪽도 뗄까.`,
  o:[
    { l:'① 손을 떼지 않고 그것의 크기와 숨을 잰다.', k:'sense', dc:22,
      ok:`떼지 않았다. 마력을 손바닥에서 조금씩 넓혔다. 저쪽 손바닥, 손목, 팔. 팔이 길다. 어깨가 높다. 사람 키 둘.<br><br>숨은 느리다. 벽에 기대 잠든 숨이다. 손바닥은 우연히 겹쳤다. 자다가 벽을 짚은 것이다.<br>마력을 접고 손을 아주 천천히 뗐다. 저쪽 손바닥은 그대로다. 벽을 따라 저것의 발끝 쪽으로 갔다. 거기 틈이 있다. 잠든 숨을 하나도 흐트러뜨리지 않고 빠졌다.<br><br>벽 하나를 사이에 두고 상대의 키와 잠까지 잰다. 손바닥 하나로 짚는 것이 그만큼 늘었다.`,
      ng:`크기를 재는데 저쪽 손바닥이 움직인다. 손가락을 하나씩 접는다. 이쪽 손가락 사이로 깍지를 끼듯.<br><br>벽인데. 손가락 사이가 차다. 손을 뗐다. 손가락 사이 살갗에 돌가루가 묻어 있다.<br>벽 너머에서 숨이 깼다. 긴 숨이 한 번 뱉어진다. 이쪽 쪽으로.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-22 }, wake:1 },
    { l:'② 마력으로 벽을 달궈 저쪽을 떼어 낸다.', k:'break', dc:22, cost:{ mana:25 },
      ok:`손바닥으로 마력을 밀어 벽을 데웠다. 돌이 미지근하다가 뜨거워진다.<br><br>저쪽 손바닥이 떨어진다. 데인 것처럼. 저쪽 반응이 벽에서 멀어진다. 멀리.<br>벽을 따라 다른 틈을 찾아 넘어갔다. 넘어가 보니 벽에 손바닥 자국이 그을려 있었다. 이쪽 손보다 두 배 크다.`,
      ng:`벽을 데우자 저쪽은 식힌다. 벽이 이쪽 손바닥 자리만 얼어붙는다.<br><br>손이 안 떨어진다. 마력을 끊었다. 손바닥 살갗이 벽에 조금 남았다.<br>벽 너머에서 무언가 그 살갗을 핥는 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A1', t:'방청석 — 빈자리의 온기',
  x:`방청석이 비어 있다. 수백 자리. 눈으로는.<br><br>
    탐지술을 편다. 자리마다 온기가 있다. 다는 아니다. 띄엄띄엄. 앉은 사람 온기다.<br>
    온기가 있는 자리는 박수를 친다. 소리 없이. 손바닥 마주치는 떨림만 마력에 닿는다.<br><br>
    방청석을 가로질러야 한다. 빈자리를 밟고.`,
  o:[
    { l:'① 온기 없는 자리만 이어 건널 길을 그린다.', k:'sense', dc:22,
      ok:`온기를 하나하나 짚어 머릿속에 칸을 그렸다. 차가운 칸이 비스듬히 줄을 이룬다. 방청석 끝 문까지.<br><br>그 칸만 밟고 건넜다. 일행에게 이쪽 발자국만 밟게 했다. 지날 때마다 옆자리 온기가 고개를 돌린다. 손을 뻗지는 않는다. 앉아 있어야 하니까.<br>끝 문에 닿았다. 돌아보니 차가운 칸 하나에 온기가 새로 생겼다. 맨 뒤 일행이 디딘 자리다. 그 일행 온기가 조금 남은 것이다.<br><br>사람이 안 보이는 자리에서 사람을 센다. 수백 개를 한 번에 짚어도 머리가 버틴다.`,
      ng:`칸을 그리는데 온기가 옮겨 다닌다. 이쪽이 그린 길 위로.<br><br>길 한가운데 온기가 앉는다. 이쪽이 디디려는 자리에. 발을 멈췄다. 몸이 기울었다. 앞 의자 등받이에 갈비뼈를 박았다.<br>숨이 한참 안 쉬어졌다. 그 사이 둘레 온기들이 박수를 쳤다. 소리 없이.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 }, wake:1 },
    { l:'② 마력으로 줄마다 냉기를 쓸어 앉은 것들을 일으킨다.', k:'break', dc:22, cost:{ mana:30 },
      ok:`앞줄부터 냉기를 쓸었다. 온기가 냉기에 밀려 일어선다. 자리를 비운다.<br><br>일어선 온기들이 뒤로 물러난다. 벽 쪽으로. 줄 하나가 통째로 비었다. 그 줄로 건넜다.<br>벽에 붙은 온기들이 다시 앉으려고 기다렸다. 이쪽이 다 지나가기를.`,
      ng:`냉기를 쓸었다. 온기가 일어서지 않는다. 더 단단히 앉는다. 그리고 냉기를 따라 이쪽을 짚는다.<br><br>수백 개가 한꺼번에 이쪽을 짚는다. 머리가 하얘진다. 이쪽 몸이 수백 개의 손바닥 밑에 있다.<br>술식을 끊고 주저앉았다. 귀에서 박수 소리가 났다. 이번엔 진짜 소리였다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A2', t:'양호실 — 커튼 뒤 셋째 침대',
  x:`양호실 침대가 넷이다. 커튼이 쳐져 있다. 물은 턱 아래까지.<br><br>
    탐지술을 편다. 셋째 침대에 반응이 있다. 따뜻하다. 박동이 있다. 산 사람이다.<br>
    이 학교에서 처음 짚인 산 반응이다.<br><br>
    커튼에 그림자가 비친다. 누운 사람. 그 곁에 앉은 사람 하나. 앉은 쪽은 반응이 없다.`,
  o:[
    { l:'① 산 반응의 숨을 세어 정말 산 것인지 가린다.', k:'sense', dc:22,
      ok:`숨을 셌다. 하나, 둘. 고르다. 박동도 고르다. 너무 고르다.<br><br>사람 숨은 고르지 않다. 꿈을 꾸면 흐트러지고 추우면 떤다. 이 숨은 셈을 하듯 고르다. 뒤에 선 일행 숨과 박자가 같다. 그 숨을 따라 하고 있다.<br>산 사람이 아니다. 산 사람을 기다리는 것이다. 곁에 앉은 그림자가 커튼을 걷으려고 손을 든다. 그 전에 일행을 끌고 양호실을 나왔다.<br><br>살아 있음도 흉내 낼 수 있다. 숨과 박동 말고 그 사이의 흐트러짐을 듣는다. 마력이 이제 흐트러짐을 짚는다.`,
      ng:`숨을 세는데 셋째 침대 박동이 빨라진다. 이쪽 박동과 같이.<br><br>이쪽이 무서워하면 저쪽도 빨라진다. 저쪽이 빨라지면 이쪽도. 둘이 서로를 끌어올린다.<br>가슴이 터질 듯했다. 술식을 끊고 벽을 짚고 섰다. 커튼 뒤 그림자가 이쪽으로 고개를 돌렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16 }, wake:1 },
    { l:'② 커튼을 걷고 산 사람을 데려온다.', k:'bond', dc:23,
      doom:{ title:'셋째 침대', what:'침대에 눕혀져 물 밑으로 가라앉습니다', dc:18, sec:45,
        text:`커튼을 걷었다. 침대에 아이가 누워 있다. 눈을 감았다. 가슴이 오르내린다.<br><br>곁에 앉은 것이 없다. 그림자만 커튼에 남았다. 아이 손을 잡았다. 따뜻하다. 아이가 눈을 뜬다. 웃는다. 손을 놓지 않는다.<br>침대가 내려앉는다. 물속으로. 아이가 손을 끌어당긴다. 이쪽이 침대 위로 넘어진다. 담요가 덮인다. 물이 담요 위로 차오른다.`,
        dieText:`셋째 침대 커튼이 다시 쳐졌다.<br><br>커튼에 그림자가 비친다. 누운 사람. 곁에 앉은 사람 하나. 앉은 쪽이 조금 더 크다.<br>탐지술에 짚일 산 반응이 하나 줄었다.` },
      ok:`커튼을 걷기 전에 손을 넣어 아이 손목만 짚었다. 따뜻하다. 박동이 고르다.<br><br>마력으로 손목 안쪽을 짚었다. 피가 돈다. 그런데 피가 아니라 물이 돈다. 따뜻한 물.<br>손을 뺐다. 커튼은 걷지 않았다. 머리맡 약장에 남은 약초 뭉치를 집어 나왔다. 커튼 뒤에서 아이가 돌아누웠다.`,
      win:{ exp:22, dream:3, item:'약초 뭉치' } }
  ] },

{ at:'A', t:'차가운 반응 — 벽 속을 가는 것',
  x:`술식을 편다. 차가운 반응이 많다. 돌, 쇠, 물. 차가운 것은 움직이지 않는다.<br><br>
    하나가 움직인다. 차가운 채로. 천천히. 벽 속을.<br>
    벽 속을 지나는 것은 길이 필요 없다.<br><br>
    그것이 일행 쪽 벽으로 온다.`,
  o:[
    { l:'① 냉기가 가는 길을 앞질러 읽고 일행을 비켜 세운다.', k:'sense', dc:22,
      ok:`냉기가 벽 속을 지나는 빠르기를 쟀다. 돌이 두꺼우면 느리다. 얇으면 빠르다.<br><br>얇은 벽 쪽으로 온다. 그쪽에 일행이 기대 있다. 일행을 두꺼운 벽 쪽으로 옮겼다. 냉기가 얇은 벽에 닿아 멈춘다. 일행이 기댔던 자리에서. 거기서 오래 머문다. 남은 체온을 핥는 것처럼.<br>그 사이 지나갔다. 두꺼운 벽은 냉기에게도 두껍다.`,
      ng:`읽는데 냉기가 둘로 갈라진다. 하나는 얇은 벽, 하나는 두꺼운 벽.<br><br>두꺼운 벽 쪽 일행 등에 냉기가 닿았다. 일행이 비명을 지른다. 등이 하얗게 얼었다.<br>끌어냈다. 등에 손바닥 모양 동상이 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 등잔 심지를 끝까지 올려 냉기를 쫓는다.', k:'luck', dc:22,
      ok:`심지를 끝까지 올렸다. 불이 커진다. 벽이 따뜻해진다.<br><br>냉기가 벽 속에서 멈춘다. 따뜻한 데를 피해 돈다. 크게. 불 둘레를 비켜서.<br>불을 든 채 걸었다. 기름이 빨리 닳았다. 그래도 냉기는 불빛 둘레에 들지 못했다.`,
      ng:`불을 키우자 벽 속 냉기가 불 쪽으로 온다. 불을 끄러.<br><br>등잔 불이 파랗게 질린다. 등잔을 쥔 손이 언다.<br>불이 꺼졌다. 어둠 속에서 냉기가 벽에서 나와 일행 사이를 지나갔다. 다들 이가 딱딱 부딪혔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-12, spirit:-20 } }
  ] },

{ at:'A', t:'너무 많은 반응 — 다 이쪽을 본다',
  x:`이 층은 반응이 많다. 벽마다, 바닥마다, 천장마다.<br><br>
    다 가만있었다. 술식을 펴는 순간 다 같이 돌아섰다. 마력이 오는 쪽으로.<br>
    짚을수록 이쪽이 보인다.<br><br>
    머리가 지끈거린다. 다 볼 수도 있고, 끊을 수도 있다.`,
  o:[
    { l:'① 마력을 실 한 가닥만큼 좁혀 빈 길만 짚는다.', k:'sense', dc:23,
      ok:`넓게 펴지 않았다. 마력을 실처럼 가늘게 꼬아 바닥 한 줄만 짚었다. 실이 닿는 데만 반응한다. 나머지는 이쪽을 잃는다.<br><br>실 끝을 한 걸음씩 밀었다. 반응이 없으면 디디고, 있으면 돌았다. 일행이 이쪽 발만 따랐다.<br>층 끝까지 실 한 가닥으로 갔다. 수백 개 가운데 이쪽을 본 것은 실이 닿은 서넛뿐이었다.<br><br>마력을 넓히는 것보다 좁히는 것이 어렵다. 좁힌 마력은 남이 못 본다. 손끝에서 실이 풀려 나온다.`,
      ng:`좁히다 실이 끊겼다. 끊긴 마력이 사방으로 흩어진다.<br><br>흩어진 마력을 반응들이 하나씩 잡는다. 잡고 당긴다. 머리가 사방으로 당겨진다.<br>코피가 쏟아졌다. 무릎을 꿇었다. 일행이 입을 막고 끌어냈다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-22 }, wake:1 },
    { l:'② 술식을 끊고 귀로만 걷는다.', k:'steady', dc:22,
      ok:`끊었다. 머리가 맑아진다. 대신 눈먼 것 같다.<br><br>반응들이 이쪽을 잃는다. 마력이 없으니 찾을 게 없다. 일행 발소리만 따라 걸었다.<br>그 층을 빠져나왔다. 다만 몇이 소리로 따라왔다. 계단 앞까지.`,
      ng:`끊는 순간 반응들이 한꺼번에 멈춘다. 이쪽이 끊은 것을 안다.<br><br>끊긴 자리를 향해 온다. 마력이 아니라 이쪽을 향해.<br>지나는 내내 무언가 따라왔다. 계단에서 일행 하나가 발목을 잡혔다. 겨우 뿌리쳤다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, mind:-14, spirit:-16 } },
    { l:'③ 마력을 한 번에 크게 터뜨려 반응들의 눈을 가린다.', k:'break', dc:22, cost:{ mana:30 },
      ok:`마력을 모았다가 한 번에 터뜨렸다. 하얀 소리 같은 것이 층을 쓸었다.<br><br>반응들이 일제히 흐려진다. 눈부신 데서 눈을 가리듯. 그 사이 층을 가로질렀다.<br>뒤에서 반응들이 하나씩 다시 떠올랐다. 이쪽이 터뜨린 자리를 짚었다. 이쪽은 거기 없었다.`,
      ng:`터뜨렸다. 반응들이 흐려지지 않는다. 더 밝아진다. 마력을 먹었다.<br><br>먹고 커진 것들이 이쪽을 짚는다. 이쪽 마력 맛을 안다.<br>남은 마력이 다 빠져나갔다. 다리가 풀렸다. 일행이 업고 뛰었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A1', t:'녹음 부스 — 언니의 목소리',
  x:`녹음 부스 유리창 너머에 마이크가 하나 서 있다. 스피커에서 목소리가 나온다. 언니 목소리다. 다정하다. 친구들, 같이 불러 볼까.<br><br>
    테이프가 돌고 있어야 한다. 데크는 멈춰 있다.<br>
    탐지술을 부스 안으로 민다.<br><br>
    마이크 앞에 반응이 있다. 따뜻하다. 노래할 때마다 숨이 깊어진다.`,
  o:[
    { l:'① 부스 안 반응의 생김을 짚는다.', k:'sense', dc:22,
      ok:`마력을 얇게 밀었다. 마이크 앞에 선 것의 키를 쟀다. 크다. 사람보다 머리 하나. 머리가 둥글고 크다. 탈이다. 노란 탈.<br><br>탈 속은 비었다. 비었는데 따뜻하다. 숨은 탈 속이 아니라 마이크에서 난다. 마이크가 숨을 쉰다.<br>노래를 따라 부르면 부스 문이 열린다. 일행 입을 막게 하고 부스 앞을 지났다.`,
      ng:`짚는데 노래가 멈춘다. 마이크가 이쪽 마력을 들었다.<br><br>스피커에서 언니가 말한다. 거기 있는 친구, 이름이 뭐니. 다정하게.<br>대답이 목까지 왔다. 혀를 깨물었다. 입안에 피가 고였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-12, spirit:-20 } },
    { l:'② 마력으로 부스 문틈을 메워 노래를 가둔다.', k:'steady', dc:22, cost:{ mana:30 },
      ok:`문틈마다 마력을 메웠다. 소리가 새는 데를. 스피커 선까지.<br><br>노래가 부스 안에만 울린다. 유리창이 떨린다. 바깥은 조용하다.<br>그 앞을 지나며 유리창을 봤다. 노란 탈이 유리에 이마를 대고 있다. 입 모양만 계속 노래한다. 같이 불러 볼까.`,
      ng:`메웠다. 노래가 막히자 마이크가 숨을 크게 들이쉰다. 부스 안 공기가 다 빨려 든다.<br><br>문틈 마력이 같이 빨려 들어간다. 머리가 핑 돈다.<br>손을 뗐다. 마력 절반이 부스 안에 남았다. 돌려받지 못했다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'③ 부스 안에 들어가 마이크를 끈다.', k:'bond', dc:23,
      doom:{ title:'같이 불러 볼까', what:'목소리에 이끌려 마이크 앞으로 끌려갑니다', dc:18, sec:45,
        text:`부스 문을 열었다. 노래가 몸을 덮는다. 따뜻하다. 아는 노래다. 처음 듣는데 안다.<br><br>마이크 전원을 찾았다. 손이 전원 대신 마이크를 쥔다. 입이 노래를 따라 한다.<br>노란 탈이 등 뒤에서 어깨를 잡는다. 마이크 앞으로 민다. 부스 문이 닫힌다. 노래가 끝날 때까지 나갈 수 없다. 노래는 끝나지 않는다.`,
        dieText:`녹음 부스 스피커에서 노래가 나온다.<br><br>언니 목소리 밑에 다른 목소리가 하나 섞였다. 반 박 늦게. 서툴게.<br>데크 숫자가 올라간다. 녹음 중.` },
      ok:`문을 열기 전에 마력으로 마이크 선을 따라갔다. 선이 벽 속 콘센트까지 간다. 콘센트는 부스 바깥이다.<br><br>밖에서 플러그를 뽑았다. 노래가 끊긴다. 마이크 숨이 멎었다. 노란 탈이 유리창 너머에서 굳었다. 입을 벌린 채.<br>부스 안에는 들어가지 않았다. 들어갈 필요가 없었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'도서관 — 젖지 않은 책',
  x:`도서관 서가가 물에 잠겼다. 책이 다 불었다. 페이지가 흘러나와 물에 떠다닌다.<br><br>
    탐지술을 편다. 한 권만 마른 반응이 돌아온다. 맨 위 칸. 물 밖이다.<br>
    마른 책 속에 온기가 있다. 아주 작다. 손바닥만 하다.<br><br>
    책장을 넘기면 따뜻한 것이 나올 것이다.`,
  o:[
    { l:'① 책을 펴지 않고 책 속 온기를 짚는다.', k:'sense', dc:22,
      ok:`손끝만 책등에 댔다. 마력을 얇게 밀었다. 책장 사이가 한 장씩 짚인다. 연필 자국이 있다. 일기다.<br><br>마지막 장 사이에 온기가 있다. 말린 꽃이다. 아직 따뜻하다. 꽃 옆에 연필 자국. 엄마 오면 줄 거. 날짜는 물 들어온 날 아침이다.<br>책을 펴지 않았다. 그 대신 책 옆에 끼워진 쪽지를 뺐다. 물 빠지는 길. 체육관 배수로. 아이가 적어 둔 것이다.<br><br>온기가 무엇의 온기인지까지 마력이 가린다. 꽃 한 송이와 사람 하나의 차이를. 그 차이가 이제 손끝에서 갈린다.`,
      ng:`짚는 순간 책 속 온기가 움직인다. 손바닥만 한 것이 책장 사이를 기어 나온다.<br><br>책이 저절로 펼쳐진다. 페이지마다 젖은 손바닥 자국이 찍혀 있다.<br>책을 덮었다. 덮은 책 속에서 무언가 표지를 두드렸다. 손을 떼고 물러났다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 }, wake:1 },
    { l:'② 마력으로 서가를 말려 다른 쪽지도 찾는다.', k:'fix', dc:22, cost:{ mana:25 },
      ok:`손을 펴서 서가에 마력을 흘렸다. 열이다. 젖은 책에서 김이 오른다.<br><br>마른 책들 사이로 쪽지가 몇 장 떨어진다. 아이들이 책 속에 숨긴 쪽지. 대답하지 마. 이름 불러도. 같은 말이 여러 글씨로.<br>쪽지 하나 뒤에 식당 저장고 자리가 그려져 있다. 거기서 말린 고기를 찾았다.`,
      ng:`말리는데 김이 짙어진다. 도서관 가득.<br><br>김 속에 사람 그림자가 선다. 서가마다 하나씩. 책을 읽는 자세로. 김이 걷히면 사라진다.<br>김이 걷힐 때까지 꼼짝 못 했다. 마력이 다 빠졌다. 손끝이 데었다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-22, mind:-14, spirit:-16 } }
  ] },

{ at:'A', t:'바닥 밑 — 누운 반응',
  x:`쉬는 자리다. 탐지술로 둘레를 살핀다. 아무것도 없다. 바닥 밑을 짚는다.<br><br>
    반응이 있다. 바로 밑. 판자 한 장 아래. 사람 길이로 누워 있다. 따뜻하다.<br>
    박동이 일행 하나의 박동과 같다. 같은 박자.<br><br>
    그 일행은 지금 그 판자 위에 누워 있다.`,
  o:[
    { l:'① 위와 아래의 박동을 같이 짚어 어느 쪽이 이끄는지 본다.', k:'sense', dc:22,
      ok:`위 박동과 아래 박동을 같이 짚었다. 같다. 그런데 아래가 반 박 먼저 뛴다. 아래가 이끈다.<br><br>위 일행을 깨웠다. 일어나 앉으라고 했다. 판자에서 몸이 떨어지는 순간 박동이 둘로 갈라졌다. 아래 박동이 혼자 남아 허둥대다 느려진다.<br>그 판자를 피해 다들 자리를 옮겼다. 아래 반응은 밤새 그 자리를 떠나지 않았다.`,
      ng:`짚는데 위 일행 박동이 느려진다. 아래 박동을 따라.<br><br>일행 얼굴이 하얘진다. 깨워도 안 깬다. 아래로 끌려가는 박동이다.<br>일행을 판자에서 굴려 떼어 냈다. 숨이 돌아올 때까지 한참 가슴을 눌렀다. 팔이 다 떨렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-16 } },
    { l:'② 판자를 뜯어 무엇이 누웠는지 본다.', k:'break', dc:23,
      doom:{ title:'판자 밑', what:'판자 밑으로 끌려 내려갑니다', dc:18, sec:50,
        text:`일행을 비키게 하고 판자를 뜯었다. 밑이 어둡다. 불을 들이댔다.<br><br>누워 있다. 일행 얼굴이다. 눈을 뜨고 있다. 이쪽을 본다. 비킨 일행이 등 뒤에서 숨을 들이켠다.<br>아래 것이 손을 뻗는다. 이쪽 손목을 잡는다. 판자 밑은 얕아 보였다. 깊다. 몸이 들어간다. 판자가 위에서 닫힌다.`,
        dieText:`일행이 판자를 다시 뜯었다. 밑은 흙이다. 얕다. 아무것도 없다.<br><br>그날 밤 다들 그 자리를 피해 잤다.<br>탐지술을 쓸 사람이 없어서, 바닥 밑 박동이 둘로 늘었다는 것은 아무도 몰랐다.` },
      ok:`뜯기 전에 일행을 판자에서 다 비키게 했다. 그리고 판자 가장자리를 한 뼘만 들었다.<br><br>틈으로 불을 비추자 밑의 것이 빛을 피해 깊이 들어간다. 판자 밑은 얕지 않다. 아래로 굴이 이어진다.<br>판자를 다시 내리고 짐을 다 올렸다. 그 밤 판자 밑에서 손톱이 판자를 긁었다. 짐이 무거워 들리지 않았다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A1', t:'스튜디오 — 송출선 속 맥',
  x:`송출 부스로 가는 바닥에 굵은 선이 깔려 있다. 송출선이다. 검고 굵다.<br><br>
    탐지술로 선을 짚는다. 전기가 아니다. 맥이 뛴다. 피 도는 것처럼. 선이 숨을 쉰다.<br>
    선은 무대에서 부스로 이어진다. 넘어가야 한다.<br><br>
    밟으면 선이 안다.`,
  o:[
    { l:'① 맥이 가장 약한 이음매를 찾아 거기서 넘는다.', k:'sense', dc:22,
      ok:`선을 따라 마력을 흘렸다. 맥이 고르지 않다. 이음매마다 약해진다. 셋째 이음매가 가장 약하다. 테이프로 감은 자리다. 맥이 거기서 한 번 멈칫한다.<br><br>멈칫할 때 넘었다. 한 사람씩. 선은 넘어가는 발을 느끼지 못했다.<br>부스 문 앞에 닿았다. 선 끝이 부스 안 스위치에 꽂혀 있다. 맥이 거기서 가장 세다. 심장이 거기 있다.<br><br>쇠줄 속에서도 맥이 고르지 않은 데를 찾는다. 사람이 아닌 것의 맥도 짚인다. 마력이 닿는 것이 하나 더 늘었다.`,
      ng:`이음매를 찾는데 맥이 이쪽 마력을 탄다. 선을 따라 손끝으로.<br><br>손끝이 뛴다. 선 박자로. 팔이 저리고 가슴이 선 박자로 뛴다. 박수 소리가 선 박자로 들린다.<br>마력을 끊었다. 가슴이 한참 제 박자를 못 찾았다. 일행이 등을 두드렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16 }, wake:1 },
    { l:'② 마력으로 선 한 마디를 얼려 맥을 잠시 멎게 한다.', k:'break', dc:22, cost:{ mana:30 },
      ok:`선 한 마디에 냉기를 쏟았다. 선이 하얗게 언다. 맥이 그 마디에서 멈춘다.<br><br>언 마디를 다들 넘었다. 넘는 동안 선 앞쪽이 부풀었다. 막힌 피처럼.<br>다 넘고 손을 뗐다. 언 마디가 녹으며 맥이 한꺼번에 흘렀다. 무대 조명이 한 번 다 켜졌다 꺼졌다.`,
      ng:`얼렸다. 맥이 멈추지 않는다. 언 마디를 깨고 흐른다. 언 조각이 튀었다.<br><br>조각이 손등에 박혔다. 차갑다가 뜨겁다. 맥이 손등 상처로 들어오려 한다.<br>상처를 눌러 막았다. 피가 선처럼 검었다. 한참 지나서야 붉어졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A2', t:'강당 문 앞 — 이백열하나의 반응',
  x:`강당 문 앞에서 탐지술을 편다. 물 밑 강당 안이 그려진다.<br><br>
    반응이 줄지어 있다. 미지근한 것들. 세어 본다. 이백열하나.<br>
    하나가 빈다. 그리고 줄 밖에 하나. 무대 뒤. 따뜻하지도 차갑지도 않다. 혼자 웅크렸다.<br><br>
    무대 쪽에 차가운 것이 하나 선다. 줄 앞에. 줄을 보고.`,
  o:[
    { l:'① 줄 밖의 하나를 아주 조금만 짚는다.', k:'sense', dc:22,
      ok:`줄 밖 반응에 마력을 아주 조금 댔다. 작다. 아이다. 무릎을 끌어안고 있다. 숨을 참고 있다. 몇 해를.<br><br>숨을 참는 것은 미지근해지지 않는다. 그래서 따뜻하지도 차갑지도 않다. 아직 대답하지 않은 아이다.<br>그 아이 쪽으로 가지 않았다. 숨은 자리를 피해 무대 반대편으로 돌았다. 차가운 것은 줄만 봤다. 줄 밖은 보지 않는다.`,
      ng:`짚는 순간 줄 밖 반응이 숨을 터뜨린다. 놀라서.<br><br>숨소리가 물을 타고 강당에 퍼진다. 차가운 것이 고개를 든다. 줄 밖을 본다. 처음으로.<br>마력을 끊었다. 늦었다. 무대 뒤에서 열쇠 소리가 났다. 그 아이 쪽으로 가는 소리였다. 이쪽 탓이다. 그 생각이 오래 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 술식을 접고 일행 손만 잡은 채 벽을 따라간다.', k:'bond', dc:22,
      ok:`마력을 접었다. 줄도 아이도 차가운 것도 머리에서 지웠다. 일행 손만 잡았다.<br><br>벽을 따라 걸었다. 물이 차다. 아무것도 짚지 않으니 아무것도 이쪽을 짚지 않는다.<br>무대 옆 계단에 닿았다. 손을 놓고 세어 보니 손이 다 따뜻했다.`,
      ng:`손을 잡고 걷는데 맨 끝 손이 차갑다.<br><br>세었다. 손이 하나 많다. 차가운 손이 일행 손을 잡고 따라온다. 줄에서 빠져나온 손이다.<br>손을 풀게 했다. 차가운 손이 한참 허공을 더듬다 물속으로 내려갔다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, mind:-14, spirit:-18 } },
    { l:'③ 비어 있는 한 자리가 어디인지 짚는다.', k:'gaze', dc:22,
      ok:`줄을 하나씩 짚어 빈자리를 찾았다. 3학년 2반 줄. 열일곱째.<br><br>줄 밖에 웅크린 아이 자리다. 빈자리는 기다리는 자리다. 저 아이를. 아니면 대신 설 누군가를.<br>그 줄 쪽으로는 아무도 가지 않게 했다. 빈자리 앞을 지날 때 물이 한 번 당겼다. 아주 약하게.`,
      ng:`빈자리를 찾았다. 짚는 순간 빈자리가 마력을 잡는다. 이쪽을 그 자리에 세우려는 것처럼.<br><br>마력이 끌려가며 몸이 그 줄 쪽으로 기운다. 일행이 허리를 잡았다.<br>마력을 끊을 때 머릿속에 이름 하나가 남았다. 이쪽 이름. 출석부 글씨로.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A', t:'마지막 초 — 마력으로 그린 방',
  x:`초가 꺼졌다. 마지막 초였다.<br><br>
    어둠이 완전하다. 일행 손이 이쪽 어깨를 잡는다.<br>
    탐지술사는 눈을 감는다. 감으나 뜨나 같다.<br><br>
    어둠 속 어딘가에서 초가 꺼진 것을 무언가 알았다. 숨이 하나 가까워진다.`,
  o:[
    { l:'① 마력만으로 방과 길을 그리며 걷는다.', k:'sense', dc:23,
      ok:`마력을 발 앞에 깔았다. 바닥이 그려진다. 벽이 그려진다. 문이 그려진다. 그리고 숨 하나. 다섯 걸음 앞. 바닥에 엎드려 기어 온다.<br><br>그 숨 둘레로 길을 그렸다. 둥글게 돌아서. 일행 손을 잡고 그 길로 걸었다. 숨이 방향을 바꾼다. 발소리 쪽으로. 그때마다 그림을 고쳤다.<br>빛이 있는 데까지 갔다. 눈은 한 번도 뜨지 않았다. 그림 속에서 엎드린 숨이 문턱에서 멈췄다.<br><br>어둠 속에서 그림을 그리고, 걷는 동안 고친다. 그리는 손이 이제 걷는 발만큼 빠르다.`,
      ng:`그리다 그림이 흐려진다. 숨 하나가 그림 속을 마구 기어 다닌다. 지운다.<br><br>그림이 다 지워졌을 때 숨이 바로 발밑에 있었다. 발목을 무언가 핥는다.<br>발을 빼고 벽을 더듬어 달렸다. 문틀에 얼굴을 박았다. 이가 하나 흔들렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-22 }, wake:1 },
    { l:'② 마력을 손끝의 빛으로 바꾼다.', k:'fix', dc:22, cost:{ mana:25 },
      ok:`손끝에 작은 불이 섰다. 마력이 타는 불이다. 오래는 못 간다.<br><br>불빛에 다섯 걸음 앞이 보인다. 엎드린 것이 빛을 피해 웅크린다. 그 옆을 지났다.<br>문을 나서자 불이 꺼졌다. 문을 닫았다. 안쪽에서 손바닥이 문을 짚었다.`,
      ng:`불이 섰다. 너무 밝았다.<br><br>엎드린 것만이 아니라 어둠 속 모든 것이 이쪽을 봤다. 빛나는 손끝을.<br>불을 끄려 했는데 안 꺼진다. 마력이 다 탈 때까지 그것들이 그 빛을 따라왔다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A', t:'물 — 맥이 뛰는 물',
  x:`물통이 비었다. 앞에 고인 물이 있다. 맑다. 냄새가 없다.<br><br>
    탐지술로 물을 짚는다. 차갑다. 그런데 맥이 있다. 물 전체가 아주 천천히 뛴다.<br>
    물 밑에 무엇이 있는 게 아니다. 물이 뛴다.<br><br>
    일행 입술이 갈라졌다.`,
  o:[
    { l:'① 물속 기운을 짚어 맥이 닿지 않은 물을 찾는다.', k:'sense', dc:22,
      ok:`맥은 가운데가 세다. 가장자리로 갈수록 약하다. 구석 돌 틈에서 새어 나오는 물만 맥이 없다.<br><br>돌 틈 물은 다른 데서 온다. 고인 물에 섞이기 전에 손바닥으로 받았다. 한 방울씩. 오래 걸렸다.<br>일행이 돌아가며 입을 적셨다. 수통에도 조금 채웠다. 고인 물 가운데가 그 사이 한 번 크게 뛰었다. 아쉬운 것처럼.`,
      ng:`가장자리를 찾았는데 마력이 닿자 가장자리도 뛰기 시작한다.<br><br>물이 이쪽 마력을 맛봤다. 물 전체가 이쪽으로 기운다. 발끝까지 물이 기어 온다.<br>물러섰다. 신발 앞코가 젖었다. 젖은 데가 오래 뛰었다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ hp:-22, mind:-12, spirit:-18 } },
    { l:'② 물을 떠서 마력으로 끓여 맥을 날린다.', k:'heal', dc:22, cost:{ mana:25 },
      ok:`물통에 고인 물을 떠서 마력을 흘렸다. 끓는다. 맥이 김과 함께 날아간다.<br><br>김이 사람 얼굴 모양으로 피어오르다 흩어진다. 남은 물에 맥이 없다.<br>식혀서 나눠 마셨다. 따뜻한 물이 목을 지나가자 다들 처음으로 어깨를 내렸다.`,
      ng:`끓이는데 맥이 빨라진다. 물이 끓는 게 아니라 맥이 뛰는 것이다. 물통 속에서.<br><br>물통이 손에서 튄다. 뜨거운 물이 손등에 쏟아졌다. 데었다.<br>바닥에 쏟아진 물이 고인 물 쪽으로 기어갔다. 합쳐졌다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A', t:'부르는 소리 — 몸 없는 목소리',
  x:`어둠 속에서 목소리가 일행 하나의 이름을 부른다. 그 일행이 떤다. 어머니 목소리라고 한다.<br><br>
    탐지술을 목소리 쪽으로 민다.<br>
    목소리 자리에 반응이 없다. 따뜻한 것도 차가운 것도. 숨도 없다.<br><br>
    목소리만 있다. 몸이 없다.`,
  o:[
    { l:'① 목소리 둘레를 넓게 짚어 몸이 어디 있는지 찾는다.', k:'sense', dc:22,
      ok:`목소리 자리는 비었다. 둘레를 넓혔다. 위로. 천장. 없다. 아래로. 바닥 밑. 없다.<br><br>그러다 등 뒤에서 반응이 잡혔다. 아주 가까이. 목소리와 반대쪽. 숨을 죽이고 기다린다. 일행이 목소리 쪽으로 가기를. 그 등 뒤로 오려고.<br>목소리는 미끼였다. 일행 귀를 막게 하고, 등 뒤 반응 쪽으로 불을 던졌다. 반응이 물러났다. 목소리가 그쳤다.<br><br>소리가 나는 데가 아니라 소리가 안 나는 데를 짚는다. 숨긴 쪽이 늘 더 가깝다. 마력이 그쪽을 먼저 안다.`,
      ng:`둘레를 짚는데 목소리가 이쪽 이름도 부른다. 이쪽 어머니 목소리로.<br><br>마력이 흔들렸다. 마음이 흔들렸다. 목소리 쪽으로 한 걸음 나갔다. 일행이 팔을 잡았다.<br>술식을 끊었다. 손이 떨렸다. 그 목소리는 이쪽 어릴 적 이름을 알았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 }, wake:1 },
    { l:'② 마력 실로 일행 손목을 서로 잇는다.', k:'bond', dc:22,
      ok:`마력을 실처럼 뽑아 일행 손목을 하나씩 이었다. 하나가 끌리면 다 안다.<br><br>목소리가 부를 때마다 그 일행 손목 실이 팽팽해진다. 다들 그 실을 당겼다.<br>목소리가 지칠 때까지 아무도 끌려가지 않았다. 실을 풀 때 손목마다 붉은 줄이 남았다.`,
      ng:`실을 이었다. 목소리가 부르자 실이 다 같이 끌린다. 한 사람이 아니라 모두.<br><br>이은 것이 거꾸로 됐다. 하나가 끌리면 다 끌린다. 실을 끊었다. 끊는 데 마력이 다 들었다.<br>다들 무릎을 꿇고 숨을 몰아쉬었다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, mind:-14, spirit:-18 } }
  ] },

{ at:'A', t:'바닥나는 마력 — 얇아진 막',
  x:`마력이 바닥나 간다. 펼 때마다 범위가 줄어든다. 이제 손 닿는 데까지만 짚인다.<br><br>
    짚이지 않는 데에서 무언가 기다린다. 마력이 줄어드는 것을 안다.<br>
    마력의 끝이 막처럼 얇아졌다. 그 막 바로 바깥에 반응이 몇.<br><br>
    막이 꺼지면 바로 앞이다.`,
  o:[
    { l:'① 남은 마력을 한 점에 모아 한 걸음 앞만 짚는다.', k:'sense', dc:22,
      ok:`넓히지 않았다. 남은 마력을 발끝 한 점에 모았다. 한 걸음 앞만.<br><br>한 걸음 앞이 비면 디뎠다. 다음 한 걸음. 막 바깥 반응들은 막이 넓을 때만 다가왔다. 좁으니 막 끝을 찾지 못한다.<br>한 걸음씩, 아주 느리게. 계단까지 갔다. 마력이 바닥나기 세 걸음 전이었다.`,
      ng:`한 점에 모으는데 마력이 떨린다. 한 점이 두 점이 된다. 흩어진다.<br><br>흩어지는 순간 막 바깥 반응들이 막 안으로 들어왔다. 하나가 손등에 닿았다. 젖은 손가락이다.<br>비명을 삼키고 뒷걸음질 쳤다. 손등에 손가락 자국이 남았다. 넷.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-12, spirit:-22 } },
    { l:'② 남은 마력을 한 번에 다 펴 끝까지 본다.', k:'gaze', dc:23, cost:{ mana:35 },
      doom:{ title:'꺼진 막', what:'막 바깥의 것들에게 여러 갈래로 끌려갑니다', dc:18, sec:50,
        text:`남은 마력을 다 폈다. 한 번에. 층 끝까지 그려진다. 반응이 많다. 다 막 바로 바깥에 있었다.<br><br>그리고 마력이 끝난다. 막이 꺼진다. 한꺼번에.<br>막 바깥의 것들이 동시에 한 걸음 들어온다. 손목. 발목. 옷깃. 차가운 손들이 잡는다. 어둠 쪽으로. 마력이 없으니 몇인지도 모른다.`,
        dieText:`일행이 불을 켰다. 바닥에 끌린 자국이 사방으로 나 있다.<br><br>여러 갈래로. 한 사람에게서 나간 자국이다.<br>어느 갈래를 따라가야 할지 아무도 몰랐다.` },
      ok:`다 폈다. 층 끝까지 그려진다. 반응들 자리가 다 보인다. 막 바로 바깥에 몰려 있었다. 한쪽 귀퉁이만 비었다.<br><br>막이 꺼지기 직전 그 귀퉁이를 머리에 새겼다. 막이 꺼졌다. 눈을 감고 새긴 대로 걸었다. 일행 손을 잡고.<br>귀퉁이 끝에 문이 있었다. 문을 닫자 등 뒤에서 여러 손이 한꺼번에 문을 짚는 소리가 났다.`,
      win:{ exp:24, dream:3 } }
  ] }
]);

// ------------------------------------------
// 보물사냥꾼 (treasure) · 자원 없음
// ------------------------------------------
kJob('treasure', 'A', [
{ at:'A', t:'빈방 — 겁먹은 사람의 버릇',
  x:`이 층에는 먼저 온 사람들이 있었다. 방마다 짐이 흩어져 있다. 주인은 없다.<br><br>
    사람은 떠날 때 못 가져간 것을 숨긴다. 보물사냥꾼은 숨긴 자리의 버릇을 안다.<br>
    오른손잡이는 오른쪽 아래. 급한 사람은 문 가까이. 겁먹은 사람은 높이.<br><br>
    여기 숨긴 사람들은 다 겁먹었다.`,
  o:[
    { l:'① 겁먹은 사람의 버릇대로 높은 데를 뒤진다.', k:'sense', dc:22,
      ok:`방마다 위를 봤다. 문틀 위. 선반 꼭대기. 천장 판자 틈.<br><br>셋째 방 천장 판자 하나가 덜 닫혀 있다. 손을 넣었다. 기름종이 꾸러미. 말린 고기와 꿈결 조각. 쪽지 한 장. 내려오지 마.<br>숨긴 사람이 자기에게 쓴 쪽지다. 내려가지 않으려고 천장에 숨었다가, 물건만 남았다. 판자를 다시 닫았다. 닫는 손을 판자 위에서 무언가 지켜봤다. 눈을 들지 않았다.<br><br>숨긴 물건보다 숨긴 사람의 겁을 읽었다. 겁의 높이까지. 사람이 남긴 자리가 이제 그 사람의 하루를 다 말한다.`,
      ng:`문틀 위에 손을 넣었다. 꾸러미 대신 손이 잡혔다. 차갑고 마른 손.<br><br>그 손이 꽉 쥔다. 놓지 않는다. 물건을 지키는 손이다. 몇 해를.<br>손가락을 하나씩 떼어 냈다. 손목에 멍이 들었다. 문틀 위 손은 다시 어둠으로 들어갔다.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ hp:-22, spirit:-22 }, wake:1 },
    { l:'② 손 가는 대로 아무 데나 뒤진다.', k:'luck', dc:22,
      ok:`손 가는 대로 열었다. 서랍, 상자, 주머니.<br><br>넷째 주머니에서 꿈결이 둘 나왔다. 까닭은 모른다. 그래서 다음엔 안 통할 것이다.`,
      ng:`손 가는 대로 열다가 상자 하나를 열었다. 안이 꽉 차 있다. 머리카락이다.<br><br>사람 머리 하나만큼. 땋아 두었다. 아직 윤기가 있다.<br>뚜껑을 닫았다. 그 방을 나올 때까지 뒷목이 근질거렸다.`,
      win:{ exp:15, dream:3 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'A1', t:'로비 — 진열장 밑의 재고',
  x:`로비 기념품 진열장은 비었다. 가운데 칸에 가격표만 남았다. 다 팔렸어요.<br><br>
    보물사냥꾼은 진열장을 보지 않는다. 진열장 밑을 본다.<br>
    파는 데에는 늘 재고가 있다. 재고는 손님 눈에 안 띄는 데 둔다.<br><br>
    진열장 밑판이 다른 데보다 한 뼘 두껍다.`,
  o:[
    { l:'① 밑판 이음새를 찾아 재고 서랍을 연다.', k:'sense', dc:22,
      ok:`밑판을 손바닥으로 쓸었다. 이음새가 있다. 손가락 걸 자리도. 직원 손이 수백 번 닿아 반들거린다.<br><br>당겼다. 서랍이 미끄러져 나온다. 인형은 없다. 직원들 간식 상자가 있다. 꿀 사탕 봉지. 비닐이 터지지 않았다. 그 밑에 쓰지 않은 방청권 묶음. 날짜가 다 같다.<br>서랍을 닫을 때 위 칸 인형들이 기울었다. 유리에 비친 것만.<br><br>팔리는 물건보다 파는 사람 손을 본다. 반들거린 자리가 숨긴 자리를 먼저 가리킨다. 이제 손때만 봐도 서랍이 보인다.`,
      ng:`이음새를 찾는데 밑판 안에서 무언가 긁는다. 손바닥 바로 아래서.<br><br>서랍이 저절로 조금 열린다. 틈으로 솜이 삐져나온다. 갈색 털이 섞였다.<br>손을 뗐다. 서랍이 다시 닫혔다. 위 칸 인형들이 일제히 이쪽을 봤다. 유리에 비친 것만이 아니었다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ mind:-16, spirit:-22 }, wake:1 },
    { l:'② 유리를 열고 넘어진 인형 하나의 속을 뒤진다.', k:'luck', dc:22,
      ok:`맨 아래 칸 구석에 작은 인형 하나가 넘어져 있다. 유리를 열고 꺼냈다.<br><br>등 솔기가 터졌다. 솜 사이에 꿈결 조각이 박혀 있다. 누가 인형 속에 숨겼다.<br>인형을 제자리에 눕혀 두었다. 터진 등을 아래로.`,
      ng:`인형을 꺼냈다. 등 솔기를 벌리는데 인형이 웃는다. 박음질한 입이 한 땀 올라간다.<br><br>손가락을 솔기에 물렸다. 실이 손가락을 감는다. 끊는 데 피가 났다.<br>인형을 진열장 안으로 던졌다. 인형이 일어나 앉았다.`,
      win:{ exp:15, dream:3 }, lose:{ hp:-22, mind:-12, spirit:-18 } }
  ] },

{ at:'A2', t:'탈의실 — 녹이 얇은 칸',
  x:`탈의실 사물함이 물에 잠겼다. 칸마다 자물쇠. 다 녹슬었다.<br><br>
    보물사냥꾼은 자물쇠의 녹을 본다. 녹은 손이 안 닿은 시간만큼 슨다.<br>
    한 칸 자물쇠만 녹이 얇다. 최근에 열렸다.<br><br>
    213번. 이름표가 새것이다.`,
  o:[
    { l:'① 녹의 결로 그 칸이 언제, 어느 쪽에서 열렸는지 읽는다.', k:'sense', dc:22,
      ok:`녹이 얇은 자리가 손잡이 안쪽뿐이다. 열쇠 구멍은 두껍게 슬었다. 열쇠로 연 게 아니다. 안에서 밀어 연 것이다.<br><br>213번은 열지 않았다. 대신 바로 옆 212번을 봤다. 녹이 두껍다. 몇 해를 아무도 안 열었다. 아무도 안 연 칸이 안전하다. 비틀어 열었다.<br>안에 수영 가방이 있다. 비닐 속 수건이 말랐다. 그 밑에 말린 고기 봉지. 집에서 싸 준 것이다. 이름이 적혀 있다.<br><br>녹이 시간을 잰다. 연 손이 안인지 밖인지까지. 물건을 잡기 전에 그 물건을 마지막으로 잡은 손을 먼저 본다.`,
      ng:`녹을 보는데 213번 칸 문이 안에서 한 번 덜컹인다.<br><br>문틈으로 물이 새어 나온다. 칸 안에 물이 꽉 차 있다. 그 물속에서 무언가 문을 민다.<br>물러섰다. 덜컹임이 이쪽 박동과 같이 뛰었다. 탈의실을 나올 때까지.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ hp:-22, mind:-12, spirit:-20 }, wake:1 },
    { l:'② 새 이름표가 붙은 213번 칸을 연다.', k:'luck', dc:23,
      doom:{ title:'213번 사물함', what:'사물함 안 물속으로 끌려 들어갑니다', dc:18, sec:45,
        text:`213번 손잡이를 당겼다. 쉽게 열린다. 녹이 얇으니까.<br><br>안에 물이 꽉 차 있다. 쏟아지지 않는다. 칸 모양 그대로 서 있다. 물속에 수영복이 걸려 있다. 새것이다. 이쪽 치수다.<br>물속에서 손이 나와 손목을 잡는다. 칸 안으로. 사물함은 사람 하나 들어갈 크기가 아니다. 들어간다. 문이 닫힌다. 딸깍.`,
        dieText:`탈의실 213번 사물함 자물쇠가 잠겼다.<br><br>이름표 글씨가 마를 무렵 자물쇠에 녹이 슬기 시작했다.<br>옆 칸에 이름표가 새로 붙었다. 214.` },
      ok:`손잡이를 당기기 전에 문틈을 손톱으로 쓸었다. 젖었다. 안에서 새는 물이다.<br><br>당기지 않았다. 대신 문 위 환기 구멍으로 철사를 넣어 이름표 뒤를 긁었다. 이름표가 떨어진다. 뒷면에 연필로. 신입생.<br>이름표를 찢었다. 칸 안에서 물이 한 번 출렁였다. 실망한 소리였다. 옆 칸 위에 올려진 수영부 물병 하나를 챙겼다.`,
      win:{ exp:21, dream:3, item:'맑은 물' } }
  ] },

{ at:'A', t:'방 가운데 — 지키는 것이 없는 상자',
  x:`방 한가운데 상자가 놓여 있다. 뚜껑이 열려 있다. 안에 꿈결이 반짝인다. 한 줌.<br><br>
    보물사냥꾼은 다가가지 않는다.<br>
    보물이 있는 곳에는 지키는 것이 있다. 지키는 것이 안 보이면 그 보물은 미끼다.<br><br>
    여기는 미끼치고도 너무 반짝인다.`,
  o:[
    { l:'① 상자 둘레의 먼지와 바닥을 읽는다.', k:'sense', dc:22,
      ok:`상자 둘레 먼지가 고르다. 너무 고르다. 누가 쓸고 다시 뿌렸다.<br><br>먼지 사이에 손자국 하나. 상자 밑에서 바깥으로 손가락이 뻗었다. 밑에서 누가 손을 내밀었던 자리다. 상자 밑판이 문이다.<br>상자에 손대지 않았다. 대신 상자 앞으로 돌을 하나 굴렸다. 돌이 상자 밑으로 들어가는 순간 밑판이 열렸다. 손이 돌을 쥐고 들어갔다. 다시 닫혔다.<br>열리고 닫히는 사이 상자가 기울어 꿈결 몇 알이 흘렀다. 그것만 주웠다.<br><br>보물을 보기 전에 보물을 놓은 손을 본다. 이 방 전체를 놓은 손을. 손이 보이면 상자는 그냥 상자다.`,
      ng:`먼지를 읽는데 상자 안 꿈결이 조금씩 줄어든다. 밑으로 빠져나간다.<br><br>다 빠지면 기회가 없다. 마음이 급해졌다. 반 걸음 다가섰다. 바닥이 한 뼘 꺼졌다.<br>뒤로 굴렀다. 정강이가 꺼진 바닥 모서리에 찢겼다. 상자는 비었다.`,
      win:{ exp:22, dream:4 }, lose:{ hp:-26, mind:-14 }, wake:1 },
    { l:'② 재빨리 한 줌 쥐고 물러난다.', k:'evade', dc:23,
      doom:{ title:'열린 상자', what:'상자 밑에서 나온 손에 끌려 내려갑니다', dc:18, sec:50,
        text:`손을 넣고 빼는 데 눈 깜짝할 사이. 그보다 빨랐다.<br><br>손목을 잡혔다. 상자 안에서. 꿈결 사이에서 손이 나온다. 꿈결이 손가락 사이로 흘러내린다.<br>상자 밑판이 열린다. 상자째 바닥이 꺼진다. 팔이 먼저 들어가고 어깨가 들어간다. 아래가 깊다. 반짝임이 위로 멀어진다.`,
        dieText:`방 가운데 상자가 놓여 있다. 뚜껑이 열린 채로.<br><br>안에 꿈결이 반짝인다. 아까보다 한 줌 많다.<br>상자 둘레 먼지는 고르다. 누가 쓸고 다시 뿌렸다.` },
      ok:`손을 넣었다. 빼는 순간 상자 안에서 손이 나와 허공을 쥐었다. 손목 한 뼘 뒤를.<br><br>뒤로 뛰었다. 상자 밑 바닥이 꺼졌다 닫혔다. 손에 꿈결이 쥐여 있다. 한 줌의 반.<br>나머지 반은 손가락 사이로 흘렀다. 주우러 가지 않았다.`,
      win:{ exp:21, dream:3 } }
  ] },

{ at:'A1', t:'방청석 — 착한 어린이 선물',
  x:`방청석 맨 앞줄 의자마다 선물 상자가 하나씩 놓여 있다. 리본이 묶였다. 착한 어린이 상.<br><br>
    흔들어 본 사람은 없다. 리본 끝이 길다. 바닥을 따라 무대 쪽으로 이어진다.<br>
    보물사냥꾼은 리본의 매듭을 본다.<br><br>
    선물은 받는 사람보다 주는 사람을 말한다.`,
  o:[
    { l:'① 상자를 들지 않고 밑 테이프를 뜯어 본다.', k:'sense', dc:22,
      ok:`리본은 위에서 묶었다. 아래는 테이프 한 줄뿐이다. 받는 쪽은 위만 본다.<br><br>상자를 그대로 두고 밑 테이프를 손톱으로 뜯었다. 사탕과 비스킷이 쏟아진다. 진짜다. 포장지가 오래됐다.<br>리본은 끝까지 손대지 않았다. 리본이 당겨지지 않으니 무대 쪽 아무것도 몰랐다. 꿀 사탕 한 줌을 챙겼다.`,
      ng:`밑을 뜯는데 상자 안에서 사탕이 아니라 리본이 나온다. 끝없이.<br><br>리본이 손목에 감긴다. 상자 안에서 감아 나온다. 끊었다. 손톱이 하나 들렸다.<br>무대 쪽에서 박수가 났다. 리본 끝을 쥔 무언가가 친 박수다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ hp:-24, mind:-14 } },
    { l:'② 리본을 풀어 선물을 받는다.', k:'bond', dc:23,
      doom:{ title:'착한 어린이 상', what:'리본에 손목이 묶여 무대로 끌려갑니다', dc:18, sec:50,
        text:`리본을 풀었다. 매듭이 쉽게 풀린다. 쉽게 풀리게 묶은 것이다.<br><br>상자가 열린다. 안이 비었다. 바닥에 카드 한 장. 착한 어린이 — 오늘의 친구.<br>풀린 리본이 손목을 감는다. 리본 끝이 무대 쪽으로 팽팽해진다. 당긴다. 의자를 넘고 계단을 넘는다. 무대 조명이 이쪽에만 켜진다.`,
        dieText:`방청석 맨 앞줄 의자에 선물 상자가 다시 놓였다.<br><br>하나가 늘었다. 리본이 묶였다. 상자를 흔들면 안에서 무언가 구른다.<br>무대에서 박수가 한참 났다.` },
      ok:`리본을 풀되 끝을 손에 쥐지 않았다. 의자 다리에 묶어 두고 풀었다.<br><br>상자가 열린다. 비었다. 카드 한 장. 리본이 팽팽해진다. 무대 쪽으로. 의자 다리가 버틴다. 의자째 끌려가 무대 계단에 쿵 부딪혔다.<br>상자 밑판 아래 진짜 선물이 테이프로 붙어 있었다. 꿈결 조각. 착한 어린이 몫이다.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A2', t:'매점 — 외상 장부',
  x:`식당동 매점 계산대 위에 외상 장부가 펼쳐져 있다. 물에 반쯤 젖었다.<br><br>
    이름, 날짜, 물건. 줄마다 빨간 줄이 그어졌다. 갚은 것이다. 한 줄만 그어지지 않았다.<br>
    보물사냥꾼은 장부를 읽지 않는다. 장부 놓인 자리를 본다.<br><br>
    매점 주인은 돈을 장부 가까이 둔다.`,
  o:[
    { l:'① 계산대 밑, 앉은 손이 닿는 데를 두드린다.', k:'sense', dc:22,
      ok:`계산대 밑 판자를 두드렸다. 소리가 다른 데가 있다. 무릎 높이. 주인이 앉아서 손 닿는 데.<br><br>판자를 밀자 작은 칸이 나왔다. 돈은 없다. 쌓인 것이 있다. 소금 덩이. 매점 물건 가운데 물에 안 녹게 기름종이로 싼 것.<br>장부 마지막 줄 이름 옆에 연필로 적혀 있다. 대신 갚음. 소금 한 덩이. 그 덩이는 두고 다른 하나를 챙겼다.`,
      ng:`판자를 두드리는데 장부가 저절로 넘어간다. 젖은 장이.<br><br>한 장. 또 한 장. 맨 뒷장에서 멈춘다. 새 줄. 이쪽 이름. 물건 칸은 비었다.<br>장부를 덮었다. 덮는 손이 떨렸다. 그 이름을 지울 데가 없었다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 깨진 진열장 안쪽을 재빨리 턴다.', k:'evade', dc:22,
      ok:`진열장 유리가 깨져 있다. 물속이다. 손을 넣어 안쪽을 더듬었다.<br><br>통조림 사이에 꿀 병이 하나. 뚜껑을 밀랍으로 봉했다. 손이 닿자마자 빼냈다.<br>빼낸 자리로 물이 소용돌이친다. 무언가 그 손 자리를 쥐었다. 늦게.`,
      ng:`손을 넣었다. 깨진 유리 모서리에 손목이 긁혔다.<br><br>피가 물에 번진다. 진열장 안쪽 어둠이 그 피 쪽으로 기운다.<br>손을 빼고 물러났다. 손목 상처가 오래 아물지 않았다. 물에 담그면 따끔했다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-24, mind:-12, spirit:-16 } }
  ] },

{ at:'A', t:'복도 — 이름표 붙은 물건',
  x:`복도에 물건이 줄지어 놓였다. 가방, 모자, 물병, 신발. 다 작다. 아이 것이다.<br><br>
    물건마다 이름표가 붙어 있다. 주인이 있다는 뜻이다.<br>
    몇 개만 이름표가 없다.<br><br>
    보물사냥꾼은 주인 없는 것만 줍는다. 여기서는 그게 목숨을 가른다.`,
  o:[
    { l:'① 처음부터 이름표가 없던 것만 골라 줍는다.', k:'sense', dc:22,
      ok:`하나씩 봤다. 이름표가 있는 것은 손대지 않았다. 없는 것만 봤다.<br><br>없는 것 가운데에도 자국이 있다. 떼어 낸 자국. 그런 것도 두었다. 처음부터 없던 것만. 물병 하나. 안에 맑은 물이 반쯤.<br>물병을 주웠다. 복도 끝까지 아무것도 따라오지 않았다.`,
      ng:`이름표 없는 물병을 주웠다. 손에 든 순간 물병 바닥에 이름이 떠오른다. 젖은 글씨로.<br><br>이쪽 이름이다. 떼어 낸 게 아니었다. 아직 안 붙인 것이었다.<br>내려놓았다. 손바닥에 물병 바닥 둥근 자국이 차갑게 남았다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 이름표 붙은 좋은 가방을 든다. 주인은 없다.', k:'luck', dc:23,
      doom:{ title:'주인 있는 물건', what:'물건 주인에게 손목을 잡혀 끌려갑니다', dc:18, sec:55,
        text:`가장 좋은 가방을 들었다. 무겁다. 안에 뭐가 많다.<br><br>세 걸음 갔을 때 가방 끈이 당겨진다. 뒤로. 돌아봤다. 아무도 없다. 끈만 팽팽하다.<br>복도 끝에서 작은 발소리가 달려온다. 내 거. 내 거야. 손이 손목을 잡는다. 작다. 아주 세다. 가방과 함께 끌려간다. 아이가 가는 쪽으로.`,
        dieText:`복도에 물건이 다시 줄지어 놓였다.<br><br>가방 옆에 신발 한 켤레가 늘었다. 어른 신발이다. 이름표가 붙어 있다.<br>이름표 글씨는 아이 글씨다.` },
      ok:`가방을 들었다. 세 걸음 갔을 때 끈이 뒤로 당겨진다.<br><br>바로 내려놓았다. 이름표가 보이게 바로 세워서. 끈이 풀린다. 복도 끝 작은 발소리가 멈춘다.<br>가방 옆에 사탕 하나가 놓여 있다. 아까는 없었다. 돌려줘서 고맙다는 것처럼. 그것은 이름표가 없었다. 주웠다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A1', t:'접수처 — 분실물 함',
  x:`접수처 뒤에 분실물 함이 있다. 나무 상자. 아이들 물건이 가득하다. 장갑 한 짝, 머리핀, 신발 한 짝.<br><br>
    상자 옆에 분실물 장부가 걸려 있다. 날짜와 물건. 찾아간 날 칸은 다 비었다.<br>
    아무도 찾으러 오지 않았다.<br><br>
    잃어버린 물건 사이에는 찾을 만한 것이 늘 섞여 있다.`,
  o:[
    { l:'① 분실물 장부와 상자를 하나씩 맞춰 본다.', k:'gaze', dc:22,
      ok:`장부와 상자를 맞췄다. 장갑, 있다. 머리핀, 있다.<br><br>장부에 없는 것이 하나 있다. 상자 맨 위. 일행 하나의 손수건이다. 언제 잃어버렸는지 모른다. 장부 맨 아래 칸에 그 손수건이 적혀 있다. 습득 장소 — 7층 스튜디오.<br>아직 가지 않은 데다. 손수건을 돌려줬다. 그 일행은 한참 손수건을 쥐고만 있었다.`,
      ng:`맞추는데 장부 줄이 늘어난다. 지금 쓰이는 줄. 볼펜이 혼자 움직인다.<br><br>새 줄. 물건 칸에 적힌다. 일행 하나의 이름.<br>장부를 뜯어 접었다. 접힌 종이 안에서 볼펜 긋는 소리가 한참 났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 상자 맨 밑, 아무도 손 안 댄 데를 뒤진다.', k:'sense', dc:22,
      ok:`위에 쌓인 것은 다 장갑과 핀이다. 잃어버리기 쉬운 것. 밑으로 갈수록 무겁고 오래됐다.<br><br>맨 밑에 도시락 통이 있다. 뚜껑을 고무줄로 묶었다. 안에 말린 고기와 꿈결. 직원 누군가가 분실물인 척 숨겨 둔 것이다. 가장 안 찾아가는 데에.<br>잃어버린 물건 사이에 일부러 둔 것이 섞인다. 둘은 쌓인 순서가 다르다.<br><br>상자 하나가 몇 해를 어떻게 쌓였는지 읽는다. 맨 밑이 가장 많이 말한다. 위를 헤치는 손이 이제 서두르지 않는다.`,
      ng:`맨 밑에 손이 닿았다. 무언가 손을 쥔다. 작은 손. 장갑 낀 손.<br><br>장갑 한 짝이 아니었다. 장갑 안에 손이 있었다. 분실물로 들어온 손이.<br>빼냈다. 장갑이 손에 끼워진 채 따라 나왔다. 벗겨 던졌다. 손등에 실밥 자국이 오래 남았다.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ hp:-22, mind:-12, spirit:-20 }, wake:1 }
  ] },

{ at:'A2', t:'기숙사 — 매트리스 속 비상식량',
  x:`호실 침대가 열둘. 이불이 다 개어져 있다. 각이 섰다.<br><br>
    기숙사 아이들은 먹을 것을 숨긴다. 사감 몰래. 보물사냥꾼은 그걸 안다. 자기도 그랬으니까.<br>
    숨기는 데는 늘 같다. 매트리스 속.<br><br>
    열두 매트리스 가운데 솔기를 다시 꿰맨 것이 있을 것이다.`,
  o:[
    { l:'① 솔기를 하나씩 쓸어 아이 손으로 다시 꿰맨 자리를 찾는다.', k:'sense', dc:22,
      ok:`손끝으로 솔기를 쓸었다. 공장 바느질은 땀이 고르다. 아이 바느질은 들쭉날쭉하다.<br><br>일곱째 침대 머리맡 솔기가 들쭉날쭉하다. 실 색도 다르다. 뜯었다. 비닐로 싼 꾸러미. 말린 과일과 꿀 덩이. 그리고 쪽지. 사감 선생님한테 말하지 마. 하람이 거.<br>꿀 덩이 하나만 챙겼다. 나머지는 다시 넣고 실을 감아 두었다. 이불을 그대로 개어 놓았다. 각을 맞춰서.<br><br>숨긴 사람 나이까지 손끝이 읽는다. 바느질 땀 하나로. 이제 들쭉날쭉한 것이 반짝이는 것보다 먼저 눈에 든다.`,
      ng:`솔기를 쓸다가 이불 각을 무너뜨렸다.<br><br>복도에서 열쇠 소리가 났다. 찰랑. 호실 앞에서 멈춘다. 각이 무너진 것을 안다.<br>침대 밑 물속에 숨었다. 걸음이 침대 사이를 한 바퀴 돌았다. 무너진 이불을 다시 개는 소리가 났다. 오래.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ hp:-22, mind:-14, spirit:-18 }, wake:1 },
    { l:'② 침대마다 매트리스를 들춰 본다.', k:'luck', dc:22,
      ok:`하나씩 들췄다. 다섯째 밑에서 비스킷 상자가 나왔다. 비닐 속이라 젖지 않았다.<br><br>뚜껑에 이름이 여럿. 같이 먹던 것이다. 이름 사이에 빈칸이 하나. 꿈결 조각 하나가 그 빈칸 자리에 끼워져 있다. 누구 몫인지는 모른다. 가져왔다.`,
      ng:`셋째를 들추는데 매트리스가 무겁다. 아래에서 누가 누르고 있다.<br><br>들춘 틈으로 물이 보인다. 물속에 얼굴이 있다. 눈을 뜨고 이쪽을 본다. 자는 걸 깨웠다는 얼굴이다.<br>내려놓았다. 손이 덜덜 떨렸다. 그 침대 이불 각이 저절로 다시 섰다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A', t:'무거운 배낭 — 늘어난 무게',
  x:`배낭이 무겁다. 주운 것을 다 넣었다. 그래도 이 정도는 아니었다.<br><br>
    보물사냥꾼은 제 배낭 무게를 안다. 한 줌 늘면 안다.<br>
    한 줌이 아니다. 아이 하나만큼 늘었다.<br><br>
    배낭이 따뜻하다. 등에 닿는 데가.`,
  o:[
    { l:'① 하나씩 꺼내 넣지 않은 것을 찾는다.', k:'sense', dc:22,
      ok:`배낭을 내려놓고 하나씩 꺼냈다. 물병, 고기, 약초, 꿈결. 다 이쪽이 넣은 것이다.<br><br>다 꺼냈는데 배낭이 아직 무겁다. 뒤집었다. 아무것도 안 떨어진다. 바닥을 손으로 쓸었다. 안감이 볼록하다. 손바닥 모양으로.<br>안감을 뜯지 않았다. 배낭을 그 자리에 두고, 꺼낸 것만 천에 싸서 멨다. 가볍다. 돌아보니 배낭이 조금씩 움직인다. 뒤척이듯.<br><br>제가 넣은 것과 넣지 않은 것을 무게로 가린다. 손이 짐의 무게를 낱낱이 기억한다. 늘어난 것은 숨지 못한다.`,
      ng:`꺼내다 보니 꺼낸 것이 넣은 것보다 많다. 모르는 물건이 섞였다. 머리핀, 실내화, 크레용.<br><br>그것들을 버렸다. 배낭을 다시 멨다. 무게가 그대로다.<br>등에 닿는 따뜻함이 숨을 쉬었다. 이쪽 숨에 맞춰.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16 }, wake:1 },
    { l:'② 그대로 메고 간다. 버리는 건 질색이다.', k:'steady', dc:22,
      ok:`이를 악물고 멨다. 무겁다. 그래도 다 가지고 간다.<br><br>한참 걷자 무게가 줄었다. 내려 보니 배낭 바닥이 젖어 있다. 누가 내렸다. 계단참에서.<br>주운 것은 다 그대로다. 꿈결만 한 알 줄었다. 내리는 길에 삯으로 가져간 것이다.`,
      ng:`메고 걸었다. 무게가 늘어난다. 한 걸음마다.<br><br>무릎이 꺾였다. 끈이 어깨를 파고든다. 배낭이 이쪽을 바닥으로 누른다. 일어설 수 없다.<br>일행이 끈을 끊었다. 배낭은 그 자리에 남았다. 안에 든 것과 함께.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'A', t:'벽에 기댄 외투 — 찢긴 지도',
  x:`외투 하나가 벽에 기대 앉아 있다. 안에 사람은 없다. 외투만 앉은 모양이다. 소매가 무릎을 끌어안았다.<br><br>
    소매 끝에 종이가 쥐여 있다. 지도다. 반쯤 찢겼다. 이 층 지도다.<br>
    표시가 여럿. 크게 그린 것, 작게 그린 것.<br><br>
    보물 지도는 그린 사람의 욕심만큼 틀린다.`,
  o:[
    { l:'① 가장 작게 그린 표시로 간다.', k:'gaze', dc:22,
      ok:`큰 표시는 욕심이다. 작은 표시는 그린 사람이 대수롭지 않게 여긴 데다.<br><br>가장 작은 표시. 계단 밑 소화기함. 열자 약초 뭉치와 꿈결 조각이 있다. 그린 사람이 다음에 가지러 오려던 것이다.<br>큰 표시 자리마다 지도에 손톱자국이 나 있다. 그 사람이 마지막에 간 자리들이다. 외투 소매가 왜 무릎을 끌어안았는지 알 것 같았다.`,
      ng:`가장 작은 표시로 갔다. 아무것도 없다. 벽에 작은 글씨만. 여기 아님.<br><br>돌아오니 외투가 자리를 옮겨 앉아 있다. 지나온 길 한가운데에. 소매가 이쪽을 향해 펴져 있다.<br>외투를 넘어갈 수 없었다. 먼 길로 돌았다. 다리가 풀렸다.`,
      win:{ exp:18, dream:3, item:'약초 뭉치' }, lose:{ hp:-22, mind:-12, spirit:-18 } },
    { l:'② 외투 주머니를 뒤진다.', k:'luck', dc:22,
      ok:`외투 주머니에 손을 넣었다. 따뜻하다. 방금까지 누가 손을 넣고 있던 것처럼.<br><br>꿈결 셋. 그리고 성냥 한 갑. 성냥은 반쯤 썼다.<br>손을 빼자 외투 소매가 조금 오므라들었다. 주머니를 지키지 못한 손처럼.`,
      ng:`주머니에 손을 넣자 안에서 손이 잡는다. 소매 속 손이.<br><br>외투가 일어선다. 사람 없이 사람 모양으로. 이쪽 손을 쥔 채.<br>손을 비틀어 뺐다. 외투가 무너져 다시 앉았다. 손목에 손가락 자국이 넷 남았다.`,
      win:{ exp:15, dream:3 }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A1', t:'소품 냉장고 — 촬영용 음식',
  x:`소품 창고 구석에 큰 냉장고가 있다. 전기가 끊겼는데 차다. 안에 음식이 가득하다.<br><br>
    촬영용이다. 반은 가짜다. 밀랍 사과, 플라스틱 소시지, 석고 케이크.<br>
    반은 진짜다. 아니면 진짜처럼 보이는 다른 것.<br><br>
    보물사냥꾼은 먹을 것과 먹는 척하는 것을 가린다.`,
  o:[
    { l:'① 냄새와 무게로 진짜 먹을 것만 가린다.', k:'sense', dc:22,
      ok:`하나씩 들어 봤다. 밀랍은 가볍다. 석고는 차갑다. 진짜는 냄새가 있다.<br><br>요리 코너에 쓰려던 산나물 병조림이 진짜였다. 문 닫기 전 날짜다. 병뚜껑이 볼록하지 않다. 상하지 않았다.<br>진짜처럼 보이는 고기 접시는 내려놨다. 냄새가 너무 좋았다. 이런 데서 너무 좋은 냄새는 미끼다.<br><br>먹을 것과 먹는 척하는 것 사이가 손바닥 위에서 갈린다. 무게 한 줌, 냄새 한 번. 이제 그것으로 충분하다.`,
      ng:`고기 접시를 들었다. 냄새가 좋다. 따뜻하다. 냉장고 안인데.<br><br>한 점 집으려는데 고기가 움찔한다. 접시 위에서. 결대로 접힌다.<br>접시를 떨어뜨렸다. 고기가 바닥을 기어 냉장고 밑으로 들어갔다. 손가락 끝 기름이 오래 안 지워졌다.`,
      win:{ exp:22, dream:3, item:'산나물' }, lose:{ hp:-22, mind:-12, spirit:-20 }, wake:1 },
    { l:'② 손에 잡히는 대로 쓸어 담고 문을 닫는다.', k:'luck', dc:22,
      ok:`손에 잡히는 대로 쓸어 담았다. 밀랍도 석고도.<br><br>밖에 나와 골랐다. 가짜가 대부분이다. 그 사이 육포 한 봉지가 섞여 있다.<br>냉장고 문을 닫는 순간 안에서 문을 두드리는 소리가 났다. 아무도 안 들어갔는데.`,
      ng:`쓸어 담는 사이 냉장고 문이 등 뒤에서 밀린다. 닫히려 한다. 몸이 반쯤 안에 들어가 있는데.<br><br>어깨로 문을 받았다. 찬 공기가 가슴을 얼린다. 문이 무겁다. 안에서 누가 당긴다.<br>빠져나왔다. 담은 것을 다 떨어뜨렸다. 문이 쾅 닫혔다. 손가락 하나가 끼일 뻔했다.`,
      win:{ exp:15, dream:2, item:'말린 고기' }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A2', t:'교무실 — 압수품 서랍',
  x:`교무실 맨 끝 책상 서랍에 이름표가 붙었다. 압수품.<br><br>
    아이들에게서 빼앗은 것을 넣어 둔 서랍이다. 만화책, 구슬, 사탕, 쪽지.<br>
    보물사냥꾼은 빼앗긴 물건이 가장 귀한 물건이라는 걸 안다. 아이들은 귀한 것을 숨기다 들킨다.<br><br>
    서랍은 잠기지 않았다. 물이 서랍 틈으로 드나든다.`,
  o:[
    { l:'① 압수품 목록과 서랍 속을 맞춰 본다.', k:'gaze', dc:22,
      ok:`서랍 안쪽에 목록이 붙어 있다. 선생 글씨. 날짜, 학생, 물건.<br><br>맞춰 봤다. 하나가 목록에 있는데 서랍에 없다. 3-2 17번. 나침반. 돌려준 기록도 없다. 주인이 몰래 가져갔다.<br>나침반을 가진 아이는 길을 잃지 않으려 했다. 그 아이가 간 길 끝에 나침반이 있을 것이다. 목록을 떼어 챙겼다. 서랍 속 사탕은 그대로 두었다.`,
      ng:`맞추는데 목록 줄이 늘어난다. 젖은 글씨가 새로 번진다.<br><br>새 줄. 날짜 오늘. 학생 칸에 이쪽 이름. 물건 칸에 적힌다. 배낭.<br>배낭을 꽉 쥐었다. 서랍이 저절로 조금 열렸다. 넣으라는 듯이.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 서랍 깊이를 재어 이중 바닥을 찾는다.', k:'sense', dc:22,
      ok:`서랍이 너무 얕다. 책상 깊이보다 손가락 두 마디만큼.<br><br>바닥판 모서리를 손톱으로 들었다. 이중 바닥이다. 선생이 따로 숨긴 것. 압수품 가운데 돌려주기 아까운 것. 만년필, 은시계, 그리고 꿀 단지. 학생이 집에서 가져온 것이다.<br>선생도 아이에게서 빼앗은 것을 다시 숨겼다. 숨긴 것 밑에 숨긴 것이 있다.<br><br>바닥이 하나라고 믿지 않는다. 숨긴 사람 위에 숨긴 사람이 있다. 손이 두 번째 바닥을 먼저 찾는다.`,
      ng:`바닥판을 들었다. 밑에 물이 차 있다. 물속에 손가락이 있다. 바닥판을 아래서 받치고 있던 손가락.<br><br>바닥판을 놓쳤다. 손가락이 물속으로 사라진다.<br>서랍을 닫았다. 서랍 안에서 바닥판을 다시 끼우는 소리가 났다. 꼼꼼하게.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ hp:-22, mind:-12, spirit:-20 }, wake:1 }
  ] },

{ at:'A', t:'반짝임 — 깜빡이는 것',
  x:`무너진 선반 더미 속에서 무언가 반짝인다. 둥글고 크다. 동전 한 줌만 하다.<br><br>
    보물사냥꾼은 반짝임을 의심한다.<br>
    어둠 속 반짝임은 반은 물건이고 반은 눈이다.<br><br>
    눈이라면 깜빡인다. 아직 안 깜빡였다.`,
  o:[
    { l:'① 반짝임 둘레의 먼지와 숨구멍을 읽는다.', k:'sense', dc:22,
      ok:`반짝임 둘레 먼지를 봤다. 고르게 쌓였다. 숨을 쉬면 먼지가 밀린다. 안 밀렸다.<br><br>물건이다. 갈고리로 끌어왔다. 놋쇠 단추 한 줌이다. 옷에서 떨어진 것. 그 밑에 기름종이에 싼 말린 고기 꾸러미가 깔려 있었다.<br>단추를 다시 그 자리에 뿌려 두었다. 다음 사람도 반짝임을 의심하라고.`,
      ng:`먼지를 읽는데 먼지가 아주 조금 밀린다. 숨구멍이다. 늦게 봤다.<br><br>반짝임이 깜빡였다. 둘로 갈라진다. 눈 두 개.<br>물러섰다. 선반 더미가 일어선다. 등을 펴듯이. 뛰었다. 등 뒤로 선반 무너지는 소리가 따라왔다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 장대 끝 갈고리로 멀리서 낚는다.', k:'fix', dc:22,
      ok:`갈고리를 단단히 묶고 멀리서 걸었다. 당겼다.<br><br>반짝임이 끌려온다. 단추다. 단추 달린 옷이 같이 끌려온다. 옷만. 주인 없이.<br>주머니에 꿈결 조각이 있었다. 옷은 그 자리에 다시 펴 두었다.`,
      ng:`걸었는데 장대가 반대로 끌려간다.<br><br>놓을 때 손바닥이 쓸렸다. 장대가 선반 더미 속으로 쑥 들어갔다.<br>더미 속에서 장대 씹는 소리가 났다. 오래.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-22, mind:-12, spirit:-18 } },
    { l:'③ 반짝임에 등을 돌리고 지나간다. 반짝인다고 다 보물은 아니다.', k:'steady', dc:21,
      ok:`등을 돌렸다. 일행에게도 보지 말라고 했다.<br><br>뒤에서 반짝임이 깜빡였는지 아닌지 모른다. 모르는 채로 지났다.<br>한참 뒤 일행 하나가 물었다. 아깝지 않냐고. 아까웠다. 살아 있으니 아까운 것이다.`,
      ng:`등을 돌렸는데 반짝임이 등에 비친다. 등이 따갑다. 뒤에서 누가 오래 보고 있다.<br><br>참고 걸었다. 그 시선이 등에서 안 떨어진다.<br>그날 밤 등을 대고 누울 수 없었다.`,
      win:{ exp:14, dream:2, mind:6 }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A1', t:'직원 휴게실 — 번호 자물쇠',
  x:`직원 휴게실에 사물함이 줄지어 있다. 칸마다 번호 자물쇠. 숫자 넷.<br><br>
    칸 문에 이름표. 분장, 무대 감독, 진행. 맨 끝 칸 이름표만 비었다.<br>
    보물사냥꾼은 자물쇠 숫자판의 닳은 데를 본다.<br><br>
    사람은 같은 숫자를 매일 돌린다.`,
  o:[
    { l:'① 숫자판의 닳은 숫자로 번호를 읽는다.', k:'sense', dc:22,
      ok:`진행 칸 자물쇠. 숫자판 넷마다 닳은 숫자가 하나씩 있다. 넷, 다섯, 셋, 일곱.<br><br>돌렸다. 딸깍. 열렸다. 안에 도시락 가방. 말린 고기와 꿀 사탕. 그리고 손으로 쓴 시간표. 4:53 입장. 4:58 오늘의 친구 분장. 5:00 생방송.<br>시간표를 챙겼다. 이 건물의 하루가 거기 다 있다.`,
      ng:`닳은 숫자를 돌렸다. 딸깍. 열리지 않는다. 대신 옆 칸이 열린다. 맨 끝 칸. 이름표 없는.<br><br>안에 이쪽 옷이 걸려 있다. 지금 입은 것과 같은 옷. 깨끗하게 다려져서. 가슴에 명찰. 오늘의 친구.<br>문을 닫았다. 손이 떨려 닫는 데 세 번 걸렸다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 경첩이 약한 칸을 비틀어 연다.', k:'break', dc:22,
      ok:`무대 감독 칸 문을 비틀었다. 경첩이 약하다. 열렸다.<br><br>안에 헤드셋 여분, 큐 카드 뭉치, 그리고 비상식량 상자. 꿀 사탕이 들었다.<br>큐 카드를 넘겨 봤다. 마지막 장에 적혀 있다. 퇴장. 그 카드를 챙겼다. 쓸 데가 있을지도 모른다.`,
      ng:`비트는 소리가 휴게실을 울린다.<br><br>복도에서 카드 넘기는 소리가 난다. 조용히. 가까이.<br>사물함 사이에 숨었다. 헤드셋 낀 그림자가 휴게실 문 앞을 지나갔다. 오래 걸렸다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-22, mind:-12, spirit:-18 } },
    { l:'③ 이름표 빈 맨 끝 칸 자물쇠를 돌려 본다.', k:'luck', dc:23,
      ok:`맨 끝 칸 숫자판은 하나도 닳지 않았다. 아무도 연 적이 없다.<br><br>처음 숫자 그대로 당겼다. 0000. 열렸다. 비어 있다. 바닥에 꿈결 조각이 몇 알 굴러다닌다.<br>쓸어 담고 문을 닫았다. 숫자판을 아무 숫자로나 흐트러뜨려 두었다.`,
      ng:`돌리다 손가락이 숫자판에 끼었다. 숫자판이 혼자 돈다. 손가락을 문 채.<br><br>4. 5. 3. 7. 딸깍. 사물함이 열린다. 안에서 찬 바람이 나온다. 아무것도 없다. 바람만.<br>손가락을 뺐다. 손톱 밑에 숫자 자국이 남았다.`,
      win:{ exp:15, dream:3 }, lose:{ hp:-24, mind:-12, spirit:-16 } }
  ] },

{ at:'A2', t:'강당 — 물 밑의 반짝임',
  x:`강당 물 밑 바닥이 반짝인다. 수백 개. 명찰이다. 핀이 반짝인다.<br><br>
    명찰마다 이름이 수놓였다. 학년과 반.<br>
    그 사이에 다른 반짝임이 섞여 있다. 둥글다. 명찰이 아니다.<br><br>
    그리고 무대 바로 앞 반짝임 하나. 새것이다. 실이 아직 하얗다.`,
  o:[
    { l:'① 명찰이 아닌 둥근 반짝임만 골라 건진다.', k:'sense', dc:22,
      ok:`명찰은 네모다. 핀이 위에 있다. 둥근 것은 따로 논다.<br><br>둥근 것을 하나씩 건졌다. 단추, 동전, 그리고 은 호루라기. 물속에서도 녹이 안 슬었다. 명찰은 하나도 건드리지 않았다.<br>물 위로 나오자 호루라기 안에서 물이 흘렀다. 불지 않았다. 불면 누가 줄을 설 것 같았다.`,
      ng:`둥근 것을 건지다 명찰 하나에 손이 스쳤다.<br><br>핀이 손가락을 찌른다. 빠지지 않는다. 명찰이 손가락에 매달린다. 이름이 수놓인 쪽이 이쪽을 향해.<br>억지로 뺐다. 피가 물에 번졌다. 그 명찰 이름 칸에 실이 한 땀 풀렸다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, mind:-12, spirit:-20 } },
    { l:'② 아무것도 건지지 않고 반짝임 사이를 걷는다.', k:'steady', dc:22,
      ok:`손을 넣지 않았다. 반짝임을 밟지 않게 발을 들어 디뎠다.<br><br>무대 앞까지 갔다. 물 밑 반짝임들이 이쪽 그림자를 따라 흐려졌다. 지나가자 다시 반짝였다.<br>빈손으로 건넜다. 그것이 오늘의 수확이었다.`,
      ng:`걷는데 반짝임들이 발밑으로 모인다. 물 밑에서. 명찰들이 미끄러져 온다.<br><br>디딜 데마다 명찰이다. 밟았다. 핀이 신발 밑창을 뚫었다.<br>발바닥에서 피가 났다. 물에 번진 피가 명찰들 쪽으로 흘러갔다.`,
      win:{ exp:15, dream:2, mind:6 }, lose:{ hp:-24, spirit:-20 } },
    { l:'③ 무대 앞 새 명찰을 건져 본다.', k:'luck', dc:23,
      doom:{ title:'새 명찰', what:'명찰 실에 꿰여 빈자리로 끌려 내려갑니다', dc:19, sec:40,
        text:`무대 앞 새 명찰을 건졌다. 손바닥에 올렸다. 이름이 수놓였다. 이쪽 이름이다. 학년 반 칸은 비었다.<br><br>바늘이 꽂혀 있다. 실 끝이 물 밑으로 이어진다. 실이 당겨진다. 바늘이 손바닥을 꿴다.<br>실이 이쪽을 꿰맨다. 손바닥을 가슴에. 명찰 자리에. 물 밑에서 당긴다. 줄 맨 끝 빈자리로. 무릎이 꺾이고 몸이 앉혀진다. 물이 머리를 넘는다.`,
        dieText:`강당 물 밑에 반짝임이 하나 늘었다.<br><br>맨 끝 줄. 명찰 하나. 학년과 반 칸이 채워졌다. 3학년 2반.<br>점호에서 그 이름이 불렸다. 대답이 있었다.` },
      ok:`건지기 전에 실 끝을 봤다. 물 밑으로 이어진다. 팽팽하다.<br><br>명찰을 건지지 않고 실을 끊었다. 칼로. 실 끝이 물 밑으로 빨려 내려갔다. 명찰은 바닥에 남았다. 이제 아무 데도 안 이어진 천 조각이다.<br>그 옆에 놓인 둥근 것 하나를 건졌다. 꿈결이다. 명찰을 만든 바늘이 그 위에 꽂혀 있었다. 바늘은 버렸다.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A', t:'숨긴 문 — 두드린 벽',
  x:`벽에 손잡이 없는 문 자리가 있다. 회반죽으로 덮었다. 덮은 자리만 색이 다르다.<br><br>
    보물사냥꾼은 벽을 두드린다. 빈 소리가 나면 그 뒤에 무언가 있다.<br>
    두드렸다. 똑똑.<br><br>
    안에서 두드린다. 똑똑.`,
  o:[
    { l:'① 두드림 박자를 엇갈려 진짜 빈 소리를 가린다.', k:'sense', dc:22,
      ok:`이쪽이 두 번 치면 저쪽도 두 번. 세 번이면 세 번. 따라 한다.<br><br>박자를 엇갈렸다. 하나, 쉬고, 둘. 저쪽이 따라 하다 한 번 틀린다. 틀린 순간 저쪽 소리가 멀다. 문 자리 뒤가 아니다. 왼쪽 벽 속이다.<br>문 자리는 비었다. 회반죽을 깨고 열었다. 작은 방. 쌀자루와 소금 덩이. 피난할 때 숨긴 것이다. 왼쪽 벽은 끝내 건드리지 않았다.<br><br>두드리면 대답하는 것과 그냥 비어 있는 것을 가른다. 소리 하나로 벽 속을 두 칸으로 나눈다. 귀가 그 칸을 먼저 센다.`,
      ng:`박자를 바꿨다. 저쪽도 바꿨다. 이쪽보다 먼저.<br><br>이쪽이 칠 박자를 저쪽이 먼저 친다. 손을 멈췄다. 저쪽은 멈추지 않는다. 똑똑. 똑똑. 문을 열어 달라는 박자다.<br>물러섰다. 그 소리가 다음 층까지 귀에 따라왔다.`,
      win:{ exp:22, dream:3, item:'소금 덩이' }, lose:{ mind:-18, spirit:-22 }, wake:1 },
    { l:'② 회반죽을 깨고 문을 연다.', k:'break', dc:23,
      doom:{ title:'덮은 문', what:'벽 속 틈으로 끌려 들어갑니다', dc:18, sec:50,
        text:`회반죽을 깼다. 덜 굳었다. 금방 깨진다. 안쪽에 나무 문이 있다. 밀었다.<br><br>문 너머가 방이 아니다. 벽 두께만 한 틈이다. 사람 하나 설 폭. 거기 누가 서 있다. 이쪽을 보고. 회반죽 가루를 뒤집어썼다.<br>손이 나와 옷깃을 잡는다. 틈 안으로. 두 사람은 안 들어간다. 들어간다. 등 뒤로 회반죽이 다시 발린다.`,
        dieText:`일행이 돌아왔을 때 벽은 벽이었다.<br><br>문 자리 회반죽이 새것이다. 아직 축축하다.<br>벽을 두드렸다. 안에서 두드린다. 두 번. 이쪽 박자로.` },
      ok:`회반죽을 손바닥만큼만 깼다. 문 전체가 아니라 눈높이 한 칸만.<br><br>틈 안에 누가 서 있다. 이쪽을 보고. 회반죽 가루를 뒤집어썼다. 손을 뻗지 못한다. 구멍이 손보다 작다.<br>그 사람 발밑에 꾸러미가 있다. 갈고리로 끌어냈다. 꿈결과 약초 뭉치. 그 사람이 지키던 것이다. 구멍을 다시 막았다. 안에서 두 번 두드렸다. 고맙다는 듯이.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A', t:'나눠 가질 때 — 하나 많은 몫',
  x:`쉬는 자리에서 주운 것을 나눈다. 몫은 보물사냥꾼이 정한다. 늘 그렇다.<br><br>
    나눠 놓고 보니 몫이 하나 많다. 일행 수보다.<br>
    다시 세면 맞는다. 바닥에 놓으면 또 하나 많다.<br><br>
    남는 몫 앞 바닥이 조금 젖어 있다. 누가 앉았던 것처럼.`,
  o:[
    { l:'① 몫을 바닥에 두지 않고 손에서 손으로 건네며 센다.', k:'gaze', dc:22,
      ok:`바닥에 두지 않고 손에서 손으로 건넸다. 한 사람씩 얼굴을 보며.<br><br>손에 쥔 몫은 늘어나지 않는다. 바닥에 놓은 몫만 늘었다. 바닥에 앉은 것의 몫이다. 손이 없는 것.<br>다 나눈 뒤 바닥은 비워 두었다. 젖은 자리가 한참 그대로 있다가 말랐다.`,
      ng:`손에서 손으로 건넸다. 마지막 몫을 건넬 때 받는 손이 차다.<br><br>얼굴을 봤다. 일행이다. 다시 봤다. 일행이다. 손이 차다.<br>몫을 거뒀다. 그 일행이 왜 그러냐고 물었다. 대답하지 못했다. 그 일행 손은 다시 따뜻했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 남는 몫을 젖은 자리 앞에 반듯하게 두고 간다.', k:'sense', dc:22,
      ok:`남는 몫을 거두지 않았다. 젖은 자리 앞에 반듯하게 놓았다. 주운 것 가운데 좋은 것으로.<br><br>떠날 때 돌아봤다. 몫이 그대로 있다. 젖은 자리가 몫 쪽으로 조금 번져 있다.<br>다음 층에서 짐을 풀었다. 배낭에 처음 보는 것이 하나 들어 있다. 꿀 단지. 몫을 받은 쪽이 남긴 것이다.<br><br>무엇을 가질지보다 무엇을 두고 갈지를 먼저 셈한다. 두고 간 몫이 되돌아오는 길도 있다. 이 일의 셈법이 하나 늘었다.`,
      ng:`남는 몫을 놓았다. 떠나려는데 몫이 또 늘었다. 둘.<br><br>하나를 더 놓았다. 셋이 된다. 놓을수록 는다. 배낭이 가벼워진다.<br>반을 놓고 나서야 그쳤다. 배낭에 남은 것이 별로 없었다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ mind:-16, spirit:-22 }, wake:1 }
  ] },

{ at:'A', t:'너무 좋은 것 — 차려진 식탁',
  x:`버려진 방 식탁에 음식이 차려져 있다. 따뜻하다. 김이 오른다.<br><br>
    고기, 국, 밥. 숟가락이 놓였다. 의자가 당겨져 있다.<br>
    일행 배가 운다. 이틀을 굶었다.<br><br>
    보물사냥꾼은 너무 좋은 것을 의심한다. 이 방은 먼지가 두껍다. 식탁 위만 깨끗하다.`,
  o:[
    { l:'① 냄새로 진짜 먹을 것만 가린다.', k:'sense', dc:22,
      ok:`냄새를 맡았다. 고기 냄새가 너무 좋다. 국도. 밥도. 다 너무 좋다.<br><br>식탁 아래 바구니 냄새는 평범하다. 오래된 곡식 냄새. 들췄다. 말린 산나물과 말린 민물고기. 사람이 먹으려고 둔 것이다.<br>식탁 위는 아무도 손대지 않았다. 바구니만 들고 나왔다. 등 뒤에서 의자 끄는 소리가 났다. 누가 앉을 자리를 다시 맞추는 소리.`,
      ng:`냄새를 맡는데 냄새가 코로 들어와 머리를 채운다. 좋다. 너무 좋다.<br><br>정신을 차렸을 때 숟가락을 쥐고 있었다. 일행이 손목을 잡고 있었다. 입에 국물 맛이 남았다. 짜다. 눈물 맛이다.<br>한동안 배가 끊어질 듯 아팠다.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-26, mind:-14 } },
    { l:'② 일행을 등으로 막고 아무것도 먹지 않고 지난다.', k:'steady', dc:22,
      ok:`일행을 등으로 막았다. 아무도 식탁에 다가가지 못하게.<br><br>배가 운다. 다들. 그래도 지났다. 방을 나오자 냄새가 끊겼다. 칼로 자른 것처럼.<br>문틈으로 돌아보니 식탁 위가 비어 있었다. 먼지만 두껍다. 아무것도 차려진 적이 없다.`,
      ng:`막았는데 일행 하나가 이쪽을 밀친다. 배고픈 힘이다.<br><br>그 일행을 붙잡아 바닥에 눕혔다. 몸싸움이 됐다. 팔꿈치에 코를 맞았다.<br>겨우 끌어냈다. 그 일행은 한참 원망하는 눈으로 봤다. 그 눈이 더 아팠다.`,
      win:{ exp:15, dream:2, hp:6 }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A', t:'욕심 — 바닥 금 사이의 빛',
  x:`바닥에 금이 갔다. 금 사이로 빛이 난다. 노랗다. 따뜻하다.<br><br>
    금 아래가 보인다. 쌓여 있다. 반짝이는 것이. 많이.<br>
    보물사냥꾼 손이 떨린다. 평생 본 것보다 많다.<br><br>
    빛이 부른다. 소리 없이. 손을 넣으라고.`,
  o:[
    { l:'① 표시만 남기고 돌아선다.', k:'steady', dc:22,
      ok:`손을 넣지 않았다. 일어섰다. 금 옆에 분필로 표시를 남겼다. 다음에 온다. 다음이 있다면.<br><br>돌아서는데 등 뒤 빛이 짙어진다. 돌아보지 않았다. 빛이 등을 따뜻하게 민다. 다시 오라고.<br>층계에 닿았을 때 빛이 꺼졌다. 금은 그냥 금이었다. 그 아래는 어둠이었다. 반짝이는 것은 빛이 비춘 만큼만 있었다.<br><br>욕심이 손보다 먼저 움직일 때 손을 멈춘다. 손이 떨려도 멈춘다. 이 일을 오래 하는 쪽은 그 멈춤을 안다.`,
      ng:`돌아섰는데 발이 안 떨어진다. 몸이 금 쪽으로 기운다.<br><br>무릎을 꿇었다. 일어서려고 바닥을 짚었다. 짚은 손이 금 가장자리였다. 손끝이 빛에 닿았다. 따뜻하다.<br>일행이 뒷덜미를 잡아당겼다. 손끝이 하얗게 데어 있었다. 따뜻한 줄 알았는데.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-14, spirit:-18 }, wake:1 },
    { l:'② 금 사이에 손을 넣는다.', k:'luck', dc:24,
      doom:{ title:'금 사이의 빛', what:'금 사이로 빨려 들어갑니다', dc:19, sec:50,
        text:`손을 넣었다. 반짝이는 것이 손가락에 닿는다. 차갑다. 반짝이는 것은 원래 차다.<br><br>쥐었다. 쥔 것이 이쪽 손을 쥔다. 반짝이는 것이 아니다. 손톱이다. 수많은 손톱.<br>금이 넓어진다. 빛이 짙어진다. 팔이 들어간다. 어깨가 들어간다. 금은 손 하나 폭이었다. 몸이 들어간다. 빛 속으로. 빛 속은 차갑다.`,
        dieText:`바닥에 금이 있다. 금 사이로 빛이 난다. 노랗다.<br><br>금 아래 반짝이는 것이 조금 더 쌓였다.<br>쌓인 것 가운데 하나가 반지다. 이쪽이 끼던 반지다.` },
      ok:`손을 넣기 직전 빛을 봤다. 빛이 손 그림자를 먹는다. 그림자가 없다. 빛이 아래에서 위로 비추는데.<br><br>손 대신 막대를 넣었다. 막대 끝을 무언가 쥔다. 수많은 손톱이 막대를 긁는 소리. 막대를 놓았다. 빨려 들어갔다.<br>금이 닫힌다. 빛이 꺼졌다. 금 옆에 튕겨 나온 것 하나가 남았다. 꿈결이다. 그것만 주웠다.`,
      win:{ exp:24, dream:4 } },
    { l:'③ 금의 결을 읽어 빛이 없는 끝을 연다.', k:'sense', dc:22,
      ok:`빛은 금 가운데서 난다. 금 끝은 어둡다. 끝을 손가락으로 쓸었다. 돌이 얇다.<br><br>빛이 없는 끝을 들었다. 작은 틈. 안에 기름종이 꾸러미. 빛과 상관없는 것이다. 먼저 온 누군가가 빛을 보고 놀라 버리고 간 짐이다.<br>말린 고기와 약초 뭉치가 들어 있었다. 빛 쪽은 끝까지 보지 않았다.`,
      ng:`끝을 들었는데 금 전체가 기운다. 빛이 끝 쪽으로 흘러온다.<br><br>빛이 손등을 덮는다. 손등 살갗이 하얗게 언다. 빛은 뜨거운 게 아니었다.<br>손을 뺐다. 손등에 서리가 앉았다. 오래 녹지 않았다.`,
      win:{ exp:18, dream:2, item:'약초 뭉치' }, lose:{ hp:-24, spirit:-22 } }
  ] }
]);
